var nodes = /* @__PURE__ */ new Map();
var options = /* @__PURE__ */ new Map();
BUILTIN_NODES.forEach((node) => {
  nodes.set(node.id, node);
});
function registerNode(def) {
  if (nodes.has(def.id)) {
    throw new Error(`[node-registry] \u8282\u70B9 "${def.id}" \u5DF2\u5B58\u5728\uFF0C\u65E0\u6CD5\u91CD\u590D\u6CE8\u518C`);
  }
  nodes.set(def.id, def);
}
function registerNodeOption(kb) {
  const node = nodes.get(kb.node_id);
  if (!node) {
    throw new Error(
      `[node-registry] \u9009\u9879 "${kb.option_id}" \u6240\u5C5E\u8282\u70B9 "${kb.node_id}" \u4E0D\u5B58\u5728`
    );
  }
  if (!node.options.includes(kb.option_id)) {
    console.warn(
      `[node-registry] \u9009\u9879 "${kb.option_id}" \u672A\u5728\u8282\u70B9 "${kb.node_id}" \u7684\u9884\u5B9A\u4E49\u5217\u8868\u4E2D\uFF0C\u53EF\u80FD\u4E3A\u81EA\u5B9A\u4E49\u9009\u9879`
    );
  }
  options.set(kb.option_id, kb);
}
function getNode(id) {
  return nodes.get(id);
}
function getNodeOption(optionId) {
  return options.get(optionId);
}
function getAllNodes(category) {
  const all = Array.from(nodes.values());
  if (category) {
    return all.filter((n) => n.category === category);
  }
  return all;
}
function getRegisteredOptionCount() {
  return options.size;
}
function getDefaultSelections() {
  const selections = {};
  for (const node of nodes.values()) {
    if (node.required) {
      selections[node.id] = node.defaultOptionId;
    }
  }
  return selections;
}
function getDefaultSelectionsFull() {
  const selections = {};
  for (const node of nodes.values()) {
    selections[node.id] = node.defaultOptionId;
  }
  return selections;
}
function getNodesByCategory(category) {
  return getAllNodes(category);
}
function validateSelectionsComplete(selections) {
  const missing = [];
  for (const node of nodes.values()) {
    if (node.required && !selections[node.id]) {
      missing.push(node.id);
    }
  }
  return { complete: missing.length === 0, missingNodes: missing };
}
function _resetRegistry() {
  nodes.clear();
  options.clear();
  BUILTIN_NODES.forEach((node) => nodes.set(node.id, node));
}

