function applyViolationPenalty(baseScore, violations) {
  let penalty = 0;
  for (const v of violations) {
    switch (v.severity) {
      case "error":
        penalty += 10;
        break;
      case "warning":
        penalty += 3;
        break;
      case "info":
        penalty += 1;
        break;
    }
  }
  return baseScore - Math.min(penalty, 40);
}
