function checkRepetition(text, violations) {
  const paragraphs = text.split(/\n+/).map((p) => p.trim()).filter((p) => p.length > 8);
  const seen = /* @__PURE__ */ new Map();
  for (let i = 0; i < paragraphs.length; i++) {
    const p = paragraphs[i];
    if (seen.has(p)) {
      violations.push({
        ruleId: "repetition",
        ruleName: "\u91CD\u590D\u6BB5\u843D",
        message: `\u7B2C${i + 1}\u6BB5\u548C\u7B2C${seen.get(p) + 1}\u6BB5\u5B8C\u5168\u91CD\u590D\uFF0C\u8FD9\u662F\u4E25\u91CD\u9519\u8BEF`,
        severity: "error",
        suggestion: "\u5220\u9664\u91CD\u590D\u6BB5\u843D\uFF0C\u68C0\u67E5\u662F\u4E0D\u662F\u590D\u5236\u7C98\u8D34\u9519\u8BEF\u3002\u8BFB\u8005\u770B\u5230\u91CD\u590D\u5185\u5BB9\u4F1A\u76F4\u63A5\u51FA\u620F\uFF0C\u751A\u81F3\u4EE5\u4E3A\u662FAI\u751F\u6210\u7684\u5783\u573E\u3002"
      });
    } else {
      seen.set(p, i);
    }
  }
  const sentences = [];
  const sentenceRegex = /[^。！？!?\n]+[。！？!?]?/g;
  let m;
  while ((m = sentenceRegex.exec(text)) !== null) {
    const s = m[0].trim();
    if (s.length > 10) sentences.push(s);
  }
  for (let i = 1; i < sentences.length; i++) {
    const prev = sentences[i - 1];
    const curr = sentences[i];
    let sameChars = 0;
    const minLen = Math.min(prev.length, curr.length);
    for (let j = 0; j < minLen; j++) {
      if (prev[j] === curr[j]) sameChars++;
    }
    const similarity = sameChars / Math.max(prev.length, curr.length);
    if (similarity > 0.75 && prev.length > 15 && curr.length > 15) {
      violations.push({
        ruleId: "repetition_sentence",
        ruleName: "\u53E5\u5B50\u91CD\u590D\u5570\u55E6",
        message: `\u8FDE\u7EED\u4E24\u53E5\u9AD8\u5EA6\u76F8\u4F3C\uFF08\u76F8\u4F3C\u5EA6${(similarity * 100).toFixed(0)}%\uFF09\uFF0C\u5185\u5BB9\u5728\u91CD\u590D`,
        severity: "warning",
        suggestion: "\u5220\u6389\u5176\u4E2D\u4E00\u53E5\uFF0C\u6216\u8005\u628A\u4E24\u53E5\u8BDD\u5408\u5E76\u6210\u4E00\u53E5\u63A8\u8FDB\u4FE1\u606F\u3002\u4E0D\u8981\u4E00\u53E5\u8BDD\u7FFB\u6765\u8986\u53BB\u8BF4\u3002"
      });
      break;
    }
  }
}
