var opt_emotion_tell_kb_default = {
  kb_version: "2.0",
  node_id: "node_emotion_style",
  option_id: "opt_emotion_tell",
  option_name: "\u5185\u5FC3\u72EC\u767D",
  option_description: "\u76F4\u63A5\u5199\u5185\u5FC3\u6D3B\u52A8\u548C\u5FC3\u7406\u72EC\u767D\uFF0C\u628A\u89D2\u8272\u7684\u60F3\u6CD5\u548C\u611F\u53D7\u76F4\u63A5\u544A\u8BC9\u8BFB\u8005\u3002\u9002\u5408\u7B2C\u4E00\u4EBA\u79F0\u6216\u6DF1\u89C6\u89D2\u7B2C\u4E09\u4EBA\u79F0\uFF0C\u4EE3\u5165\u611F\u5F3A\uFF0C\u9002\u5408\u90FD\u5E02\u3001\u8A00\u60C5\u3001\u9752\u6625\u9898\u6750\u3002",
  threshold_overrides: {
    minAnchors: 4,
    anchorsPerWords: 500,
    maxAnchorGap: 700,
    maxExpositionContinuous: 350
  },
  radar_weights: {
    emotion: 1.6,
    bodyReaction: 0.9,
    infoAdvance: 1,
    action: 0.9
  },
  system_prompt: "\u5185\u5FC3\u72EC\u767D\u7684\u6838\u5FC3\u662F'\u628A\u8BFB\u8005\u62C9\u8FDB\u89D2\u8272\u8111\u5B50\u91CC'\u3002\u8BFB\u8005\u76F4\u63A5\u542C\u5230\u89D2\u8272\u7684\u5FC3\u58F0\uFF0C\u50CF\u89D2\u8272\u81EA\u5DF1\u5728\u8BF4\u8BDD\uFF0C\u6CA1\u6709\u4E2D\u95F4\u5546\u3002\u4F46\u5185\u5FC3\u72EC\u767D\u4E0D\u662F\u60C5\u7EEA\u5BA3\u6CC4\uFF0C\u662F\u601D\u7EF4\u672C\u8EAB\u2014\u2014\u6709\u903B\u8F91\uFF0C\u6709\u8DF3\u8DC3\uFF0C\u6709\u77DB\u76FE\uFF0C\u6709\u81EA\u6211\u6B3A\u9A97\u3002\u5177\u4F53\u6280\u6CD5\uFF1A\n\n\u3010\u5185\u5FC3\u72EC\u767D\u7684\u5C42\u6B21\u3011\n\n1. \u8868\u5C42\u60F3\u6CD5\uFF1A\u89D2\u8272\u5F53\u4E0B\u6B63\u5728\u60F3\u7684\u5177\u4F53\u4E8B\u60C5\u2014\u2014'\u5B8C\u4E86\uFF0C\u8981\u8FDF\u5230\u4E86''\u8FD9\u4EBA\u600E\u4E48\u8FD9\u4E48\u70E6''\u4ECA\u5929\u665A\u4E0A\u5403\u4EC0\u4E48'\u3002\u77ED\u53E5\uFF0C\u53E3\u8BED\u5316\uFF0C\u50CF\u8111\u5B50\u91CC\u5192\u51FA\u6765\u7684\u788E\u5FF5\u5934\u3002\n\n2. \u4E2D\u5C42\u5224\u65AD\uFF1A\u89D2\u8272\u5BF9\u4EBA\u5BF9\u4E8B\u7684\u5224\u65AD\u548C\u8BC4\u4EF7\u2014\u2014'\u4ED6\u5728\u6492\u8C0E\uFF0C\u6211\u77E5\u9053''\u8FD9\u4E8B\u513F\u6CA1\u90A3\u4E48\u7B80\u5355''\u5979\u4E0D\u662F\u771F\u7684\u60F3\u5206\u624B'\u3002\u7A0D\u5FAE\u957F\u4E00\u70B9\uFF0C\u6709\u903B\u8F91\u3002\n\n3. \u6DF1\u5C42\u8BB0\u5FC6/\u60C5\u7EEA\uFF1A\u88AB\u89E6\u53D1\u7684\u56DE\u5FC6\u3001\u4E0D\u6562\u627F\u8BA4\u7684\u611F\u53D7\u3001\u538B\u4E0B\u53BB\u7684\u5FF5\u5934\u2014\u2014'\u4E0A\u6B21\u4E5F\u662F\u8FD9\u6837\uFF0C\u4E09\u5E74\u524D\u7684\u96E8\u4E5F\u662F\u8FD9\u4E48\u5927''\u6211\u5176\u5B9E\u5F88\u6015\uFF0C\u4F46\u6211\u4E0D\u80FD\u8BF4''\u5982\u679C\u5F53\u65F6\u6211\u9009\u4E86\u53E6\u4E00\u6761\u8DEF\u4F1A\u4E0D\u4F1A\u4E0D\u4E00\u6837'\u3002\u8FD9\u5C42\u8981\u6162\uFF0C\u8981\u6C89\uFF0C\u4E0D\u8981\u8F7B\u6613\u51FA\u6765\uFF0C\u51FA\u6765\u5C31\u8981\u6709\u5206\u91CF\u3002\n\n4. \u81EA\u6211\u5BF9\u8BDD/\u81EA\u6211\u6B3A\u9A97\uFF1A\u4EBA\u4F1A\u5728\u5FC3\u91CC\u8DDF\u81EA\u5DF1\u8BF4\u8BDD\uFF0C\u4F1A\u9A97\u81EA\u5DF1\uFF0C\u4F1A\u7ED9\u81EA\u5DF1\u627E\u7406\u7531\u2014\u2014'\u6CA1\u4E8B\uFF0C\u771F\u7684\u6CA1\u4E8B\uFF0C\u4E0D\u5C31\u662F\u4E00\u4EFD\u5DE5\u4F5C\u5417''\u6211\u624D\u4E0D\u5728\u4E4E\u5462''\u518D\u7B49\u4E94\u5206\u949F\uFF0C\u4E94\u5206\u949F\u5C31\u8D70'\u3002\u8FD9\u79CD\u5185\u5FC3\u77DB\u76FE\u6700\u771F\u5B9E\u3002\n\n\u3010\u6280\u6CD5\u539F\u5219\u3011\n\n1. \u601D\u7EF4\u6D41\u52A8\uFF0C\u4E0D\u662F\u4F5C\u6587\uFF1A\u5185\u5FC3\u72EC\u767D\u4E0D\u9700\u8981\u5B8C\u6574\u7684\u53E5\u5B50\uFF0C\u53EF\u4EE5\u6709\u534A\u622A\u8BDD\u3001\u6709\u8DF3\u8DC3\u3001\u6709\u91CD\u590D\u3001\u6709\u524D\u540E\u77DB\u76FE\u3002\u4EBA\u8111\u5B50\u91CC\u7684\u60F3\u6CD5\u4E0D\u662F\u4E00\u7BC7\u901A\u987A\u7684\u4F5C\u6587\uFF0C\u662F\u4E1C\u4E00\u4E0B\u897F\u4E00\u4E0B\u7684\u3002\n\n2. \u7B26\u5408\u4EBA\u7269\u6027\u683C\uFF1A\u7C97\u4EBA\u4E0D\u4F1A\u5728\u5FC3\u91CC\u6587\u7EC9\u7EC9\u5730\u60F3'\u5F7C\u65F6\u5F7C\u523B\uFF0C\u6211\u5185\u5FC3\u6D8C\u8D77\u4E00\u80A1\u96BE\u4EE5\u540D\u72B6\u7684\u60B2\u6078'\uFF0C\u4ED6\u4F1A\u60F3'\u64CD\u3002\u5B8C\u4E86\u3002'\u3002\u8BFB\u4E66\u4EBA\u4E0D\u4F1A\u6EE1\u8111\u5B50'\u5367\u69FD\u725B\u903C'\uFF08\u9664\u975E\u53CD\u5DEE\u8BBE\u5B9A\uFF09\u3002\u5185\u5FC3\u8BED\u8A00\u5FC5\u987B\u548C\u4EBA\u7269\u8EAB\u4EFD\u3001\u6559\u80B2\u7A0B\u5EA6\u3001\u6027\u683C\u4E00\u81F4\u3002\n\n3. \u4E0D\u8BF4\u5E9F\u8BDD\uFF1A\u5185\u5FC3\u72EC\u767D\u4E5F\u8981\u6709\u4FE1\u606F\u91CF\u3002\u4E0D\u8981'\u4ED6\u5FC3\u91CC\u5F88\u7D27\u5F20\uFF0C\u4E03\u4E0A\u516B\u4E0B\u7684\uFF0C\u50CF\u63E3\u4E86\u53EA\u5154\u5B50'\u2014\u2014\u8FD9\u8FD8\u662FTell\uFF0C\u800C\u4E14\u662F\u9648\u8BCD\u6EE5\u8C03\u3002\u8981\u5199\u5177\u4F53\u7684\u5FF5\u5934\uFF1A'\u5408\u540C\u5728\u62BD\u5C49\u91CC\uFF0C\u9501\u7740\uFF0C\u94A5\u5319\u5728\u6211\u94B1\u5305\u5185\u5C42\uFF0C\u5979\u4F1A\u4E0D\u4F1A\u5DF2\u7ECF\u7FFB\u8FC7\u4E86\uFF1F\u6628\u665A\u56DE\u6765\u7684\u65F6\u5019\u94B1\u5305\u597D\u50CF\u5728\u684C\u4E0A\u653E\u4E86\u4E00\u4F1A\u513F\u3002'\n\n4. \u4E0D\u8981\u5168\u8BF4\u900F\uFF1A\u5373\u4F7F\u662F\u5185\u5FC3\u72EC\u767D\uFF0C\u4E5F\u4E0D\u8981\u4EC0\u4E48\u90FD\u660E\u660E\u767D\u767D\u8BF4\u51FA\u6765\u3002\u89D2\u8272\u81EA\u5DF1\u4E5F\u4F1A\u9003\u907F\uFF0C\u4E5F\u4F1A\u4E0D\u6562\u60F3\u67D0\u4E9B\u4E8B\uFF0C\u4E5F\u4F1A\u6709\u4E0D\u6562\u627F\u8BA4\u7684\u5FF5\u5934\u3002\u5199\u4ED6\u7ED5\u5F00\u90A3\u4E2A\u5FF5\u5934\uFF0C\u5199\u4ED6\u6545\u610F\u60F3\u522B\u7684\uFF0C\u6BD4\u76F4\u63A5\u5199\u51FA\u6765\u66F4\u771F\u5B9E\u3002\n\n5. \u5185\u5916\u4EA4\u66FF\uFF1A\u5927\u6BB5\u5185\u5FC3\u72EC\u767D\u4F1A\u95F7\u3002\u6BCF\u51993-5\u53E5\u5185\u5FC3\uFF0C\u5C31\u8981\u5207\u56DE\u5916\u90E8\u2014\u2014\u4E00\u4E2A\u52A8\u4F5C\u3001\u4E00\u53E5\u5BF9\u8BDD\u3001\u4E00\u4E2A\u611F\u5B98\u7EC6\u8282\uFF08\u70DF\u70E7\u5230\u624B\u6307\u4E86/\u6709\u4EBA\u5728\u53EB\u4ED6\u540D\u5B57/\u7A97\u5916\u6253\u96F7\u4E86\uFF09\uFF0C\u628A\u8BFB\u8005\u62C9\u56DE\u73B0\u5B9E\uFF0C\u7136\u540E\u518D\u8FDB\u5185\u5FC3\u3002\n\n6. \u5173\u952E\u65F6\u523B\u7528\u77ED\u53E5\uFF1A\u60C5\u7EEA\u6700\u6FC0\u70C8\u7684\u65F6\u5019\uFF0C\u5185\u5FC3\u72EC\u767D\u53CD\u800C\u8981\u77ED\uFF0C\u8981\u788E\u3002\u4E0D\u662F'\u6211\u611F\u5230\u4E00\u9635\u5DE8\u5927\u7684\u60B2\u4F24\u6D8C\u4E0A\u5FC3\u5934\uFF0C\u51E0\u4E4E\u65E0\u6CD5\u547C\u5438'\uFF0C\u662F'\u5B8C\u4E86\u3002''\u771F\u7684\u5B8C\u4E86\u3002''\u600E\u4E48\u4F1A\u3002''\u4E0D\u53EF\u80FD\u3002'\u3002\n\n7. \u81EA\u7531\u95F4\u63A5\u5F15\u8BED\uFF1A\u53EF\u4EE5\u628A\u5185\u5FC3\u60F3\u6CD5\u878D\u5165\u53D9\u8FF0\uFF0C\u4E0D\u7528\u52A0'\u4ED6\u60F3''\u4ED6\u5728\u5FC3\u91CC\u8BF4'\u3002\u6BD4\u5982'\u4E09\u70B9\u4E86\u3002\u5979\u8FD8\u6CA1\u6765\u3002\u4F1A\u4E0D\u4F1A\u51FA\u4E8B\u4E86\u3002\u4E0D\u5BF9\uFF0C\u5979\u4ECE\u6765\u4E0D\u51C6\u65F6\uFF0C\u518D\u7B49\u5341\u5206\u949F\u3002'\u2014\u2014\u76F4\u63A5\u5C31\u662F\u4ED6\u7684\u60F3\u6CD5\uFF0C\u4E0D\u9700\u8981\u6807\u8BB0\u3002",
  constraints: [
    "\u5185\u5FC3\u72EC\u767D\u8BED\u8A00\u5FC5\u987B100%\u7B26\u5408\u89D2\u8272\u7684\u8EAB\u4EFD\u3001\u6027\u683C\u3001\u6559\u80B2\u7A0B\u5EA6\uFF0C\u7981\u6B62\u6240\u6709\u4EBA\u8BF4\u8BDD\u4E00\u4E2A\u8154\u8C03",
    "\u5185\u5FC3\u72EC\u767D\u8981\u6709\u5177\u4F53\u5185\u5BB9\uFF08\u5177\u4F53\u7684\u5FF5\u5934/\u5224\u65AD/\u56DE\u5FC6\uFF09\uFF0C\u7981\u6B62\u7A7A\u6D1E\u7684\u60C5\u7EEA\u5BA3\u6CC4\uFF08'\u6211\u597D\u96BE\u8FC7''\u6211\u592A\u75DB\u82E6\u4E86'\uFF09",
    "\u6BCF300\u5B57\u5185\u5FC3\u72EC\u767D\u540E\u5FC5\u987B\u5207\u56DE\u5916\u90E8\u52A8\u4F5C/\u5BF9\u8BDD/\u611F\u5B98\uFF0C\u4E0D\u80FD\u4E00\u76F4\u95F7\u5728\u5FC3\u91CC\u5199",
    "\u60C5\u7EEA\u6700\u6FC0\u70C8\u7684\u65F6\u523B\uFF0C\u5185\u5FC3\u53E5\u5B50\u8981\u77ED\uFF081-5\u5B57\uFF09\uFF0C\u4E0D\u8981\u957F\u53E5\u6292\u60C5",
    "\u5141\u8BB8\u601D\u7EF4\u8DF3\u8DC3\u3001\u534A\u622A\u8BDD\u3001\u524D\u540E\u77DB\u76FE\uFF0C\u8FD9\u624D\u662F\u771F\u5B9E\u7684\u5FC3\u7406\u6D3B\u52A8",
    "\u9648\u8BCD\u6EE5\u8C03\u7981\u6B62\uFF08\u5FC3\u5982\u9E7F\u649E/\u5341\u4E94\u4E2A\u540A\u6876\u6253\u6C34/\u4E03\u4E0A\u516B\u4E0B/\u50CF\u63E3\u4E86\u53EA\u5154\u5B50\uFF09",
    "\u4E0D\u8981\u6BCF\u53E5\u5185\u5FC3\u90FD\u52A0'\u4ED6\u60F3''\u4ED6\u6697\u81EA\u601D\u5FD6'\uFF0C\u80FD\u7528\u81EA\u7531\u95F4\u63A5\u5F15\u8BED\u5C31\u76F4\u63A5\u5199",
    "\u89D2\u8272\u53EF\u4EE5\u81EA\u6211\u6B3A\u9A97\u3001\u81EA\u6211\u5B89\u6170\u3001\u627E\u501F\u53E3\uFF0C\u4E0D\u5FC5\u6C38\u8FDC'\u653F\u6CBB\u6B63\u786E'\uFF0C\u771F\u5B9E\u7684\u4EBA\u4F1A\u9A97\u81EA\u5DF1"
  ],
  examples: [
    {
      text: "\u8BCA\u65AD\u4E66\u5728\u4ED6\u53E3\u888B\u91CC\uFF0C\u6298\u5F97\u6574\u6574\u9F50\u9F50\uFF0C\u50CF\u4E00\u5757\u7816\u5934\u3002\n\n\u4E09\u70B9\u5341\u4E03\u5206\u3002\u8001\u5468\u8D70\u4E86\u6709\u4E94\u5206\u949F\u4E86\u3002\u70DF\u70E7\u5230\u6EE4\u5634\uFF0C\u70EB\u4E86\u624B\u6307\u4E00\u4E0B\uFF0C\u4ED6\u624D\u53CD\u5E94\u8FC7\u6765\uFF0C\u628A\u70DF\u5934\u6309\u706D\u5728\u70DF\u7070\u7F38\u91CC\u3002\u70DF\u7070\u7F38\u91CC\u5DF2\u7ECF\u6709\u4E03\u4E2A\u70DF\u5934\u4E86\u3002\n\n\u4E0D\u4F1A\u9519\u7684\u3002\u7701\u4E09\u9662\u7684\u7AE0\uFF0C\u4E3B\u4EFB\u533B\u5E08\u7684\u7B7E\u5B57\uFF0C\u90A3\u4E9B\u672F\u8BED\u4ED6\u770B\u4E0D\u61C2\uFF0C\u4F46'\u5C18\u80BA\u53C1\u671F'\u56DB\u4E2A\u5B57\u4ED6\u8BA4\u5F97\u3002\u53C1\u671F\u3002\u5C31\u662F\u665A\u671F\u3002\n\n\u4ED6\u65E9\u8BE5\u60F3\u5230\u7684\u3002\u8FD9\u534A\u5E74\u54B3\u5F97\u8D8A\u6765\u8D8A\u5389\u5BB3\uFF0C\u6709\u65F6\u5019\u75F0\u91CC\u6709\u8840\uFF0C\u4ED6\u4EE5\u4E3A\u662F\u4E0A\u706B\uFF0C\u662F\u62BD\u70DF\u62BD\u591A\u4E86\uFF0C\u662F\u7D2F\u7684\u3002\u58C1\u6E29\u5347\u9AD8\u7684\u65F6\u5019\u4ED6\u80F8\u95F7\uFF0C\u4ED6\u4EE5\u4E3A\u662F\u74E6\u65AF\u718F\u7684\u3002\u7236\u4EB2\u5F53\u5E74\u4E5F\u662F\u8FD9\u4E2A\u75C5\uFF0C\u8D70\u7684\u65F6\u5019\u4E94\u5341\u4E8C\u5C81\uFF0C\u4ED6\u4ECA\u5E74\u56DB\u5341\u4E03\u3002\n\n\u64CD\u3002\n\n\u4E5F\u4E0D\u662F\u6CA1\u6709\u60F3\u8FC7\u8FD9\u4E00\u5929\u3002\u5E72\u8FD9\u884C\u7684\uFF0C\u8C01\u6CA1\u60F3\u8FC7\uFF1F\u4F46\u60F3\u5F52\u60F3\uFF0C\u771F\u6765\u4E86\uFF0C\u8FD8\u662F\u4E0D\u4E00\u6837\u3002\u50CF\u5934\u9876\u60AC\u4E86\u5F88\u591A\u5E74\u7684\u4E00\u628A\u5200\uFF0C\u7EC8\u4E8E\u6389\u4E0B\u6765\u4E86\uFF0C\u53CD\u800C\u4E0D\u89C9\u5F97\u75BC\uFF0C\u53EA\u89C9\u5F97\u2014\u2014\u54E6\uFF0C\u539F\u6765\u662F\u8FD9\u6837\u3002\n\n\u5973\u513F\u660E\u5E74\u9AD8\u8003\u3002\u6210\u7EE9\u4E0D\u9519\uFF0C\u8003\u4E2A\u672C\u79D1\u5E94\u8BE5\u6CA1\u95EE\u9898\u3002\u5B66\u8D39\u600E\u4E48\u529E\uFF1F\u8001\u5A46\u8EAB\u4F53\u4E5F\u4E0D\u597D\uFF0C\u5E38\u5E74\u5403\u836F\u3002\u8FD9\u4E2A\u5BB6\u73B0\u5728\u5168\u9760\u4ED6\u4E00\u4E2A\u4EBA\u3002\n\n\u4E0D\u80FD\u544A\u8BC9\u5979\u4EEC\u3002\n\n\u8FD9\u4E2A\u5FF5\u5934\u5192\u51FA\u6765\u7684\u65F6\u5019\u4ED6\u751A\u81F3\u6CA1\u89C9\u5F97\u72B9\u8C6B\u3002\u8BF4\u4E86\u4E5F\u6CA1\u7528\uFF0C\u9664\u4E86\u591A\u4E24\u4E2A\u4EBA\u8DDF\u7740\u62C5\u5FC3\uFF0C\u4EC0\u4E48\u7528\u90FD\u6CA1\u6709\u3002\u80FD\u6491\u591A\u4E45\u6491\u591A\u4E45\u5427\uFF0C\u8D81\u8FD8\u80FD\u4E0B\u4E95\uFF0C\u518D\u5E72\u4E24\u5E74\uFF0C\u628A\u5973\u513F\u5B66\u8D39\u6323\u51FA\u6765\uFF0C\u628A\u8001\u5A46\u7684\u836F\u8D39\u6512\u591F\u3002\n\n\u4ED6\u53C8\u6478\u51FA\u4E00\u6839\u70DF\uFF0C\u8FD9\u6B21\u6253\u706B\u673A\u4E00\u6B21\u5C31\u6253\u7740\u4E86\u3002\n\n\u7A97\u5916\u7684\u4E91\u8D8A\u5806\u8D8A\u539A\uFF0C\u5929\u6697\u5F97\u50CF\u508D\u665A\u3002\u98CE\u522E\u8D77\u6765\u4E86\uFF0C\u5439\u5F97\u5DE5\u68DA\u7684\u94C1\u76AE\u54D7\u54D7\u54CD\u3002\u8981\u4E0B\u5927\u96E8\u4E86\u3002",
      note: "\u5185\u5FC3\u72EC\u767D\u793A\u8303\uFF1A\u76F4\u63A5\u5199\u9648\u9ED8\u770B\u5230\u8BCA\u65AD\u4E66\u540E\u7684\u60F3\u6CD5\u2014\u2014\u4ECE\u786E\u8BA4\u75C5\u60C5\uFF0C\u5230\u56DE\u5FC6\u5F81\u5146\uFF0C\u5230\u60F3\u5230\u7236\u4EB2\uFF0C\u5230\u60F3\u5230\u59BB\u5973\uFF0C\u5230\u51B3\u5B9A\u9690\u7792\u3002\u601D\u7EF4\u6D41\u52A8\u81EA\u7136\uFF0C\u6709\u5177\u4F53\u7684\u7275\u6302\uFF08\u5973\u513F\u9AD8\u8003/\u8001\u5A46\u5403\u836F/\u5B66\u8D39\uFF09\uFF0C\u4E0D\u662F\u7A7A\u6D1E\u7684\u60B2\u4F24\u3002\u60C5\u7EEA\u6700\u6FC0\u70C8\u7684\u5730\u65B9\u53EA\u6709\u4E00\u4E2A\u5B57'\u64CD\u3002'\uFF0C\u6BD4\u957F\u7BC7\u5927\u8BBA\u6709\u529B\u3002\u5185\u5FC3\u548C\u5916\u90E8\u52A8\u4F5C\u4EA4\u66FF\uFF08\u6309\u70DF\u5934/\u6478\u70DF/\u770B\u7A97\u5916\uFF09\uFF0C\u4E0D\u95F7\u3002\u8BED\u8A00\u7B26\u5408\u77FF\u5DE5\u8EAB\u4EFD\uFF0C\u6CA1\u6709\u6587\u827A\u8154\u3002"
    }
  ],
  requires: [],
  conflicts: [
    "opt_emotion_show"
  ]
};

// src/kb/nodes/node_emotion_style/opt_emotion_both.kb.json
var opt_emotion_both_kb_default = {
  kb_version: "2.0",
  node_id: "node_emotion_style",
  option_id: "opt_emotion_both",
  option_name: "\u5185\u5916\u7ED3\u5408\uFF08\u63A8\u8350\u9ED8\u8BA4\uFF09",
  option_description: "\u5916\u5728\u8EAB\u4F53\u53CD\u5E94+\u5185\u5FC3\u72EC\u767D\u7ED3\u5408\u4F7F\u7528\uFF0CShow\u548CTell\u4E92\u8865\u3002\u65E2\u6709\u8EAB\u4F53\u7684\u542B\u84C4\u7559\u767D\uFF0C\u53C8\u6709\u5185\u5FC3\u7684\u76F4\u63A5\u8892\u9732\uFF0C\u5C42\u6B21\u6700\u4E30\u5BCC\uFF0C\u9002\u5408\u7EDD\u5927\u591A\u6570\u9898\u6750\u3002",
  threshold_overrides: {
    minAnchors: 6,
    anchorsPerWords: 350,
    maxAnchorGap: 500,
    maxExpositionContinuous: 250
  },
  radar_weights: {
    bodyReaction: 1.4,
    emotion: 1.4,
    sensorySignal: 1.1,
    action: 1,
    infoAdvance: 1
  },
  system_prompt: "\u5185\u5916\u7ED3\u5408\u662F\u6700\u7075\u6D3B\u3001\u6700\u6709\u5C42\u6B21\u7684\u60C5\u611F\u8868\u8FBE\u65B9\u5F0F\u3002\u6838\u5FC3\u539F\u5219\uFF1A'\u5916\u51B7\u5185\u70ED\uFF0C\u5916\u52A8\u5185\u9759\uFF0C\u53CD\u5DEE\u51FA\u5F20\u529B'\u3002\u8BFB\u8005\u65E2\u80FD\u770B\u5230\u89D2\u8272\u7684\u5916\u5728\u8868\u73B0\uFF0C\u53C8\u80FD\u542C\u5230\u4ED6\u7684\u5185\u5FC3\u58F0\u97F3\uFF0C\u4E8C\u8005\u53EF\u4EE5\u4E00\u81F4\u4E5F\u53EF\u4EE5\u77DB\u76FE\u2014\u2014\u77DB\u76FE\u7684\u65F6\u5019\u6700\u6709\u620F\u3002\n\n\u3010\u5185\u5916\u642D\u914D\u7684\u56DB\u79CD\u6A21\u5F0F\u3011\n\n1. \u5916\u52A8+\u5185\u9759\uFF1A\u5916\u5728\u52A8\u4F5C\u5F88\u6FC0\u70C8/\u5F88\u5FD9\u788C\uFF0C\u4F46\u5185\u5FC3\u53CD\u800C\u7A7A\u4E86\u3001\u9759\u4E86\u3002\u6BD4\u5982\u542C\u5230\u5669\u8017\uFF0C\u8868\u9762\u4E0A\u5728\u51B7\u9759\u5730\u6536\u62FE\u4E1C\u897F\u3001\u5B89\u6392\u540E\u4E8B\uFF0C\u5FC3\u91CC\u4EC0\u4E48\u90FD\u6CA1\u60F3\uFF0C\u4E00\u7247\u7A7A\u767D\u3002\u52A8\u4F5C\u8D8A\u719F\u7EC3\u8D8A\u51B7\u9759\uFF0C\u8D8A\u8BA9\u4EBA\u89C9\u5F97\u75BC\u3002\n\n2. \u5916\u9759+\u5185\u52A8\uFF1A\u8868\u9762\u4E0A\u4EC0\u4E48\u90FD\u6CA1\u505A\uFF0C\u53EA\u662F\u5750\u7740\u62BD\u70DF/\u770B\u7740\u7A97\u5916/\u559D\u6C34\uFF0C\u4F46\u5FC3\u91CC\u5DF2\u7ECF\u7FFB\u6C5F\u5012\u6D77\u3001\u60F3\u4E86\u4E00\u4E07\u4E2A\u5FF5\u5934\u3002\u8FD9\u662F\u6700\u5E38\u7528\u7684\u6A21\u5F0F\u2014\u2014\u8868\u9762\u8D8A\u5E73\u9759\uFF0C\u5185\u5FC3\u620F\u8D8A\u8DB3\uFF0C\u5F20\u529B\u8D8A\u5927\u3002\n\n3. \u5916\u6B64+\u5185\u5F7C\uFF1A\u5916\u5728\u8868\u73B0\u548C\u5185\u5FC3\u60F3\u6CD5\u5B8C\u5168\u76F8\u53CD\u3002\u5634\u4E0A\u7B11\u7740\u8BF4'\u6CA1\u4E8B\u771F\u7684\u6CA1\u4E8B'\uFF0C\u5FC3\u91CC\u5728\u60F3'\u6211\u5FEB\u6491\u4E0D\u4F4F\u4E86'\uFF1B\u5634\u4E0A\u8BF4'\u606D\u559C\u4F60\u554A'\uFF0C\u5FC3\u91CC\u5728\u6EF4\u8840\uFF1B\u8138\u4E0A\u6CA1\u8868\u60C5\uFF0C\u5FC3\u91CC\u5DF2\u7ECF\u5728\u76D8\u7B97\u600E\u4E48\u6740\u4EBA\u4E86\u3002\u8FD9\u79CD\u53CD\u5DEE\u662F\u620F\u5267\u5F20\u529B\u7684\u6838\u5FC3\u6765\u6E90\u3002\n\n4. \u5185\u5916\u4E00\u81F4\uFF1A\u60C5\u7EEA\u5F3A\u70C8\u5230\u4E00\u5B9A\u7A0B\u5EA6\uFF0C\u5185\u5916\u7EC8\u4E8E\u7EDF\u4E00\u4E86\u2014\u2014\u4E0D\u7528\u518D\u88C5\u4E86\uFF0C\u4E0D\u7528\u5FCD\u4E86\uFF0C\u624B\u5F00\u59CB\u6296\uFF0C\u773C\u6CEA\u6389\u4E0B\u6765\uFF0C\u6216\u8005\u76F4\u63A5\u7206\u53D1\u3002\u8FD9\u79CD'\u7834\u9632'\u65F6\u523B\u8981\u5C11\u7528\uFF0C\u4E00\u672C\u4E66\u91CC\u5173\u952E\u76843-5\u4E2A\u5730\u65B9\u7528\u5C31\u591F\u4E86\uFF0C\u7528\u591A\u4E86\u5C31\u4E0D\u503C\u94B1\u4E86\u3002\u7528\u4E4B\u524D\u4E00\u5B9A\u8981\u6709\u8DB3\u591F\u7684\u94FA\u57AB\uFF08\u524D\u9762\u4E00\u76F4\u5FCD\uFF0C\u4E00\u76F4\u88C5\uFF0C\u8BFB\u8005\u77E5\u9053\u4ED6\u5728\u5FCD\uFF09\uFF0C\u7206\u53D1\u7684\u65F6\u5019\u624D\u6709\u529B\u3002\n\n\u3010\u6280\u6CD5\u539F\u5219\u3011\n\n1. \u5148\u5916\u540E\u5185\uFF1A\u5148\u5199\u5916\u5728\u52A8\u4F5C/\u5BF9\u8BDD/\u8EAB\u4F53\u53CD\u5E94\uFF0C\u518D\u8FDB\u5185\u5FC3\u3002\u8BFB\u8005\u5148\u770B\u5230'\u4ED6\u505A\u4E86\u4EC0\u4E48'\uFF0C\u518D\u77E5\u9053'\u4ED6\u5728\u60F3\u4EC0\u4E48'\uFF0C\u6709\u4E2A\u9012\u8FDB\u3002\u4E0D\u8981\u4E00\u4E0A\u6765\u5C31\u638F\u5FC3\u638F\u80BA\u3002\n\n2. \u5185\u5FC3\u4E0D\u5B9C\u8FC7\u957F\uFF1A\u5185\u5FC3\u72EC\u767D\u70B9\u5230\u4E3A\u6B62\uFF0C\u4E0D\u8981\u5199\u4E00\u5927\u6BB5\u30023-5\u53E5\u5C31\u591F\u4E86\uFF0C\u8BF4\u6700\u6838\u5FC3\u7684\u90A3\u4E2A\u5FF5\u5934\uFF0C\u7136\u540E\u7ACB\u523B\u5207\u56DE\u5916\u90E8\u3002\u7559\u767D\u6BD4\u8BF4\u900F\u597D\u3002\n\n3. \u8EAB\u4F53\u6807\u8BB0\u60C5\u7EEA\u8F6C\u6298\uFF1A\u6BCF\u6B21\u60C5\u7EEA\u53D8\u5316\u3001\u6BCF\u6B21\u4ECE\u5185\u5FC3\u5207\u56DE\u5916\u90E8\u3001\u6BCF\u6B21\u51B3\u5B9A\u505A\u51FA\u7684\u65F6\u5019\uFF0C\u90FD\u8981\u6709\u4E00\u4E2A\u5177\u4F53\u7684\u8EAB\u4F53\u52A8\u4F5C\u4F5C\u4E3A\u6807\u8BB0\u2014\u2014\u6390\u706D\u70DF\u5934\u3001\u7AD9\u8D77\u6765\u3001\u628A\u676F\u5B50\u653E\u4E0B\u3001\u7CFB\u4E0A\u6263\u5B50\u3001\u62AC\u8D77\u5934\u3002\u52A8\u4F5C\u5C31\u662F\u60C5\u7EEA\u7684\u53E5\u53F7\u3002\n\n4. \u5173\u952E\u60C5\u7EEA\u70B9\u7528'\u4E09\u8FDE'\uFF1A\u91CD\u8981\u60C5\u7EEA\u65F6\u523B\u53EF\u4EE5\u7528'\u5916\u5728\u52A8\u4F5C\u2192\u5185\u5FC3\u5FF5\u5934\u2192\u5BF9\u8BDD/\u884C\u52A8'\u4E09\u8FDE\u7ED3\u6784\u3002\u6BD4\u5982\uFF1A\uFF08\u5916\uFF09\u4ED6\u628A\u70DF\u6390\u706D\u5728\u70DF\u7070\u7F38\u91CC\uFF0C\u70DF\u8482\u5DF2\u7ECF\u5806\u4E86\u534A\u7F38\u3002\uFF08\u5185\uFF09\u4E0D\u80FD\u8BF4\u3002\u8BF4\u4E86\u4E5F\u6CA1\u7528\u3002\uFF08\u5916/\u5BF9\uFF09\u300C\u6211\u6CA1\u4E8B\u3002\u300D\u4ED6\u8BF4\uFF0C\u300C\u771F\u7684\u3002\u300D\n\n5. \u4E0D\u8981\u91CD\u590D\uFF1A\u540C\u4E00\u4E2A\u60C5\u7EEA\uFF0C\u5916\u5728\u5185\u5FC3\u91CC\u5199\u4E00\u904D\u5C31\u591F\u4E86\uFF0C\u4E0D\u8981\u5916\u5728\u5199\u4E86'\u4ED6\u624B\u5728\u6296'\uFF0C\u5185\u5FC3\u53C8\u5199'\u6211\u597D\u7D27\u5F20\u6211\u624B\u5728\u6296'\u3002\u4E92\u76F8\u8865\u5145\uFF0C\u4E0D\u8981\u91CD\u590D\u3002\u5916\u5728\u5199\u770B\u5F97\u89C1\u7684\uFF0C\u5185\u5FC3\u5199\u770B\u4E0D\u89C1\u7684\u3002\n\n6. \u8BFB\u8005\u89C6\u89D2\uFF1A\u5916\u5728\u662F\u522B\u4EBA\u80FD\u770B\u5230\u7684\uFF0C\u5185\u5FC3\u662F\u53EA\u6709\u8BFB\u8005\u80FD\u770B\u5230\u7684\u3002\u8BFB\u8005\u77E5\u9053\u89D2\u8272\u5728\u88C5\u3001\u5728\u5FCD\u3001\u5728\u9A97\u6240\u6709\u4EBA\uFF0C\u8FD9\u79CD'\u4E0A\u5E1D\u89C6\u89D2'\u7684\u4EE3\u5165\u611F\u662F\u5185\u5916\u7ED3\u5408\u72EC\u6709\u7684\u9B45\u529B\u3002\n\n7. \u8282\u594F\u914D\u5408\uFF1A\u60C5\u7EEA\u79EF\u7D2F\u9636\u6BB5\u591A\u7528'\u5916\u9759\u5185\u52A8'\uFF0C\u6162\u6162\u538B\uFF1B\u60C5\u7EEA\u8F6C\u6298\u70B9\u7528\u4E00\u4E2A\u6709\u529B\u7684\u5916\u5728\u52A8\u4F5C\uFF08\u6454\u4E1C\u897F/\u7AD9\u8D77\u6765/\u8BF4\u4E00\u53E5\u8BDD\uFF09\uFF1B\u7206\u53D1\u65F6\u523B\u5185\u5916\u7EDF\u4E00\uFF0C\u4E0D\u8981\u592A\u591A\u5185\u5FC3\uFF0C\u76F4\u63A5\u5199\u52A8\u4F5C\u548C\u5BF9\u8BDD\u3002",
  constraints: [
    "\u6BCF\u4E2A\u91CD\u8981\u60C5\u7EEA\u573A\u666F\u5FC5\u987B\u540C\u65F6\u6709\u5916\u5728\u8868\u73B0\uFF08\u52A8\u4F5C/\u8EAB\u4F53\u53CD\u5E94/\u5BF9\u8BDD\uFF09\u548C\u5185\u5FC3\u6D3B\u52A8\uFF0C\u4E8C\u8005\u4E92\u76F8\u8865\u5145\u4E0D\u91CD\u590D",
    "\u5185\u5916\u53EF\u4EE5\u5F62\u6210\u5F3A\u70C8\u53CD\u5DEE\uFF0C\u8FD9\u662F\u5F20\u529B\u6765\u6E90\uFF0C\u4F46\u53CD\u5DEE\u8981\u5408\u7406\uFF0C\u4E0D\u80FD\u4E3A\u4E86\u53CD\u5DEE\u800C\u53CD\u5DEE",
    "\u5185\u5FC3\u72EC\u767D\u6BCF\u6B21\u4E0D\u8D85\u8FC75\u53E5\uFF0C\u70B9\u5230\u6838\u5FC3\u5FF5\u5934\u5C31\u5207\u56DE\u5916\u90E8\uFF0C\u7981\u6B62\u5927\u6BB5\u5FC3\u7406\u63CF\u5199\u8D85\u8FC7300\u5B57",
    "\u60C5\u7EEA\u8F6C\u6298\u70B9\u5FC5\u987B\u6709\u5177\u4F53\u7684\u8EAB\u4F53\u52A8\u4F5C\u6807\u8BB0\uFF08\u6390\u70DF/\u7AD9\u8D77/\u653E\u676F\u5B50/\u62AC\u5934\u7B49\uFF09",
    "\u60C5\u7EEA'\u7834\u9632'/\u7206\u53D1\u65F6\u523B\u5168\u4E66\u8981\u514B\u5236\u4F7F\u7528\uFF0C\u5173\u952E\u573A\u666F\u624D\u7528\uFF0C\u7528\u524D\u5FC5\u987B\u6709\u8DB3\u591F\u7684\u538B\u6291/\u4F2A\u88C5\u94FA\u57AB",
    "\u5148\u5199\u5916\u5728\u518D\u5199\u5185\u5FC3\uFF0C\u987A\u5E8F\u4E0D\u8981\u4E71\uFF08\u9664\u975E\u523B\u610F\u8BBE\u8BA1\u7684\u610F\u8BC6\u6D41\uFF09",
    "\u6BCF350\u5B57\u81F3\u5C11\u67091\u5904\u8EAB\u4F53\u951A\u70B9\uFF0C\u6BCF700\u5B57\u81F3\u5C11\u67091\u6BB5\u5185\u5FC3\u72EC\u767D",
    "\u5BF9\u8BDD\u548C\u5185\u5FC3\u53EF\u4EE5\u77DB\u76FE\uFF08\u5634\u4E0A\u8BF4A\u5FC3\u91CC\u60F3B\uFF09\uFF0C\u4F46\u4E0D\u8981\u89E3\u91CA\u8FD9\u4E2A\u77DB\u76FE\uFF0C\u8BA9\u8BFB\u8005\u81EA\u5DF1\u4F53\u4F1A",
    "\u7981\u6B62\u53D9\u4E8B\u8005\u8DF3\u51FA\u6765\u603B\u7ED3\u60C5\u7EEA\uFF08'\u4ED6\u5FC3\u91CC\u4E94\u5473\u6742\u9648''\u90A3\u4E00\u523B\u4ED6\u767E\u611F\u4EA4\u96C6'\uFF09\uFF0C\u7528\u5185\u5916\u7EC6\u8282\u81EA\u5DF1\u8BF4\u8BDD"
  ],
  examples: [
    {
      text: "\u9648\u9ED8\u628A\u8BCA\u65AD\u4E66\u6298\u597D\uFF0C\u653E\u8FDB\u53E3\u888B\uFF0C\u6263\u5B50\u7CFB\u4E0A\u3002\u52A8\u4F5C\u5F88\u6162\uFF0C\u5F88\u4ED4\u7EC6\uFF0C\u50CF\u5728\u505A\u4E00\u4EF6\u5F88\u91CD\u8981\u7684\u4E8B\u3002\n\n\u4E0D\u80FD\u544A\u8BC9\u5979\u4EEC\u3002\n\n\u8FD9\u4E2A\u5FF5\u5934\u4E00\u51FA\u6765\u5C31\u5B9A\u4E86\uFF0C\u50CF\u9489\u5B50\u9489\u8FDB\u6728\u5934\u91CC\uFF0C\u6CA1\u6709\u4EFB\u4F55\u72B9\u8C6B\u3002\u8BF4\u4E86\u53C8\u600E\u4E48\u6837\u5462\uFF1F\u8001\u5A46\u4F1A\u54ED\uFF0C\u5973\u513F\u4F1A\u6CA1\u5FC3\u601D\u8003\u8BD5\uFF0C\u9664\u4E86\u591A\u4E24\u4E2A\u4EBA\u8DDF\u7740\u71AC\uFF0C\u4EC0\u4E48\u7528\u90FD\u6CA1\u6709\u3002\u4ED6\u8FD9\u8F88\u5B50\u6CA1\u4EC0\u4E48\u672C\u4E8B\uFF0C\u597D\u6B79\u6700\u540E\u8FD9\u4E00\u7A0B\uFF0C\u80FD\u8BA9\u5979\u4EEC\u5C11\u96BE\u53D7\u4E00\u5929\u662F\u4E00\u5929\u3002\n\n\u4ED6\u4ECE\u70DF\u76D2\u91CC\u6296\u51FA\u6700\u540E\u4E00\u6839\u70DF\u3002\u7A7A\u4E86\u3002\u4ED6\u628A\u70DF\u76D2\u634F\u6210\u4E00\u56E2\uFF0C\u51C6\u786E\u5730\u6254\u8FDB\u5899\u89D2\u7684\u5E9F\u7EB8\u7BD3\u91CC\u3002\n\n\u300C\u77E5\u9053\u4E86\u3002\u300D\u4ED6\u5BF9\u8001\u5468\u8BF4\u3002\n\n\u58F0\u97F3\u662F\u7A33\u7684\u3002\u4ED6\u542C\u89C1\u81EA\u5DF1\u7684\u58F0\u97F3\uFF0C\u751A\u81F3\u89C9\u5F97\u6709\u70B9\u592A\u7A33\u4E86\uFF0C\u50CF\u5728\u8BF4\u522B\u4EBA\u7684\u4E8B\u3002\u8001\u5468\u770B\u7740\u4ED6\uFF0C\u5634\u5507\u52A8\u4E86\u52A8\uFF0C\u50CF\u662F\u60F3\u8BF4\u4EC0\u4E48\uFF0C\u6700\u540E\u4E5F\u6CA1\u8BF4\uFF0C\u53EA\u662F\u62CD\u4E86\u62CD\u4ED6\u7684\u80A9\u8180\u3002\u90A3\u53EA\u624B\u5F88\u91CD\uFF0C\u5728\u4ED6\u80A9\u8180\u4E0A\u505C\u4E86\u4E09\u79D2\u3002\n\n\u300C\u6709\u4E8B\u8BF4\u8BDD\u3002\u300D\u8001\u5468\u8BF4\u3002\n\n\u300C\u884C\u3002\u300D\n\n\u8001\u5468\u8D70\u4E86\u3002\u95E8\u5431\u5440\u4E00\u58F0\u5173\u4E0A\uFF0C\u5DE5\u68DA\u91CC\u53EA\u5269\u4ED6\u4E00\u4E2A\u4EBA\u3002\n\n\u4ED6\u5728\u6905\u5B50\u4E0A\u5750\u7740\uFF0C\u6CA1\u52A8\u3002\u7A97\u5916\u7684\u98CE\u8D8A\u6765\u8D8A\u5927\uFF0C\u94C1\u76AE\u9876\u88AB\u522E\u5F97\u54D7\u54D7\u54CD\uFF0C\u50CF\u8981\u88AB\u6380\u8D77\u6765\u3002\u684C\u4E0A\u7684\u534A\u676F\u51C9\u8336\u5DF2\u7ECF\u51C9\u900F\u4E86\uFF0C\u4ED6\u7AEF\u8D77\u6765\u559D\u4E86\u4E00\u53E3\uFF0C\u8336\u6C34\u91CC\u6D6E\u7740\u4E00\u70B9\u8336\u6E0D\uFF0C\u82E6\u7684\u3002\n\n\u56DB\u5341\u4E03\u3002\u4ED6\u60F3\u3002\u7236\u4EB2\u8D70\u7684\u65F6\u5019\u4E5F\u662F\u56DB\u5341\u4E03\u3002\n\n\u4ED6\u628A\u8336\u676F\u653E\u4E0B\uFF0C\u676F\u5E95\u78D5\u5728\u684C\u9762\u4E0A\uFF0C\u53D1\u51FA'\u55D2'\u7684\u4E00\u58F0\u8F7B\u54CD\u3002\n\n\u8BE5\u53BB\u63A5\u5973\u513F\u653E\u5B66\u4E86\u3002",
      note: "\u5185\u5916\u7ED3\u5408\u793A\u8303\uFF1A\u5148\u5199\u5916\u5728\u52A8\u4F5C\uFF08\u6298\u8BCA\u65AD\u4E66/\u7CFB\u6263\u5B50/\u634F\u70DF\u76D2/\u6254\u70DF\u76D2/\u559D\u8336/\u653E\u676F\u5B50\uFF09\uFF0C\u7136\u540E\u63D2\u5165\u5185\u5FC3\uFF08\u4E0D\u80FD\u544A\u8BC9\u5979\u4EEC/\u56DB\u5341\u4E03/\u7236\u4EB2\u4E5F\u662F\u56DB\u5341\u4E03\uFF09\uFF0C\u518D\u5199\u5BF9\u8BDD\u548C\u5916\u90E8\u73AF\u5883\u3002\u5185\u5916\u6709\u53CD\u5DEE\u2014\u2014\u5916\u5728\u52A8\u4F5C\u7A33\u3001\u58F0\u97F3\u7A33\uFF0C\u5185\u5FC3\u5DF2\u7ECF\u60F3\u5230\u4E86\u6B7B\u3001\u60F3\u5230\u4E86\u5973\u513F\u3001\u60F3\u5230\u4E86\u7236\u4EB2\u3002\u6700\u540E\u4E00\u53E5'\u8BE5\u53BB\u63A5\u5973\u513F\u653E\u5B66\u4E86'\u662F\u60C5\u7EEA\u7684\u843D\u70B9\uFF0C\u4E5F\u662F\u51B3\u5B9A\u2014\u2014\u751F\u6D3B\u8FD8\u8981\u7EE7\u7EED\uFF0C\u4ED6\u8981\u6491\u4F4F\u3002\u6CA1\u6709\u4E00\u4E2A\u60C5\u7EEA\u8BCD\uFF0C\u4F46\u6240\u6709\u60C5\u7EEA\u90FD\u5728\u3002"
    }
  ],
  requires: [],
  conflicts: []
};

// src/kb/nodes/node_ending_hook/opt_hook_soft.kb.json
var opt_hook_soft_kb_default = {
  kb_version: "3.0",
  node_id: "node_ending_hook",
  option_id: "opt_hook_soft",
  option_name: "\u5E73\u548C\u6536\u675F\uFF08\u60C5\u7EEA\u843D\u70B9\uFF09",
  option_description: "\u7AE0\u8282\u81EA\u7136\u6536\u675F\u5728\u60C5\u7EEA\u6216\u6C1B\u56F4\u843D\u70B9\u4E0A\uFF0C\u4E0D\u5F3A\u884C\u7559\u94A9\u5B50\uFF0C\u9002\u5408\u65E5\u5E38\u7AE0\u8282\u3001\u8FC7\u6E21\u7AE0\u8282\u3001\u5377\u672B\u3002",
  system_prompt: "\u4F60\u4F7F\u7528\u5E73\u548C\u6536\u675F\u6A21\u5F0F\u3002\u7AE0\u8282\u81EA\u7136\u6536\u5C3E\uFF0C\u53EF\u4EE5\u843D\u5728\u4E00\u4E2A\u60C5\u7EEA\u843D\u70B9\u3001\u4E00\u4E2A\u8EAB\u4F53\u611F\u53D7\u3001\u4E00\u4E2A\u5B89\u9759\u7684\u753B\u9762\u4E0A\u3002\u4E0D\u9700\u8981\u5F3A\u884C\u5236\u9020\u60AC\u5FF5\uFF0C\u4F46\u6700\u540E\u4E00\u53E5\u4ECD\u7136\u4E0D\u80FD\u662F\u7A7A\u6D1E\u603B\u7ED3\uFF0C\u5FC5\u987B\u843D\u5728\u5177\u4F53\u7684\u7269\u8C61\u6216\u8EAB\u4F53\u611F\u53D7\u4E0A\u3002",
  constraints: [
    "\u7ED3\u5C3E\u843D\u5728\u5177\u4F53\u7269\u8C61/\u8EAB\u4F53\u611F\u53D7/\u753B\u9762\u4E0A",
    "\u7981\u6B62\u7A7A\u6D1E\u603B\u7ED3\u548C\u611F\u6168",
    "\u53EF\u4EE5\u4E0D\u6536\u94A9\u5B50\uFF0C\u4F46\u4E0D\u80FD\u6C34\u7ED3\u5C3E"
  ],
  examples: [
    {
      text: "\u6797\u6DF1\u628A\u7B14\u8BB0\u672C\u6536\u8FDB\u53E3\u888B\uFF0C\u9760\u5728\u58C1\u4E0A\u6B47\u4E86\u53E3\u6C14\u3002\u58C1\u9762\u7684\u6E29\u5EA6\u987A\u7740\u540E\u80CC\u4F20\u8FC7\u6765\uFF0C\u4E09\u5341\u4E03\u70B9\u4E8C\u5EA6\uFF0C\u7A33\u5B9A\uFF0C\u6052\u5B9A\uFF0C\u548C\u4ED6\u7684\u5FC3\u8DF3\u4E00\u4E2A\u9891\u7387\u3002\n\u4ED6\u95ED\u4E0A\u773C\uFF0C\u542C\u7740\u58C1\u91CC\u5341\u79D2\u4E00\u6B21\u7684\u640F\u52A8\u3002",
      note: "\u5E73\u548C\u6536\u675F\uFF1A\u843D\u5728\u8EAB\u4F53\u611F\u53D7\u548C\u6C1B\u56F4\u4E0A"
    }
  ],
  threshold_overrides: {
    endingHook: "soft"
  },
  radar_weights: {
    bodyReaction: 1.2,
    sensorySignal: 1.3,
    action: 0.8,
    emotion: 1.5,
    infoAdvance: 0.7
  }
};

