  option_description: "\u7AE0\u672B\u7559\u4E0B\u4E00\u4E2A\u672A\u89E3\u95EE\u9898\u6216\u60AC\u5FF5\uFF0C\u8BFB\u8005\u60F3\u77E5\u9053\u7B54\u6848\u4F46\u4E0D\u4F1A\u88AB\u65AD\u7AE0\u6FC0\u6012\uFF0C\u662F\u6BD4\u8F83\u6E29\u548C\u7684\u94A9\u5B50\u65B9\u5F0F\u3002",
  system_prompt: "\u4F60\u4F7F\u7528\u60AC\u5FF5\u94A9\u5B50\u6A21\u5F0F\u3002\u7AE0\u8282\u7ED3\u5C3E\u7559\u4E0B\u4E00\u4E2A\u5177\u4F53\u7684\u672A\u89E3\u95EE\u9898\u3001\u5373\u5C06\u53D1\u751F\u7684\u5371\u9669\u3001\u6216\u4E00\u4E2A\u672A\u5B8C\u6210\u7684\u52A8\u4F5C\u3002\u6700\u540E\u4E00\u53E5\u53EF\u4EE5\u662F\u7591\u95EE\u3001\u53EF\u4EE5\u662F\u672A\u5B8C\u6210\u52A8\u4F5C\u3001\u53EF\u4EE5\u662F\u5A01\u80C1\u5373\u5C06\u5230\u6765\u3002\u4E0D\u9700\u8981\u98A0\u8986\u524D\u6587\uFF0C\u4F46\u5FC5\u987B\u6709\u660E\u786E\u7684\u201C\u63A5\u4E0B\u6765\u4F1A\u53D1\u751F\u4EC0\u4E48\u201D\u7684\u60AC\u5FF5\u3002",
  constraints: [
    "\u7AE0\u672B\u5FC5\u987B\u6709\u660E\u786E\u7684\u672A\u89E3\u95EE\u9898\u6216\u672A\u5B8C\u6210\u52A8\u4F5C",
    "\u6700\u540E\u4E00\u53E5\u4E0D\u80FD\u662F\u603B\u7ED3\u53E5/\u5224\u65AD\u53E5",
    "\u60AC\u5FF5\u5FC5\u987B\u5177\u4F53\uFF0C\u4E0D\u80FD\u662F\u201C\u672A\u6765\u4F1A\u600E\u6837\u201D\u8FD9\u79CD\u7A7A\u6CDB\u60AC\u5FF5",
    "\u5FC5\u987B\u8BA9\u8BFB\u8005\u60F3\u77E5\u9053\u7B54\u6848"
  ],
  examples: [
    {
      text: "\u90A3\u622A\u91D1\u8272\u7684\u7EA4\u7EF4\u505C\u5728\u534A\u7A7A\u4E2D\uFF0C\u6307\u5411\u6797\u6DF1\u7684\u5C0F\u81C2\uFF0C\u4E00\u4E0B\u4E00\u4E0B\u5730\u640F\u52A8\u3002\u6797\u6DF1\u63E1\u7D27\u4E86\u51FF\u5B50\uFF0C\u76EF\u7740\u90A3\u9053\u88C2\u7F1D\u3002\n\u88C2\u7F1D\u6DF1\u5904\uFF0C\u6709\u4EC0\u4E48\u4E1C\u897F\u6B63\u5728\u5F80\u5916\u722C\u3002",
      note: "\u60AC\u5FF5\u94A9\u5B50\uFF1A\u65B0\u5371\u9669\u5373\u5C06\u51FA\u73B0\uFF0C\u8BFB\u8005\u60F3\u77E5\u9053\u722C\u51FA\u6765\u7684\u662F\u4EC0\u4E48"
    }
  ],
