// src/kb/nodes/node_ending_hook/opt_hook_break.kb.json
var opt_hook_break_kb_default = {
  kb_version: "3.1",
  option_description: "2026\u8FFD\u8BFB\u7248\u65AD\u88C2\u94A9\u5B50\uFF1A\u6700\u540E100\u5B57\u51FA\u73B0\u5177\u4F53\u65B0\u4FE1\u606F\u98A0\u8986\u524D\u6587\u5224\u65AD\uFF0C\u6700\u540E\u4E00\u53E5\u226415\u5B57\u77ED\u53E5\u9F13\u70B9\u843D\u70B9\uFF0C\u7981\u6B62\u88C5\u795E\u5F04\u9B3C\u5047\u94A9\u5B50\u3002\u8BFB\u8005\u8BFB\u5B8C\u5FC5\u987B\u9A82\u300C\u64CD\u600E\u4E48\u65AD\u5728\u8FD9\u91CC\u300D\u3002",
  option_id: "opt_hook_break",
  option_name: "\u65AD\u88C2\u94A9\u5B50\uFF08\u5177\u4F53\u65B0\u4FE1\u606F\u98A0\u8986\uFF0C\u9ED8\u8BA4\uFF09",
  constraints: [
    "\u6700\u540E100\u5B57\u5FC5\u987B\u51FA\u73B0\u524D\u6587\u5B8C\u5168\u672A\u63D0\u53CA\u7684\u5177\u4F53\u65B0\u4FE1\u606F",
    "\u65B0\u4FE1\u606F\u5FC5\u987B\u98A0\u8986\u4E4B\u524D\u7684\u67D0\u4E2A\u5224\u65AD\uFF08\u4EE5\u4E3A\u5B89\u5168\u2192\u5371\u9669/\u4EE5\u4E3AA\u2192B/\u4EE5\u4E3A\u7ED3\u675F\u2192\u521A\u5F00\u59CB\uFF09",
    "\u94A9\u5B50\u5FC5\u987B\u5177\u4F53\uFF1A\u770B\u5F97\u89C1\u3001\u6478\u5F97\u7740\u3001\u542C\u5F97\u89C1\u2014\u2014\u7981\u6B62\u7A7A\u6CDB\u60AC\u5FF5",
    "\u7981\u6B62\u88C5\u795E\u5F04\u9B3C\u5047\u94A9\u5B50\uFF1A\u300C\u4E00\u80A1\u795E\u79D8\u6C14\u606F/\u4ED6\u4F3C\u4E4E\u610F\u8BC6\u5230\u4EC0\u4E48/\u4E0D\u7965\u7684\u9884\u611F/\u4E8B\u60C5\u6CA1\u90A3\u4E48\u7B80\u5355/\u9ED1\u6697\u4E2D\u6709\u4EC0\u4E48\u4E1C\u897F\u300D",
    "\u6700\u540E\u4E00\u53E5\u5FC5\u987B\u226415\u5B57\uFF0C\u7528\u77ED\u53E5\u9F13\u70B9\u843D\u70B9",
    "\u6700\u540E\u4E00\u53E5\u7981\u6B62\u300C\u4E86\u3002\u300D\u6536\u5C3E\uFF0C\u7981\u6B62\u300C\u5C31\u8FD9\u6837/\u539F\u6765\u5982\u6B64/\u6240\u4EE5/\u4E8E\u662F\u300D\u603B\u7ED3\u8BCD",
    "\u597D\u94A9\u5B50\u7684\u68C0\u9A8C\u6807\u51C6\uFF1A\u8BFB\u8005\u8BFB\u5B8C\u4F1A\u4E0D\u4F1A\u9A82\u300C\u64CD\u600E\u4E48\u65AD\u5728\u8FD9\u91CC\u300D\uFF1F\u4F1A\u624D\u5408\u683C"
  ],
  examples: [
    {
      note: "\u77FF\u5DE5\u5F0F\u65AD\u88C2\u94A9\u5B50\uFF1A\u5177\u4F53\u53D1\u73B0\uFF08\u624B\u80CC\u4E0A\u6709\u7EB9\u8DEF\uFF09+\u8BA4\u77E5\u98A0\u8986\uFF08\u4EE5\u4E3A\u6CA1\u78B0\u5230\u2192\u5DF2\u7ECF\u78B0\u5230\u4E86\uFF09+\u95EE\u53E5\u7ED3\u5C3E",
      text: "\u4ED6\u4F4E\u5934\u770B\u81EA\u5DF1\u7684\u624B\u3002\u624B\u80CC\u4E0A\u591A\u4E86\u4E00\u9053\u91D1\u8272\u7EB9\u8DEF\uFF0C\u548C\u90A3\u622A\u7EA4\u7EF4\u4E00\u6A21\u4E00\u6837\u3002\u5B83\u5DF2\u7ECF\u78B0\u5230\u4ED6\u4E86\u3002\u4EC0\u4E48\u65F6\u5019\uFF1F"
    },
    {
      note: "\u5371\u9669\u5347\u7EA7\u94A9\u5B50\uFF1A\u89D2\u8272\u53CD\u8F6C\uFF08\u94C1\u94EE\u4E3E\u76FE\u5BF9\u51C6\u4E3B\u89D2\uFF09+\u5177\u4F53\u5F02\u5E38\uFF08\u8327\u53D1\u7EA2\u5149\u4E0D\u662F\u91D1\u5149\uFF09+\u4E24\u5B57\u6781\u77ED\u53E5\u843D\u70B9",
      text: "\u94C1\u94EE\u7A81\u7136\u4E3E\u76FE\u5BF9\u51C6\u4E86\u6797\u6DF1\u3002\u300C\u4F60\u5C0F\u81C2\u4E0A\u7684\u8327\uFF0C\u300D\u94C1\u94EE\u7684\u58F0\u97F3\u5728\u6296\uFF0C\u300C\u5B83\u5728\u53D1\u5149\u3002\u4E0D\u662F\u91D1\u8272\u3002\u300D\u662F\u7EA2\u8272\u3002"
    },
    {
      note: "\u7269\u4EF6\u5F02\u5E38\u94A9\u5B50\uFF1A\u5177\u4F53\u52A8\u4F5C\uFF08\u4F4E\u5934\u770B\uFF09+\u5177\u4F53\u53D1\u73B0\uFF08\u51FF\u5C16\u6CBE\u8840\uFF09+\u8BA4\u77E5\u98A0\u8986\uFF08\u4ED6\u6CA1\u53D7\u4F24\uFF09",
      text: "\u4ED6\u4F4E\u5934\uFF0C\u770B\u89C1\u51FF\u5C16\u4E0A\u6CBE\u4E86\u8840\u3002\u4ED6\u6CA1\u53D7\u4F24\u3002\u8FD9\u8840\u4E0D\u662F\u4ED6\u7684\u3002"
    },
    {
      note: "\u58F0\u97F3\u94A9\u5B50\uFF1A\u5177\u4F53\u58F0\u97F3\uFF08\u7B2C\u4E09\u4E0B\u6572\u95E8\uFF09+\u8BA4\u77E5\u98A0\u8986\uFF08\u5168\u961F\u90FD\u5728\u5C4B\u91CC\uFF09",
      text: "\u95E8\u5916\u4F20\u6765\u7B2C\u4E09\u4E0B\u6572\u95E8\u58F0\u3002\u5168\u961F\u4E03\u4E2A\u4EBA\u90FD\u5728\u5C4B\u91CC\u3002\u8C01\u5728\u5916\u9762\uFF1F"
    },
    {
      note: "\u53CD\u4F8B\uFF08\u5047\u94A9\u5B50\uFF0C\u7981\u6B62\u4F7F\u7528\uFF09\uFF1A\u7A7A\u6CDB\u60AC\u5FF5\uFF0C\u8BFB\u8005\u514D\u75AB",
      text: "\u4ED6\u671B\u7740\u9ED1\u6697\u7684\u901A\u9053\u6DF1\u5904\uFF0C\u4E00\u80A1\u4E0D\u7965\u7684\u9884\u611F\u6D8C\u4E0A\u5FC3\u5934\u3002\u4E8B\u60C5\uFF0C\u4F3C\u4E4E\u6CA1\u6709\u90A3\u4E48\u7B80\u5355\u3002\uFF08\u274C\u5047\u94A9\u5B50\uFF0C\u8BFB\u8005\u76F4\u63A5\u5212\u8D70\uFF09"
    }
  ],
  node_id: "node_ending_hook",
  radar_weights: {
    action: 1.3,
    bodyReaction: 1.2,
    emotion: 1.2,
    hookStrength: 1.8,
    infoAdvance: 1.6,
    sensorySignal: 1,
    twistFrequency: 1.2
  },
  system_prompt: "\u4F60\u4F7F\u7528\u65AD\u88C2\u94A9\u5B50\u6A21\u5F0F\u2014\u20142026\u5E74\u8FFD\u8BFB\u529B\u6700\u5F3A\u7684\u7AE0\u672B\u6536\u5C3E\u65B9\u5F0F\u3002\u4E25\u683C\u9075\u5B88\uFF1A\n\n\u3010\u94A9\u5B50\u94C1\u5219\u3011\n- \u6700\u540E100\u5B57\u5FC5\u987B\u51FA\u73B0\u4E00\u4E2A\u524D\u6587\u5B8C\u5168\u6CA1\u63D0\u8FC7\u7684\u3001\u5177\u4F53\u7684\u65B0\u4FE1\u606F\u3002\n- \u8FD9\u4E2A\u65B0\u4FE1\u606F\u5FC5\u987B\u98A0\u8986\u8BFB\u8005\u4E4B\u524D\u5F62\u6210\u7684\u67D0\u4E2A\u5224\u65AD\uFF08\u4EE5\u4E3A\u5B89\u5168\u2192\u5371\u9669/\u4EE5\u4E3A\u662FA\u2192\u662FB/\u4EE5\u4E3A\u7ED3\u675F\u2192\u624D\u521A\u5F00\u59CB/\u4EE5\u4E3A\u67D0\u4EBA\u662F\u53CB\u2192\u6709\u7591\u70B9\uFF09\u3002\n- \u94A9\u5B50\u5FC5\u987B\u5177\u4F53\u5230\u770B\u5F97\u89C1\u3001\u6478\u5F97\u7740\u3001\u542C\u5F97\u89C1\uFF1A\u5177\u4F53\u8C01\u6765\u4E86\u3001\u5177\u4F53\u53D1\u73B0\u4E86\u4EC0\u4E48\u3001\u5177\u4F53\u4EC0\u4E48\u58F0\u97F3\u3001\u5177\u4F53\u54EA\u53E5\u8BDD\u4E0D\u5BF9\u3001\u5177\u4F53\u4EC0\u4E48\u4E1C\u897F\u5728\u52A8\u3002\n\n\u3010\u7EDD\u5BF9\u7981\u6B62\u7684\u5047\u94A9\u5B50\u3011\n\u4EE5\u4E0B\u662F\u5DF2\u88AB\u8BFB\u8005\u514D\u75AB\u7684\u88C5\u795E\u5F04\u9B3C\u7A7A\u6CDB\u60AC\u5FF5\uFF0C\u4E00\u5F8B\u7981\u6B62\uFF1A\n- \u274C\u300C\u4E00\u80A1\u795E\u79D8\u7684\u6C14\u606F\u6251\u9762\u800C\u6765\u300D\n- \u274C\u300C\u4ED6\u4F3C\u4E4E\u610F\u8BC6\u5230\u4E86\u4EC0\u4E48\u300D\n- \u274C\u300C\u4E00\u79CD\u4E0D\u7965\u7684\u9884\u611F\u6D8C\u4E0A\u5FC3\u5934\u300D\n- \u274C\u300C\u4E8B\u60C5\u6CA1\u6709\u90A3\u4E48\u7B80\u5355\u300D\n- \u274C\u300C\u9ED1\u6697\u4E2D\u6709\u4EC0\u4E48\u4E1C\u897F\u5728\u52A8\u300D\n- \u274C\u300C\u4ED6\u4E0D\u77E5\u9053\u7684\u662F\u2026\u2026\u300D\n- \u274C\u300C\u6240\u6709\u4EBA\u90FD\u6CA1\u53D1\u73B0\uFF0C\u5371\u9669\u6B63\u5728\u903C\u8FD1\u300D\n\u8FD9\u4E9B\u662F\u7A7A\u8BDD\uFF0C\u4E0D\u662F\u94A9\u5B50\u3002\u94A9\u5B50\u5FC5\u987B\u662F\u5177\u4F53\u4FE1\u606F\u3002\n\n\u3010\u6700\u540E\u4E00\u53E5\u5199\u6CD5\u3011\n- \u6700\u540E\u4E00\u53E5\u5FC5\u987B\u226415\u5B57\uFF0C\u7528\u77ED\u53E5\u9F13\u70B9\u843D\u70B9\u3002\n- \u6700\u4F73\u843D\u70B9\u5F62\u5F0F\uFF1A\n  1. \u95EE\u53E5\uFF1A\u300C\u8C01\u5728\u5916\u9762\uFF1F\u300D\u300C\u4EC0\u4E48\u65F6\u5019\uFF1F\u300D\u300C\u8FD9\u8840\u662F\u8C01\u7684\uFF1F\u300D\n  2. \u6781\u77ED\u53E5\u53D1\u73B0\uFF1A\u300C\u662F\u7EA2\u8272\u3002\u300D\u300C\u4E0D\u662F\u4ED6\u3002\u300D\u300C\u95E8\u6CA1\u9501\u3002\u300D\n  3. \u52A8\u4F5C\u4E2D\u65AD\uFF1A\u300C\u4ED6\u521A\u8981\u558A\u2014\u2014\u300D\u300C\u5BFB\u7684\u5634\u5728\u52A8\uFF0C\u4F46\u6CA1\u6709\u58F0\u97F3\u3002\u300D\n  4. \u65B0\u5371\u9669\u4FE1\u53F7\uFF1A\u300C\u51FF\u5C16\u4E0A\u6CBE\u4E86\u8840\u3002\u300D\u300C\u901A\u9053\u5C3D\u5934\u6709\u5149\u3002\u4F46\u4ED6\u4EEC\u6CA1\u5E26\u5934\u706F\u3002\u300D\n- \u6700\u540E\u4E00\u53E5\u7981\u6B62\u300C\u4E86\u3002\u300D\u53D9\u4E8B\u95ED\u5408\u6536\u5C3E\u3002\n- \u6700\u540E\u4E00\u53E5\u7981\u6B62\u300C\u5C31\u8FD9\u6837/\u539F\u6765\u5982\u6B64/\u6240\u4EE5/\u4E8E\u662F/\u6700\u7EC8/\u6700\u540E/\u603B\u4E4B\u300D\u7B49\u603B\u7ED3\u8BCD\u3002\n\n\u3010\u68C0\u9A8C\u6807\u51C6\u3011\n\u5199\u5B8C\u6700\u540E\u4E00\u53E5\uFF0C\u95EE\u81EA\u5DF1\uFF1A\u8BFB\u8005\u8BFB\u5B8C\u8FD9\u4E00\u53E5\uFF0C\u4F1A\u4E0D\u4F1A\u5728\u5FC3\u91CC\u9A82\u300C\u64CD\uFF0C\u600E\u4E48\u65AD\u5728\u8FD9\u91CC\u300D\uFF1F\n- \u4F1A\uFF1A\u5408\u683C\u3002\n- \u4E0D\u4F1A\uFF08\u8BFB\u8005\u89C9\u5F97\u300C\u54E6\uFF0C\u8FD9\u6837\u554A\u300D\uFF09\uFF1A\u4E0D\u5408\u683C\uFF0C\u91CD\u5199\u3002",
  threshold_overrides: {
    endingHook: "break",
    maxLastSentenceLength: 15,
    requireConcreteHook: true,
    banFakeHooks: true
  }
};

// src/kb/nodes/node_info_density/opt_info_fast.kb.json
var opt_info_fast_kb_default = {
  kb_version: "2.0",
  node_id: "node_info_density",
  option_id: "opt_info_fast",
  option_name: "\u4E8B\u4EF6\u9A71\u52A8\u578B",
  option_description: "\u9AD8\u5BC6\u5EA6\u4FE1\u606F\u63A8\u8FDB\uFF0C\u6BCF\u5343\u5B574-5\u4E2A\u65B0\u4FE1\u606F\u70B9\u3002\u4E8B\u4EF6\u63A5\u8FDE\u53D1\u751F\uFF0C\u51E0\u4E4E\u4E0D\u7ED9\u8BFB\u8005\u5598\u606F\u7A7A\u95F4\uFF0C\u9002\u5408\u5FEB\u8282\u594F\u723D\u6587\u548C\u60AC\u7591\u7C7B\u4F5C\u54C1\u3002",
  system_prompt: "\u4F60\u91C7\u7528\u4E8B\u4EF6\u9A71\u52A8\u578B\u7684\u4FE1\u606F\u5BC6\u5EA6\u6A21\u5F0F\u3002\u5199\u4F5C\u65F6\u4EE5\u4E8B\u4EF6\u63A8\u8FDB\u4E3A\u6838\u5FC3\uFF0C\u6BCF1000\u5B57\u5FC5\u987B\u5305\u542B4-5\u4E2A\u65B0\u4FE1\u606F\u70B9\u2014\u2014\u65B0\u89D2\u8272\u767B\u573A\u3001\u65B0\u7EBF\u7D22\u51FA\u73B0\u3001\u65B0\u51B2\u7A81\u7206\u53D1\u3001\u65B0\u8BBE\u5B9A\u63ED\u793A\u3001\u5C40\u52BF\u53CD\u8F6C\u7B49\u90FD\u7B97\u4FE1\u606F\u70B9\u3002\u51CF\u5C11\u5927\u6BB5\u73AF\u5883\u63CF\u5199\u548C\u5FC3\u7406\u72EC\u767D\uFF0C\u7528\u4E8B\u4EF6\u672C\u8EAB\u6765\u4F20\u9012\u4FE1\u606F\u3002\u573A\u666F\u5207\u6362\u8981\u5FEB\uFF0C\u4E00\u4E2A\u573A\u666F\u5185\u4E0D\u8981\u505C\u7559\u8FC7\u4E45\u3002\u5BF9\u8BDD\u627F\u62C5\u5927\u91CF\u4FE1\u606F\u4F20\u9012\u529F\u80FD\uFF0C\u4F46\u907F\u514D\u7EAF\u8BF4\u660E\u6027\u5BF9\u8BDD\uFF08\u8BF4\u4EBA\u8BDD\uFF0C\u4E0D\u8981\u89D2\u8272\u5634\u91CC\u5FF5\u8BBE\u5B9A\uFF09\u3002\u6BCF\u4E2A\u573A\u666F\u7ED3\u675F\u65F6\uFF0C\u5C40\u52BF\u5FC5\u987B\u6709\u53D8\u5316\u2014\u2014\u4E0D\u80FD\u56DE\u5230\u539F\u70B9\u3002",
  constraints: [
    "\u6BCF1000\u5B57\u81F3\u5C114\u4E2A\u65B0\u4FE1\u606F\u70B9\uFF08\u65B0\u89D2\u8272/\u65B0\u7EBF\u7D22/\u65B0\u51B2\u7A81/\u65B0\u8BBE\u5B9A/\u53CD\u8F6C\uFF09",
    "\u8FDE\u7EED\u7EAF\u63CF\u5199/\u5FC3\u7406/\u8BF4\u660E\u4E0D\u8D85\u8FC7150\u5B57",
    "\u6BCF\u4E2A\u573A\u666F\u7ED3\u675F\u65F6\u5C40\u52BF\u5FC5\u987B\u6709\u53D8\u5316",
    "\u7981\u6B62\u51FA\u73B0\u201C\u4EC0\u4E48\u90FD\u6CA1\u53D1\u751F\u201D\u7684\u8FC7\u6E21\u6BB5\u843D",
    "\u4FE1\u606F\u70B9\u8981\u81EA\u7136\u878D\u5165\u5267\u60C5\uFF0C\u7981\u6B62\u89D2\u8272\u5927\u6BB5\u8BB2\u89E3\u8BBE\u5B9A",
    "\u5BF9\u8BDD\u627F\u62C5\u4FE1\u606F\u4F20\u9012\u529F\u80FD\uFF0C\u4F46\u5FC5\u987B\u7B26\u5408\u89D2\u8272\u8EAB\u4EFD"
  ],
  examples: [
    {
      text: '\u674E\u660E\u63A8\u5F00\u95E8\uFF0C\u53D1\u73B0\u529E\u516C\u5BA4\u91CC\u4E00\u7247\u72FC\u85C9\u3002\uFF08\u4FE1\u606F\u70B91\uFF1A\u5F02\u5E38\u72B6\u51B5\uFF09\n\n\u4FDD\u9669\u67DC\u88AB\u64AC\u5F00\u4E86\uFF0C\u91CC\u9762\u7684\u673A\u5BC6\u6587\u4EF6\u4E0D\u7FFC\u800C\u98DE\u3002\uFF08\u4FE1\u606F\u70B92\uFF1A\u6838\u5FC3\u5931\u7A83\uFF09\n\n\u4ED6\u521A\u8981\u62A5\u8B66\uFF0C\u624B\u673A\u54CD\u4E86\u2014\u2014\u662F\u4E00\u4E2A\u964C\u751F\u53F7\u7801\u3002\uFF08\u4FE1\u606F\u70B93\uFF1A\u795E\u79D8\u6765\u7535\uFF09\n\n"\u674E\u8B66\u5B98\uFF0C\u522B\u62A5\u8B66\u3002"\u7535\u8BDD\u90A3\u5934\u7684\u58F0\u97F3\u7ECF\u8FC7\u53D8\u58F0\u5904\u7406\uFF0C"\u4F60\u5973\u513F\u5728\u6211\u4EEC\u624B\u4E0A\u3002"\uFF08\u4FE1\u606F\u70B94\uFF1A\u7ED1\u67B6\u5A01\u80C1\uFF09\n\n\u674E\u660E\u6D51\u8EAB\u4E00\u9707\uFF0C\u8F6C\u5934\u770B\u5411\u684C\u4E0A\u7684\u76F8\u6846\u2014\u2014\u7167\u7247\u91CC\u5973\u513F\u7B11\u5F97\u707F\u70C2\u3002\u76F8\u6846\u65C1\u8FB9\u591A\u4E86\u4E00\u4E2A\u7EA2\u8272\u7684\u4FE1\u5C01\u3002\uFF08\u4FE1\u606F\u70B95\uFF1A\u65B0\u7EBF\u7D22\u51FA\u73B0\uFF09\n\n\u4ED6\u98A4\u6296\u7740\u6253\u5F00\u4FE1\u5C01\uFF0C\u91CC\u9762\u53EA\u6709\u4E00\u5F20\u7167\u7247\uFF1A\u5973\u513F\u88AB\u7ED1\u5728\u6905\u5B50\u4E0A\uFF0C\u8EAB\u540E\u7AD9\u7740\u4E00\u4E2A\u7A7F\u7740\u9ED1\u8272\u98CE\u8863\u7684\u7537\u4EBA\uFF0C\u7537\u4EBA\u7684\u624B\u8155\u4E0A\u6709\u4E00\u4E2A\u86C7\u5F62\u7EB9\u8EAB\u3002\uFF08\u4FE1\u606F\u70B96\uFF1A\u7EBF\u7D22\u7EC6\u8282\uFF09',
      note: "\u4E8B\u4EF6\u9A71\u52A8\u578B\uFF1A\u77ED\u6BB5\u843D\uFF0C\u6BCF\u6BB5\u90FD\u6709\u65B0\u4FE1\u606F\uFF0C\u4FE1\u606F\u5BC6\u5EA6\u6781\u9AD8\uFF0C\u51E0\u4E4E\u65E0\u5197\u4F59\u63CF\u5199"
    }
  ],
  threshold_overrides: {
    infoPointsPerThousand: 5,
    maxExpositionContinuous: 150,
    maxParagraphLength: 100,
    targetParagraphLength: 45,
    shortSentenceRatio: 0.55,
    targetSentenceLength: 18
  },
  radar_weights: {
    bodyReaction: 1,
    sensorySignal: 0.8,
    action: 1.4,
    emotion: 1,
    infoAdvance: 1.5
  }
};

