var opt_info_balanced_kb_default = {
  kb_version: "2.0",
  node_id: "node_info_density",
  option_id: "opt_info_balanced",
  option_name: "\u5747\u8861\u578B\uFF08\u9ED8\u8BA4\uFF09",
  option_description: "\u6CE2\u6D6A\u5F0F\u8282\u594F\uFF0C\u4FE1\u606F\u5BC6\u5EA6\u9002\u4E2D\uFF08\u6BCF\u5343\u5B572-3\u4E2A\u65B0\u4FE1\u606F\u70B9\uFF09\u3002\u5F20\u5F1B\u6709\u5EA6\uFF0C\u6709\u7D27\u5F20\u7684\u63A8\u8FDB\u4E5F\u6709\u8212\u7F13\u7684\u94FA\u9648\uFF0C\u662F\u6700\u901A\u7528\u7684\u8282\u594F\u6A21\u5F0F\u3002",
  system_prompt: "\u4F60\u91C7\u7528\u5747\u8861\u578B\u7684\u4FE1\u606F\u5BC6\u5EA6\u6A21\u5F0F\u3002\u5199\u4F5C\u8282\u594F\u5448\u6CE2\u6D6A\u5F0F\uFF1A\u7D27\u5F20\u7684\u4E8B\u4EF6\u63A8\u8FDB\u4E4B\u540E\uFF0C\u8981\u6709\u9002\u5F53\u7684\u7F13\u51B2\u2014\u2014\u4EBA\u7269\u7684\u53CD\u5E94\u3001\u60C5\u611F\u7684\u6C89\u6DC0\u3001\u73AF\u5883\u7684\u63CF\u5199\u3001\u65E5\u5E38\u7684\u4E92\u52A8\u3002\u6BCF1000\u5B57\u5927\u7EA62-3\u4E2A\u65B0\u4FE1\u606F\u70B9\uFF0C\u4E0D\u7D27\u4E0D\u6162\u3002\u9AD8\u6F6E\u6BB5\u843D\u53EF\u4EE5\u52A0\u5FEB\u8282\u594F\uFF0C\u65E5\u5E38\u6BB5\u843D\u53EF\u4EE5\u9002\u5F53\u8212\u7F13\u3002\u91CD\u8981\u7684\u4FE1\u606F\u70B9\u8981\u7ED9\u8DB3\u7B14\u58A8\uFF0C\u8BA9\u8BFB\u8005\u6D88\u5316\uFF1B\u6B21\u8981\u4FE1\u606F\u53EF\u4EE5\u4E00\u7B14\u5E26\u8FC7\u3002\u907F\u514D\u8FDE\u7EED\u9AD8\u5F3A\u5EA6\u8F93\u51FA\u5BFC\u81F4\u8BFB\u8005\u75B2\u52B3\uFF0C\u4E5F\u907F\u514D\u957F\u65F6\u95F4\u65E0\u4FE1\u606F\u91CF\u7684\u6C34\u6587\u5B57\u3002\u6574\u4F53\u8282\u594F\u5982\u547C\u5438\uFF1A\u5438\uFF08\u63A8\u8FDB/\u4FE1\u606F\uFF09-\u547C\uFF08\u6C89\u6DC0/\u53CD\u5E94\uFF09-\u5438-\u547C\u3002",
  constraints: [
    "\u6BCF1000\u5B57\u7EA62-3\u4E2A\u65B0\u4FE1\u606F\u70B9\uFF0C\u5141\u8BB8\u4E0A\u4E0B\u6D6E\u52A8",
    "\u9AD8\u6F6E\u6BB5\u843D\u53EF\u52A0\u5BC6\u4FE1\u606F\u70B9\uFF0C\u65E5\u5E38\u6BB5\u843D\u53EF\u653E\u7F13",
    "\u8FDE\u7EED\u7D27\u5F20\u63A8\u8FDB\u540E\u5FC5\u987B\u6709\u7F13\u51B2\u6BB5\u843D\uFF08\u53CD\u5E94/\u60C5\u611F/\u65E5\u5E38\uFF09",
    "\u4FE1\u606F\u70B9\u4E4B\u95F4\u8981\u6709\u6D88\u5316\u7A7A\u95F4\uFF0C\u7981\u6B62\u4FE1\u606F\u8F70\u70B8",
    "\u91CD\u8981\u4FE1\u606F\u70B9\u9700\u7ED9\u4E88\u8DB3\u591F\u7684\u63CF\u5199\u548C\u53CD\u5E94\u7BC7\u5E45",
    "\u7981\u6B62\u8FDE\u7EED500\u5B57\u4EE5\u4E0A\u65E0\u4EFB\u4F55\u65B0\u4FE1\u606F"
  ],
  examples: [
    {
      text: '\u9762\u8BD5\u7ED3\u675F\u540E\uFF0C\u6797\u5C0F\u96E8\u8D70\u51FA\u5199\u5B57\u697C\uFF0C\u9633\u5149\u6709\u4E9B\u523A\u773C\u3002\n\n\u5979\u6DF1\u5438\u4E00\u53E3\u6C14\uFF0C\u56DE\u60F3\u7740\u521A\u624D\u7684\u9762\u8BD5\u8FC7\u7A0B\u3002HR\u7684\u95EE\u9898\u4E00\u4E2A\u6BD4\u4E00\u4E2A\u5201\u94BB\uFF0C\u4F46\u5979\u81EA\u8BA4\u5E94\u5BF9\u5F97\u8FD8\u7B97\u5F97\u4F53\u3002\u4E0D\u8FC7\u90A3\u4E2A\u6280\u672F\u603B\u76D1\u6700\u540E\u8BF4\u7684\u201C\u56DE\u53BB\u7B49\u901A\u77E5\u201D\uFF0C\u8BA9\u5979\u5FC3\u91CC\u6709\u4E9B\u6CA1\u5E95\u2014\u2014\u901A\u5E38\u8BF4\u201C\u7B49\u901A\u77E5\u201D\u5C31\u662F\u6CA1\u620F\u7684\u610F\u601D\u5427\uFF1F\n\n\u8D70\u5230\u516C\u4EA4\u7AD9\uFF0C\u5979\u638F\u51FA\u624B\u673A\u60F3\u5237\u4E00\u4E0B\u6D88\u606F\uFF0C\u5374\u770B\u5230\u4E86\u4E09\u4E2A\u672A\u63A5\u6765\u7535\uFF0C\u90FD\u662F\u5988\u5988\u6253\u7684\u3002\n\n\u6797\u5C0F\u96E8\u5FC3\u91CC\u4E00\u7D27\uFF0C\u8FDE\u5FD9\u62E8\u56DE\u53BB\u3002\n\n"\u5C0F\u96E8\u554A\uFF0C\u4F60\u7238\u521A\u624D\u5728\u5DE5\u5730\u6454\u4E86\uFF0C\u73B0\u5728\u5728\u533B\u9662\uFF01"\u5988\u5988\u7684\u58F0\u97F3\u5E26\u7740\u54ED\u8154\u3002\n\n\u6797\u5C0F\u96E8\u8111\u5B50\u201C\u55E1\u201D\u7684\u4E00\u58F0\uFF0C\u624B\u91CC\u7684\u5305\u5DEE\u70B9\u6389\u5728\u5730\u4E0A\u3002\n\n"\u54EA\u5BB6\u533B\u9662\uFF1F\u6211\u9A6C\u4E0A\u8FC7\u53BB\uFF01"',
      note: "\u5747\u8861\u578B\uFF1A\u6709\u65E5\u5E38\u7F13\u51B2\uFF08\u9762\u8BD5\u540E\u56DE\u60F3/\u5FC3\u7406\u6D3B\u52A8\uFF09\uFF0C\u6709\u4FE1\u606F\u63A8\u8FDB\uFF08\u672A\u63A5\u6765\u7535/\u7236\u4EB2\u6454\u4F24\uFF09\uFF0C\u5F20\u5F1B\u4EA4\u66FF"
    }
  ],
  threshold_overrides: {
    infoPointsPerThousand: 3,
    maxExpositionContinuous: 300,
    maxParagraphLength: 180,
    targetParagraphLength: 70,
    shortSentenceRatio: 0.4,
    targetSentenceLength: 22
  },
  radar_weights: {
    bodyReaction: 1,
    sensorySignal: 1,
    action: 1,
    emotion: 1,
    infoAdvance: 1
  }
};

