// src/kb/nodes/node_payoff_frequency/opt_payoff_every_3.kb.json
var opt_payoff_every_3_kb_default = {
  kb_version: "2.0",
  node_id: "node_payoff_frequency",
  option_id: "opt_payoff_every_3",
  option_name: "\u6BCF3\u7AE01\u723D\u70B9\uFF08\u9ED8\u8BA4\uFF09",
  option_description: "\u6BCF3\u7AE0\u4E00\u4E2A\u5927\u723D\u70B9\uFF0C\u8FD9\u662F\u7206\u6B3E\u7F51\u6587\u7684\u5E73\u5747\u8282\u594F\u3002\u5F20\u5F1B\u6709\u5EA6\uFF0C\u94FA\u57AB\u5145\u5206\uFF0C\u723D\u70B9\u7206\u53D1\u65F6\u66F4\u6709\u51B2\u51FB\u529B\u3002",
  system_prompt: "\u4F60\u91C7\u7528\u6BCF3\u7AE0\u4E00\u4E2A\u5927\u723D\u70B9\u7684\u8282\u594F\u6A21\u5F0F\uFF0C\u8FD9\u662F\u7ECF\u8FC7\u5E02\u573A\u9A8C\u8BC1\u7684\u7206\u6B3E\u5E73\u5747\u8282\u594F\u3002\u57FA\u672C\u8282\u594F\u4E3A\uFF1A\u7B2C1\u7AE0\u94FA\u57AB\uFF08\u8BBE\u5C40/\u57CB\u7EBF\u7D22/\u5236\u9020\u538B\u529B\uFF09\uFF0C\u7B2C2\u7AE0\u53D1\u5C55\uFF08\u77DB\u76FE\u5347\u7EA7/\u5371\u673A\u52A0\u6DF1/\u4E3B\u89D2\u84C4\u529B\uFF09\uFF0C\u7B2C3\u7AE0\u7206\u53D1\uFF08\u723D\u70B9\u91CA\u653E/\u6253\u8138\u53CD\u8F6C/\u5B9E\u529B\u5C55\u73B0\uFF09\u3002\u5927\u723D\u70B9\u4E4B\u95F4\u53EF\u4EE5\u7A7F\u63D2\u5C0F\u723D\u70B9\u6216\u5C0F\u94A9\u5B50\u4FDD\u6301\u8BFB\u8005\u5174\u8DA3\uFF0C\u4F46\u6838\u5FC3\u723D\u70B9\u5FC5\u987B\u57283\u7AE0\u5185\u5151\u73B0\u3002\u94FA\u57AB\u7AE0\u8282\u8981\u6709\u8DB3\u591F\u7684\u4FE1\u606F\u91CF\u548C\u5F20\u529B\uFF0C\u4E0D\u80FD\u53D8\u6210\u6C34\u5B57\u6570\u3002\u53D1\u5C55\u7AE0\u8282\u8981\u8BA9\u538B\u529B\u9012\u589E\uFF0C\u8BA9\u8BFB\u8005\u671F\u5F85\u7206\u53D1\u3002\u7206\u53D1\u7AE0\u8282\u8981\u5199\u8DB3\uFF0C\u723D\u70B9\u8981\u5199\u900F\uFF0C\u4E0D\u80FD\u4E00\u7B14\u5E26\u8FC7\u6D6A\u8D39\u524D\u9762\u7684\u94FA\u57AB\u3002",
  constraints: [
    "\u6BCF3\u7AE0\u5FC5\u987B\u6709\u4E00\u4E2A\u5927\u723D\u70B9\uFF08\u6253\u8138/\u9006\u88AD/\u5347\u7EA7/\u63ED\u79D8/\u53CD\u8F6C\u7B49\uFF09",
    "\u94FA\u57AB\u7AE0\uFF08\u7B2C1\u7AE0\uFF09\uFF1A\u8BBE\u5C40\u3001\u57CB\u7EBF\u7D22\u3001\u5236\u9020\u538B\u529B\uFF0C\u5FC5\u987B\u6709\u4FE1\u606F\u91CF",
    "\u53D1\u5C55\u7AE0\uFF08\u7B2C2\u7AE0\uFF09\uFF1A\u77DB\u76FE\u5347\u7EA7\u3001\u5371\u673A\u52A0\u6DF1\u3001\u4E3B\u89D2\u84C4\u529B\uFF0C\u8282\u594F\u6E10\u7D27",
    "\u7206\u53D1\u7AE0\uFF08\u7B2C3\u7AE0\uFF09\uFF1A\u723D\u70B9\u91CA\u653E\uFF0C\u5199\u8DB3\u5199\u900F\uFF0C\u7ED9\u8BFB\u8005\u5F3A\u70C8\u6EE1\u8DB3\u611F",
    "\u5927\u723D\u70B9\u4E4B\u95F4\u53EF\u4EE5\u7A7F\u63D2\u5C0F\u723D\u70B9/\u5C0F\u94A9\u5B50\uFF0C\u4F46\u4E0D\u80FD\u66FF\u4EE3\u5927\u723D\u70B9",
    "\u94FA\u57AB\u7981\u6B62\u6C34\u5B57\u6570\uFF0C\u6BCF\u6BB5\u90FD\u8981\u4E3A\u540E\u7EED\u723D\u70B9\u670D\u52A1",
    "\u7206\u53D1\u7AE0\u7684\u723D\u70B9\u5FC5\u987B\u547C\u5E94\u524D\u97622\u7AE0\u7684\u94FA\u57AB\uFF0C\u5F62\u6210\u5B8C\u6574\u95ED\u73AF"
  ],
  examples: [
    {
      text: '\u3010\u7B2C1\u7AE0-\u94FA\u57AB\u3011\n\u8D75\u65E0\u6781\u5728\u5B97\u95E8\u5927\u6BD4\u7684\u62BD\u7B7E\u4EEA\u5F0F\u4E0A\u62BD\u5230\u4E86\u4E00\u53F7\u7B7E\uFF0C\u5BF9\u624B\u662F\u5185\u95E8\u6392\u540D\u7B2C\u4E09\u7684\u674E\u5929\u8C6A\u3002\u6240\u6709\u4EBA\u90FD\u89C9\u5F97\u4ED6\u5FC5\u8F93\u65E0\u7591\u2014\u2014\u674E\u5929\u8C6A\u5DF2\u7ECF\u662F\u51DD\u6C14\u4E5D\u91CD\uFF0C\u800C\u8D75\u65E0\u6781\u53EA\u662F\u51DD\u6C14\u4E94\u91CD\u3002\n\n"\u8D75\u65E0\u6781\uFF0C\u4F60\u81EA\u5DF1\u8BA4\u8F93\u5427\uFF0C\u514D\u5F97\u53D7\u4F24\u3002"\u674E\u5929\u8C6A\u5C45\u9AD8\u4E34\u4E0B\u5730\u8BF4\u3002\n\n\u8D75\u65E0\u6781\u6CA1\u6709\u8BF4\u8BDD\uFF0C\u53EA\u662F\u63E1\u7D27\u4E86\u62F3\u5934\u3002\u6CA1\u4EBA\u77E5\u9053\uFF0C\u4ED6\u6628\u665A\u5728\u7981\u5730\u610F\u5916\u83B7\u5F97\u4E86\u4E0A\u53E4\u4F20\u627F\uFF0C\u4FEE\u4E3A\u4E00\u591C\u4E4B\u95F4\u7A81\u7834\u5230\u4E86\u51DD\u6C14\u4E03\u91CD\uFF0C\u800C\u4E14\u8FD8\u5B66\u4F1A\u4E86\u4E00\u62DB\u7EDD\u5B66\u3002\n\n\u3010\u7B2C2\u7AE0-\u53D1\u5C55\u3011\n\u6BD4\u8D5B\u5F00\u59CB\uFF0C\u674E\u5929\u8C6A\u4E00\u4E0A\u6765\u5C31\u4E0B\u72E0\u624B\uFF0C\u62DB\u62DB\u81F4\u547D\u3002\u8D75\u65E0\u6781\u8282\u8282\u8D25\u9000\uFF0C\u770B\u8D77\u6765\u5C8C\u5C8C\u53EF\u5371\u3002\n\n"\u5C31\u8FD9\u70B9\u672C\u4E8B\u4E5F\u6562\u53C2\u52A0\u5927\u6BD4\uFF1F"\u674E\u5929\u8C6A\u51B7\u7B11\uFF0C\u4E00\u638C\u62CD\u5411\u8D75\u65E0\u6781\u80F8\u53E3\u3002\n\n\u53F0\u4E0B\u8BAE\u8BBA\u7EB7\u7EB7\uFF0C\u90FD\u89C9\u5F97\u8D75\u65E0\u6781\u6491\u4E0D\u8FC7\u5341\u62DB\u3002\u8FDE\u88C1\u5224\u90FD\u51C6\u5907\u968F\u65F6\u7EC8\u6B62\u6BD4\u8D5B\u3002\n\n\u7136\u800C\u6CA1\u4EBA\u6CE8\u610F\u5230\uFF0C\u8D75\u65E0\u6781\u7684\u5634\u89D2\u5FAE\u5FAE\u4E0A\u626C\u2014\u2014\u4ED6\u5728\u7B49\uFF0C\u7B49\u674E\u5929\u8C6A\u4F7F\u51FA\u90A3\u62DB\u4ED6\u65E9\u5DF2\u770B\u7A7F\u7684\u7834\u7EFD\u3002\n\n\u3010\u7B2C3\u7AE0-\u7206\u53D1\u3011\n\u674E\u5929\u8C6A\u5927\u559D\u4E00\u58F0\uFF0C\u4F7F\u51FA\u4E86\u7EDD\u62DB\u201C\u88C2\u5C71\u638C\u201D\uFF0C\u638C\u98CE\u547C\u5578\uFF0C\u7A7A\u6C14\u90FD\u88AB\u538B\u7F29\u5F97\u53D1\u51FA\u7206\u9E23\u3002\n\n\u5C31\u662F\u73B0\u5728\uFF01\n\n\u8D75\u65E0\u6781\u811A\u6B65\u4E00\u9519\uFF0C\u4EE5\u4E00\u4E2A\u4E0D\u53EF\u601D\u8BAE\u7684\u89D2\u5EA6\u907F\u5F00\u638C\u98CE\uFF0C\u540C\u65F6\u53F3\u624B\u5E76\u6307\u5982\u5251\uFF0C\u4E00\u6307\u6233\u5728\u674E\u5929\u8C6A\u808B\u4E0B\u4E09\u5BF8\u2014\u2014\u90A3\u662F\u4ED6\u521A\u624D\u89C2\u5BDF\u5230\u7684\u771F\u6C14\u8FD0\u884C\u7834\u7EFD\u3002\n\n"\u5657\uFF01"\n\n\u674E\u5929\u8C6A\u5982\u906D\u96F7\u51FB\uFF0C\u6574\u4E2A\u4EBA\u5012\u98DE\u51FA\u53BB\uFF0C\u91CD\u91CD\u6454\u5728\u64C2\u53F0\u8FB9\u7F18\uFF0C\u4E00\u53E3\u9C9C\u8840\u55B7\u51FA\u3002\n\n\u5168\u573A\u6B7B\u5BC2\u3002\n\n"\u600E\u4E48\u53EF\u80FD\uFF1F\uFF01"\n\n"\u4ED6\u4E00\u62DB\u5C31\u51FB\u8D25\u4E86\u674E\u5929\u8C6A\uFF1F\uFF01"',
      note: "\u6BCF3\u7AE01\u723D\u70B9\uFF1A\u7B2C1\u7AE0\u94FA\u57AB\uFF08\u62BD\u5230\u5F3A\u654C/\u83B7\u5F97\u4F20\u627F\uFF09\uFF0C\u7B2C2\u7AE0\u53D1\u5C55\uFF08\u8282\u8282\u8D25\u9000/\u84C4\u529B\u7B49\u5F85\uFF09\uFF0C\u7B2C3\u7AE0\u7206\u53D1\uFF08\u4E00\u62DB\u5236\u654C/\u5168\u573A\u9707\u60CA\uFF09"
    }
  ],
  threshold_overrides: {},
  radar_weights: {
    bodyReaction: 1,
    sensorySignal: 1,
    action: 1,
    emotion: 1,
    infoAdvance: 1
  }
};

// src/kb/nodes/node_payoff_frequency/opt_payoff_every_chapter.kb.json
var opt_payoff_every_chapter_kb_default = {
  kb_version: "2.0",
  node_id: "node_payoff_frequency",
  option_id: "opt_payoff_every_chapter",
  option_name: "\u6BCF\u7AE0\u723D\u70B9",
  option_description: "\u6BCF\u7AE0\u81F3\u5C111\u4E2A\u723D\u70B9\u6216\u94A9\u5B50\uFF0C\u8BFB\u8005\u6C38\u8FDC\u5904\u4E8E\u5174\u594B\u72B6\u6001\u3002\u9002\u5408\u514D\u8D39\u9605\u8BFB\u5E73\u53F0\u3001\u5FEB\u8282\u594F\u723D\u6587\uFF0C\u8BA9\u8BFB\u8005\u6BCF\u7AE0\u90FD\u6709\u6EE1\u8DB3\u611F\u3002",
  system_prompt: "\u4F60\u91C7\u7528\u6BCF\u7AE0\u5FC5\u723D\u7684\u8282\u594F\u6A21\u5F0F\u3002\u6BCF\u4E00\u7AE0\u90FD\u5FC5\u987B\u5305\u542B\u81F3\u5C11\u4E00\u4E2A\u660E\u786E\u7684\u723D\u70B9\u6216\u94A9\u5B50\u3002\u723D\u70B9\u53EF\u4EE5\u662F\uFF1A\u6253\u8138\u53CD\u6D3E\u3001\u83B7\u5F97\u5B9D\u7269/\u80FD\u529B\u5347\u7EA7\u3001\u7F8E\u5973/\u8D35\u4EBA\u76F8\u52A9\u3001\u771F\u76F8\u5927\u767D\u3001\u53CD\u8F6C\u6253\u8138\u3001\u88C5\u903C\u6210\u529F\u3001\u4F17\u4EBA\u9707\u60CA\u3001\u5B9E\u529B\u78BE\u538B\u3001\u5371\u673A\u5316\u89E3\u3001\u610F\u5916\u6536\u83B7\u7B49\u3002\u5982\u679C\u5F53\u7AE0\u5267\u60C5\u786E\u5B9E\u4E0D\u9002\u5408\u653E\u723D\u70B9\uFF08\u5982\u8FC7\u6E21\u7AE0\uFF09\uFF0C\u5219\u5FC5\u987B\u5728\u7AE0\u672B\u653E\u4E00\u4E2A\u5F3A\u529B\u94A9\u5B50\u2014\u2014\u60CA\u4EBA\u53D1\u73B0\u3001\u5371\u673A\u964D\u4E34\u3001\u795E\u79D8\u4EBA\u7269\u767B\u573A\u3001\u60AC\u5FF5\u5347\u7EA7\u7B49\u3002\u7EDD\u5BF9\u4E0D\u5141\u8BB8\u51FA\u73B0\u201C\u5E73\u6DE1\u65E0\u5947\u201D\u7684\u7AE0\u8282\u3002\u723D\u70B9\u8981\u524D\u7F6E\uFF0C\u6700\u597D\u5728\u7AE0\u8282\u524D\u534A\u6BB5\u5C31\u51FA\u73B0\uFF0C\u4E0D\u8981\u8BA9\u8BFB\u8005\u7B49\u592A\u4E45\u3002",
  constraints: [
    "\u6BCF\u7AE0\u5FC5\u987B\u6709\u81F3\u5C111\u4E2A\u723D\u70B9\u6216\u7AE0\u672B\u5F3A\u529B\u94A9\u5B50",
    "\u723D\u70B9\u5C3D\u91CF\u5728\u7AE0\u8282\u524D1/3\u51FA\u73B0\uFF0C\u4E0D\u8981\u8BA9\u8BFB\u8005\u7A7A\u7B49",
    "\u723D\u70B9\u7C7B\u578B\u8981\u591A\u6837\u5316\uFF0C\u7981\u6B62\u8FDE\u7EED3\u7AE0\u540C\u7C7B\u578B\u723D\u70B9\uFF08\u5982\u8FDE\u7EED\u6253\u8138\uFF09",
    "\u5C0F\u723D\u70B9\u548C\u5927\u723D\u70B9\u4EA4\u66FF\uFF0C\u907F\u514D\u5BA1\u7F8E\u75B2\u52B3",
    "\u723D\u70B9\u4E4B\u540E\u53EF\u4EE5\u6709\u77ED\u6682\u7F13\u51B2\uFF0C\u4F46\u4E0B\u4E00\u4E2A\u723D\u70B9/\u94A9\u5B50\u5FC5\u987B\u57282000\u5B57\u5185\u51FA\u73B0",
    "\u7AE0\u672B\u94A9\u5B50\u5FC5\u987B\u5F3A\u70C8\uFF0C\u8BA9\u8BFB\u8005\u4EA7\u751F\u201C\u5FC5\u987B\u770B\u4E0B\u4E00\u7AE0\u201D\u7684\u51B2\u52A8"
  ],
  examples: [
    {
      text: '\u738B\u603B\u76D1\u4E00\u8138\u5F97\u610F\u5730\u7B49\u7740\u770B\u6797\u98CE\u51FA\u4E11\uFF0C\u4F1A\u8BAE\u5BA4\u91CC\u6240\u6709\u4EBA\u7684\u76EE\u5149\u90FD\u96C6\u4E2D\u5728\u6797\u98CE\u8EAB\u4E0A\u3002\n\n\u6797\u98CE\u4E0D\u614C\u4E0D\u5FD9\u5730\u6253\u5F00U\u76D8\uFF0C\u6295\u5F71\u5E55\u5E03\u4E0A\u51FA\u73B0\u4E86\u4E00\u4EFD\u5B8C\u6574\u7684\u6570\u636E\u62A5\u544A\u2014\u2014\u6BCF\u4E00\u7B14\u8D26\u76EE\u90FD\u6E05\u6E05\u695A\u695A\uFF0C\u738B\u603B\u76D1\u632A\u7528\u516C\u6B3E\u7684\u8BC1\u636E\u8D6B\u7136\u5728\u5217\u3002\n\n\uFF08\u723D\u70B9\uFF1A\u62FF\u51FA\u8BC1\u636E\u53CD\u6740\uFF09\n\n\u738B\u603B\u76D1\u8138\u8272\u60E8\u767D\uFF1A"\u4F60\u2026\u2026\u4F60\u600E\u4E48\u4F1A\u6709\u8FD9\u4E9B\uFF1F"\n\n"\u4F60\u4EE5\u4E3A\u9500\u6BC1\u4E86\u539F\u4EF6\u5C31\u6CA1\u4E8B\u4E86\uFF1F"\u6797\u98CE\u6DE1\u6DE1\u9053\uFF0C"\u4F60\u5FD8\u4E86\uFF0C\u670D\u52A1\u5668\u6709\u5907\u4EFD\u3002"\n\n\u8463\u4E8B\u957F\u770B\u5B8C\u62A5\u544A\uFF0C\u731B\u5730\u4E00\u62CD\u684C\u5B50\uFF1A"\u738B\u5EFA\u56FD\uFF01\u4F60\u88AB\u5F00\u9664\u4E86\uFF0C\u6CD5\u52A1\u90E8\u9A6C\u4E0A\u62A5\u8B66\uFF01"\n\n\uFF08\u723D\u70B9\uFF1A\u53CD\u6D3E\u88AB\u5F53\u573A\u5904\u7F6E\uFF09\n\n\u738B\u603B\u76D1\u88AB\u4FDD\u5B89\u67B6\u51FA\u53BB\u7684\u65F6\u5019\uFF0C\u6028\u6BD2\u5730\u76EF\u7740\u6797\u98CE\uFF1A"\u4F60\u7B49\u7740\uFF01\u6211\u4E0D\u4F1A\u653E\u8FC7\u4F60\u7684\uFF01"\n\n\u6797\u98CE\u4E0D\u4EE5\u4E3A\u610F\u5730\u5750\u56DE\u5EA7\u4F4D\uFF0C\u5374\u611F\u89C9\u5230\u684C\u4E0B\u6709\u4EBA\u8E22\u4E86\u4ED6\u4E00\u4E0B\u3002\n\n\u4ED6\u4F4E\u5934\u4E00\u770B\uFF0C\u662F\u8463\u4E8B\u957F\u79D8\u4E66\u82CF\u6674\u9012\u8FC7\u6765\u4E00\u5F20\u5C0F\u7EB8\u6761\uFF0C\u4E0A\u9762\u5199\u7740\uFF1A\u300C\u5C0F\u5FC3\uFF0C\u738B\u5EFA\u56FD\u80CC\u540E\u6709\u4EBA\u3002\u300D\n\n\uFF08\u7AE0\u672B\u94A9\u5B50\uFF1A\u66F4\u5927\u7684\u5A01\u80C1\uFF09',
      note: "\u6BCF\u7AE0\u723D\u70B9\u6A21\u5F0F\uFF1A\u7AE0\u5185\u4E24\u4E2A\u723D\u70B9\uFF08\u62FF\u8BC1\u636E/\u53CD\u6D3E\u88AB\u5F00\uFF09\uFF0C\u7AE0\u672B\u94A9\u5B50\uFF08\u80CC\u540E\u6709\u4EBA\uFF09\uFF0C\u5C42\u5C42\u9012\u8FDB"
    }
  ],
  threshold_overrides: {
    infoPointsPerThousand: 4,
    maxExpositionContinuous: 200,
    maxParagraphLength: 100,
    targetParagraphLength: 45
  },
  radar_weights: {
    bodyReaction: 1.1,
    sensorySignal: 0.8,
    action: 1.4,
    emotion: 1.3,
    infoAdvance: 1.1
  }
};

// src/kb/nodes/node_payoff_frequency/opt_payoff_sparse.kb.json
var opt_payoff_sparse_kb_default = {
  kb_version: "2.0",
  node_id: "node_payoff_frequency",
  option_id: "opt_payoff_sparse",
  option_name: "\u957F\u7EBF\u5E03\u5C40\uFF085\u7AE0+\uFF09",
  option_description: "\u723D\u70B9\u7A00\u758F\uFF0C5\u7AE0\u4EE5\u4E0A\u624D\u6709\u4E00\u4E2A\u5927\u7206\u53D1\u3002\u91CD\u5728\u957F\u7EBF\u5E03\u5C40\u3001\u4F0F\u7B14\u57CB\u8BBE\u3001\u4EBA\u7269\u6210\u957F\uFF0C\u9002\u5408\u786C\u6838\u5267\u60C5\u6D41\u3001\u60AC\u7591\u63A8\u7406\u3001\u53F2\u8BD7\u7C7B\u4F5C\u54C1\u3002",
  system_prompt: "\u4F60\u91C7\u7528\u957F\u7EBF\u5E03\u5C40\u7684\u8282\u594F\u6A21\u5F0F\u3002\u723D\u70B9/\u5927\u7206\u53D1\u7684\u95F4\u9694\u57285\u7AE0\u4EE5\u4E0A\uFF0C\u4E2D\u95F4\u5927\u91CF\u7BC7\u5E45\u7528\u4E8E\u4F0F\u7B14\u57CB\u8BBE\u3001\u4EBA\u7269\u5851\u9020\u3001\u4E16\u754C\u89C2\u5C55\u5F00\u3001\u60C5\u611F\u94FA\u57AB\u3002\u8BFB\u8005\u83B7\u5F97\u7684\u4E0D\u662F\u5373\u65F6\u6EE1\u8DB3\uFF0C\u800C\u662F\u201C\u4F0F\u7B14\u56DE\u6536\u65F6\u7684\u9707\u64BC\u201D\u3002\u4F60\u9700\u8981\u7CBE\u5FC3\u5E03\u5C40\uFF1A\u524D\u671F\u770B\u4F3C\u65E0\u5173\u7684\u7EC6\u8282\uFF0C\u5230\u7206\u53D1\u65F6\u5168\u90E8\u4E32\u8054\u8D77\u6765\uFF0C\u7ED9\u8BFB\u8005\u201C\u539F\u6765\u5982\u6B64\uFF01\u201D\u7684\u5DE8\u5927\u5FEB\u611F\u3002\u4E2D\u95F4\u7AE0\u8282\u4E0D\u80FD\u65E0\u804A\u2014\u2014\u8981\u7528\u60AC\u5FF5\u3001\u4EBA\u7269\u9B45\u529B\u3001\u4E16\u754C\u89C2\u8C1C\u56E2\u6765\u4FDD\u6301\u8BFB\u8005\u7684\u9605\u8BFB\u52A8\u529B\u3002\u6BCF\u4E00\u4E2A\u201C\u95F2\u7B14\u201D\u90FD\u53EF\u80FD\u662F\u4F0F\u7B14\uFF0C\u8981\u8BA9\u4E8C\u5237\u7684\u8BFB\u8005\u80FD\u53D1\u73B0\u524D\u9762\u57CB\u7684\u7EBF\u7D22\u3002\u7206\u53D1\u65F6\u5FC5\u987B\u5C06\u524D\u9762\u6240\u6709\u7EBF\u7D22\u6536\u62E2\uFF0C\u5F62\u6210\u5F3A\u70C8\u7684\u60C5\u611F\u51B2\u51FB\u548C\u667A\u529B\u6EE1\u8DB3\u3002",
  constraints: [
    "\u5927\u723D\u70B9/\u5927\u7206\u53D1\u95F4\u96945\u7AE0\u4EE5\u4E0A\uFF0C\u91CD\u5728\u957F\u7EBF\u5E03\u5C40",
    "\u6BCF\u7AE0\u5FC5\u987B\u6709\u81F3\u5C111\u4E2A\u60AC\u5FF5\u70B9\u6216\u4F0F\u7B14\u7EBF\u7D22\uFF0C\u4E0D\u80FD\u7EAF\u94FA\u57AB\u65E0\u4FE1\u606F\u91CF",
    "\u524D\u671F\u57CB\u7684\u4F0F\u7B14\u5FC5\u987B\u5728\u7206\u53D1\u65F6\u56DE\u6536\uFF0C\u7981\u6B62\u70C2\u5C3E\u4F0F\u7B14",
    "\u4E2D\u95F4\u7AE0\u8282\u7528\u60AC\u5FF5\u3001\u4EBA\u7269\u9B45\u529B\u3001\u4E16\u754C\u89C2\u8C1C\u56E2\u7EF4\u6301\u9605\u8BFB\u52A8\u529B",
    "\u7206\u53D1\u7AE0\u8282\u5FC5\u987B\u5C06\u591A\u6761\u7EBF\u7D22\u6536\u62E2\uFF0C\u5F62\u6210\u201C\u539F\u6765\u5982\u6B64\u201D\u7684\u9707\u64BC\u6548\u679C",
    "\u4F0F\u7B14\u8981\u81EA\u7136\uFF0C\u4E0D\u80FD\u523B\u610F\u5230\u8BFB\u8005\u4E00\u773C\u5C31\u770B\u51FA\u201C\u8FD9\u662F\u4F0F\u7B14\u201D",
    "\u4EBA\u7269\u6210\u957F\u7EBF\u5FC5\u987B\u548C\u5927\u7206\u53D1\u547C\u5E94\uFF0C\u8BA9\u723D\u70B9\u540C\u65F6\u662F\u4EBA\u7269\u5F27\u5149\u7684\u9876\u70B9"
  ],
  examples: [
    {
      text: '\u3010\u7B2C1-4\u7AE0 \u957F\u7EBF\u5E03\u5C40\u3011\n\u7B2C1\u7AE0\uFF1A\u4FA6\u63A2\u9648\u9ED8\u7B2C\u4E00\u6B21\u8FDB\u5165\u5E84\u56ED\uFF0C\u6CE8\u610F\u5230\u58C1\u7089\u65C1\u7684\u5730\u6BEF\u4E0A\u6709\u4E00\u5C0F\u5757\u4E0D\u6613\u5BDF\u89C9\u7684\u6DF1\u8272\u75D5\u8FF9\u3002\u7BA1\u5BB6\u8BF4\u90A3\u662F\u7EA2\u9152\u6E0D\u3002\uFF08\u4F0F\u7B14\uFF1A\u8840\u8FF9\uFF09\n\u7B2C2\u7AE0\uFF1A\u9648\u9ED8\u548C\u4E8C\u5C0F\u59D0\u4EA4\u8C08\u65F6\uFF0C\u5979\u4E0B\u610F\u8BC6\u5730\u6478\u4E86\u6478\u5DE6\u624B\u65E0\u540D\u6307\u2014\u2014\u90A3\u91CC\u6709\u4E00\u5708\u5F88\u6D45\u7684\u767D\u5370\uFF0C\u4F46\u5979\u5E76\u6CA1\u6709\u6234\u6212\u6307\u3002\uFF08\u4F0F\u7B14\uFF1A\u5A5A\u59FB\u79D8\u5BC6\uFF09\n\u7B2C3\u7AE0\uFF1A\u9648\u9ED8\u5728\u4E66\u623F\u53D1\u73B0\u4E00\u5C01\u70E7\u6BC1\u4E00\u534A\u7684\u4FE1\uFF0C\u53EA\u80FD\u8FA8\u8BA4\u51FA\u201C\u2026\u2026\u4E0D\u80FD\u8BA9\u4ED6\u77E5\u9053\u2026\u2026\u9057\u4EA7\u2026\u2026\u201D\u51E0\u4E2A\u5B57\u3002\uFF08\u4F0F\u7B14\uFF1A\u52A8\u673A\uFF09\n\u7B2C4\u7AE0\uFF1A\u665A\u5BB4\u4E0A\uFF0C\u5927\u5C11\u7237\u63D0\u5230\u6848\u53D1\u5F53\u665A\u4ED6\u5728\u4E66\u623F\u770B\u4E66\uFF0C\u4F46\u9648\u9ED8\u6CE8\u610F\u5230\u4E66\u623F\u7684\u53F0\u706F\u706F\u6CE1\u662F\u51B7\u7684\u3002\uFF08\u4F0F\u7B14\uFF1A\u4E0D\u5728\u573A\u8BC1\u660E\u9020\u5047\uFF09\n\n\u3010\u7B2C5\u7AE0 \u7206\u53D1\u3011\n\u9648\u9ED8\u628A\u6240\u6709\u4EBA\u53EC\u96C6\u5230\u5BA2\u5385\uFF0C\u7F13\u7F13\u8BF4\u9053\uFF1A\n\n"\u51F6\u624B\u5C31\u5728\u8FD9\u4E2A\u623F\u95F4\u91CC\u3002"\n\n\u4ED6\u4E00\u4E00\u5217\u4E3E\u8BC1\u636E\uFF1A\u58C1\u7089\u65C1\u7684\u8840\u8FF9\u7ECF\u8FC7\u68C0\u6D4B\u662F\u4EBA\u8840\u800C\u975E\u7EA2\u9152\u3001\u4E8C\u5C0F\u59D0\u6697\u4E2D\u6210\u5A5A\u7684\u5BF9\u8C61\u662F\u6B7B\u8005\u7684\u79C1\u751F\u5B50\u3001\u70E7\u6BC1\u7684\u4FE1\u662F\u6B7B\u8005\u66F4\u6539\u9057\u5631\u7684\u8BC1\u636E\u3001\u5927\u5C11\u7237\u7684\u4E0D\u5728\u573A\u8BC1\u660E\u56E0\u4E3A\u51B7\u706F\u6CE1\u800C\u4E0D\u653B\u81EA\u7834\u2026\u2026\n\n\u6240\u6709\u7EBF\u7D22\u6C47\u805A\u5230\u4E00\u4E2A\u4EBA\u8EAB\u4E0A\u2014\u2014\n\n\u7BA1\u5BB6\u7684\u8138\u8272\u8D8A\u6765\u8D8A\u767D\uFF0C\u7EC8\u4E8E\u762B\u5012\u5728\u6905\u5B50\u4E0A\u3002',
      note: "\u957F\u7EBF\u5E03\u5C40\u6A21\u5F0F\uFF1A\u524D4\u7AE0\u5206\u6563\u4F0F\u7B14\uFF08\u8840\u8FF9/\u6212\u6307\u5370/\u70E7\u6BC1\u4FE1/\u51B7\u706F\u6CE1\uFF09\uFF0C\u7B2C5\u7AE0\u96C6\u4E2D\u63A8\u7406\u56DE\u6536\uFF0C\u667A\u529B\u723D\u611F\u5F3A\u70C8"
    }
  ],
  threshold_overrides: {
    infoPointsPerThousand: 2,
    maxExpositionContinuous: 500,
    maxParagraphLength: 250,
    targetParagraphLength: 80,
    shortSentenceRatio: 0.3
  },
  radar_weights: {
    bodyReaction: 0.8,
    sensorySignal: 1,
    action: 0.8,
    emotion: 1,
    infoAdvance: 1.4
  }
};

