var opt_platform_generic_kb_default = {
  kb_version: "2.0",
  node_id: "node_platform",
  option_id: "opt_platform_generic",
  option_name: "\u901A\u7528\uFF08\u9ED8\u8BA4\uFF09",
  option_description: "\u901A\u7528\u5E73\u53F0\u98CE\u683C\uFF0C\u4E0D\u9488\u5BF9\u7279\u5B9A\u5E73\u53F0\u505A\u4F18\u5316\uFF0C\u91C7\u7528\u5E73\u8861\u7684\u8282\u594F\u548C\u5199\u6CD5\uFF0C\u9002\u5408\u591A\u5E73\u53F0\u5206\u53D1\u6216\u4E0D\u786E\u5B9A\u53D1\u5E03\u5E73\u53F0\u65F6\u4F7F\u7528\u3002",
  system_prompt: "\u4F60\u91C7\u7528\u901A\u7528\u7F51\u6587\u5199\u4F5C\u98CE\u683C\uFF0C\u4E0D\u9488\u5BF9\u7279\u5B9A\u5E73\u53F0\u505A\u7279\u6B8A\u4F18\u5316\u3002\u4FDD\u6301\u5747\u8861\u7684\u8282\u594F\uFF1A\u5F00\u7BC7\u6709\u5438\u5F15\u529B\u4F46\u4E0D\u8FC7\u4E8E\u6025\u4FC3\uFF0C\u63CF\u5199\u9002\u5EA6\u4E0D\u5197\u4F59\uFF0C\u723D\u70B9\u5206\u5E03\u5747\u5300\uFF0C\u6BB5\u843D\u957F\u5EA6\u9002\u4E2D\u3002\u517C\u987E\u5404\u7C7B\u8BFB\u8005\u7684\u9605\u8BFB\u4E60\u60EF\uFF0C\u65E2\u4E0D\u5199\u5F97\u592A\u788E\u4E5F\u4E0D\u5199\u5927\u5757\u6587\u5B57\u3002\u5BF9\u8BDD\u548C\u63CF\u5199\u6BD4\u4F8B\u5747\u8861\uFF0C\u60C5\u611F\u548C\u5267\u60C5\u5E76\u91CD\u3002",
  constraints: [
    "\u5F00\u7BC7\u524D1000\u5B57\u5185\u51FA\u73B0\u6838\u5FC3\u51B2\u7A81\u6216\u60AC\u5FF5",
    "\u6BB5\u843D\u957F\u5EA6\u9002\u4E2D\uFF0C\u5355\u6BB550-150\u5B57",
    "\u723D\u70B9\u5206\u5E03\u5747\u5300\uFF0C\u7EA6\u6BCF2000\u5B57\u4E00\u4E2A\u5C0F\u9AD8\u6F6E",
    "\u5BF9\u8BDD\u4E0E\u53D9\u8FF0\u63CF\u5199\u6BD4\u4F8B\u7EA6\u4E3A4:6",
    "\u907F\u514D\u6781\u7AEF\u5199\u6CD5\uFF08\u4E0D\u8981\u592A\u6C34\u4E5F\u4E0D\u8981\u592A\u8D76\uFF09",
    "\u7528\u8BCD\u89C4\u8303\uFF0C\u907F\u514D\u8FC7\u4E8E\u5C0F\u4F17\u7684\u7F51\u7EDC\u9ED1\u8BDD",
    "\u6BCF\u7AE0\u7ED3\u5C3E\u7559\u9002\u5F53\u60AC\u5FF5\u4F46\u4E0D\u5FC5\u5F3A\u884C\u53CD\u8F6C"
  ],
  examples: [
    {
      text: '\u9648\u9ED8\u63A8\u5F00\u5BBF\u820D\u95E8\u7684\u65F6\u5019\uFF0C\u5BA4\u53CB\u4EEC\u6B63\u5728\u8BA8\u8BBA\u5468\u672B\u53BB\u54EA\u73A9\u3002\n\n"\u9ED8\u54E5\uFF0C\u4E00\u8D77\u53BB\u722C\u5C71\u554A\uFF1F"\u738B\u80D6\u5B50\u63A2\u51FA\u5934\u6765\u3002\n\n"\u4E0D\u53BB\u4E86\uFF0C\u6211\u8FD8\u6709\u4E8B\u3002"\u9648\u9ED8\u628A\u4E66\u5305\u653E\u4E0B\uFF0C\u82E5\u6709\u6240\u601D\u3002\n\n\u4ECA\u5929\u4E0B\u5348\uFF0C\u4ED6\u5728\u65E7\u4E66\u644A\u4E0A\u4E70\u5230\u4E86\u4E00\u5757\u5947\u602A\u7684\u94DC\u724C\uFF0C\u4E0A\u9762\u523B\u7740\u4ED6\u4ECE\u672A\u89C1\u8FC7\u7684\u6587\u5B57\u3002\u94DC\u724C\u5165\u624B\u6E29\u70ED\uFF0C\u9690\u9690\u6709\u79CD\u8BF4\u4E0D\u51FA\u7684\u611F\u89C9\u3002\n\n\u4ED6\u628A\u94DC\u724C\u4ECE\u53E3\u888B\u91CC\u638F\u51FA\u6765\uFF0C\u653E\u5728\u684C\u4E0A\u3002\u706F\u5149\u4E0B\uFF0C\u94DC\u724C\u8868\u9762\u7684\u7EB9\u8DEF\u4F3C\u4E4E\u5FAE\u5FAE\u4EAE\u4E86\u4E00\u4E0B\u3002\n\n"\u8FD9\u4EC0\u4E48\u73A9\u610F\u513F\uFF1F"\u738B\u80D6\u5B50\u51D1\u8FC7\u6765\uFF0C"\u770B\u8D77\u6765\u633A\u8001\u7684\uFF0C\u5730\u644A\u4E0A\u6DD8\u7684\uFF1F"\n\n"\u55EF\u3002"\u9648\u9ED8\u5E94\u4E86\u4E00\u58F0\uFF0C\u4F38\u624B\u60F3\u53BB\u62FF\u94DC\u724C\u2014\u2014\n\n\u6307\u5C16\u89E6\u5230\u94DC\u724C\u7684\u77AC\u95F4\uFF0C\u4E00\u9053\u91D1\u5149\u95EA\u8FC7\uFF0C\u4ED6\u6574\u4E2A\u4EBA\u6D88\u5931\u5728\u539F\u5730\u3002\n\n\u5BBF\u820D\u91CC\uFF0C\u738B\u80D6\u5B50\u76EE\u77AA\u53E3\u5446\u5730\u770B\u7740\u7A7A\u8361\u8361\u7684\u5EA7\u4F4D\uFF0C\u624B\u91CC\u8FD8\u62FF\u7740\u534A\u888B\u85AF\u7247\u3002',
      note: "\u901A\u7528\u98CE\u5F00\u7BC7\uFF1A\u65E5\u5E38\u573A\u666F\u5F15\u5165\u2192\u6838\u5FC3\u7269\u4EF6\uFF08\u94DC\u724C\uFF09\u2192\u60AC\u5FF5\uFF08\u6D88\u5931\uFF09\uFF0C\u8282\u594F\u5E73\u8861\uFF0C\u63CF\u5199\u5BF9\u8BDD\u5747\u8861"
    }
  ],
  threshold_overrides: {},
  radar_weights: {
    bodyReaction: 1,
    sensorySignal: 1,
    action: 1,
    emotion: 1,
    infoAdvance: 1
  }
};

