var opt_pov_first_past_kb_default = {
  kb_version: "2.0",
  node_id: "node_pov",
  option_id: "opt_pov_first_past",
  option_name: "\u7B2C\u4E00\u4EBA\u79F0\u8FC7\u53BB\u5F0F",
  option_description: "\u4EE5\u201C\u6211\u201D\u7684\u89C6\u89D2\u53D9\u8FF0\uFF0C\u4F7F\u7528\u8FC7\u53BB\u65F6\u6001\u3002\u4EE3\u5165\u611F\u6781\u5F3A\uFF0C\u8BFB\u8005\u76F4\u63A5\u4F53\u9A8C\u4E3B\u89D2\u7684\u611F\u53D7\u548C\u601D\u8003\uFF0C\u9002\u5408\u60AC\u7591\u3001\u81EA\u4F20\u3001\u60C5\u611F\u7C7B\u4F5C\u54C1\u3002",
  system_prompt: "\u4F60\u4F7F\u7528\u7B2C\u4E00\u4EBA\u79F0\u8FC7\u53BB\u5F0F\u8FDB\u884C\u5199\u4F5C\u3002\u53D9\u8FF0\u8005\u662F\u201C\u6211\u201D\u2014\u2014\u6545\u4E8B\u7684\u4E3B\u89D2\u6216\u67D0\u4E2A\u89C6\u89D2\u4EBA\u7269\uFF0C\u6240\u6709\u4E8B\u4EF6\u90FD\u7528\u8FC7\u53BB\u65F6\u6001\u63CF\u8FF0\uFF08\u201C\u6211\u8D70\u4E86\u201D\u201C\u6211\u770B\u5230\u4E86\u201D\u201C\u6211\u60F3\u201D\uFF09\u3002\u56E0\u4E3A\u662F\u7B2C\u4E00\u4EBA\u79F0\uFF0C\u4F60\u53EA\u80FD\u5199\u201C\u6211\u201D\u4EB2\u773C\u770B\u5230\u3001\u4EB2\u8033\u542C\u5230\u3001\u4EB2\u8EAB\u7ECF\u5386\u7684\u4E8B\u60C5\uFF0C\u4E0D\u80FD\u76F4\u63A5\u5199\u522B\u4EBA\u7684\u5FC3\u7406\u6D3B\u52A8\u2014\u2014\u522B\u4EBA\u600E\u4E48\u60F3\u7684\uFF0C\u53EA\u80FD\u901A\u8FC7\u4ED6\u4EEC\u7684\u8868\u60C5\u3001\u52A8\u4F5C\u3001\u8BED\u8A00\u6765\u63A8\u6D4B\u3002\u201C\u6211\u201D\u7684\u5185\u5FC3\u72EC\u767D\u3001\u611F\u53D7\u3001\u56DE\u5FC6\u53EF\u4EE5\u81EA\u7531\u5199\uFF0C\u8FD9\u662F\u7B2C\u4E00\u4EBA\u79F0\u7684\u4F18\u52BF\u3002\u4EE3\u5165\u611F\u662F\u7B2C\u4E00\u4EBA\u79F0\u7684\u751F\u547D\uFF0C\u8981\u8BA9\u8BFB\u8005\u89C9\u5F97\u201C\u6211\u5C31\u662F\u4E3B\u89D2\u201D\u3002\u6CE8\u610F\u65F6\u6001\u4E00\u81F4\u6027\uFF0C\u4E0D\u8981\u5728\u8FC7\u53BB\u5F0F\u4E2D\u6DF7\u5165\u73B0\u5728\u5F0F\uFF08\u9664\u975E\u662F\u89D2\u8272\u5F53\u4E0B\u7684\u5FC3\u7406\u6D3B\u52A8\u53EF\u4EE5\u7528\u73B0\u5728\u5F0F\u8868\u8FBE\u5373\u65F6\u611F\u53D7\uFF0C\u4F46\u53D9\u8FF0\u4E3B\u7EBF\u5FC5\u987B\u662F\u8FC7\u53BB\u5F0F\uFF09\u3002",
  constraints: [
    "\u53D9\u8FF0\u89C6\u89D2\u4E25\u683C\u4E3A\u7B2C\u4E00\u4EBA\u79F0\u201C\u6211\u201D\uFF0C\u4E0D\u5F97\u5207\u6362\u5230\u5176\u4ED6\u4EBA\u7269\u7684\u5185\u5FC3",
    "\u65F6\u6001\u4EE5\u8FC7\u53BB\u5F0F\u4E3A\u4E3B\uFF08\u4E86/\u8FC7/\u5F53\u65F6/\u66FE\u7ECF/\u5DF2\u7ECF\uFF09\uFF0C\u53D9\u8FF0\u4E3B\u7EBF\u4FDD\u6301\u4E00\u81F4",
    "\u53EA\u80FD\u5199\u201C\u6211\u201D\u4EB2\u773C\u6240\u89C1\u3001\u4EB2\u8033\u6240\u95FB\u3001\u4EB2\u8EAB\u7ECF\u5386\uFF0C\u7981\u6B62\u5168\u77E5\u89C6\u89D2",
    "\u4ED6\u4EBA\u5FC3\u7406\u53EA\u80FD\u901A\u8FC7\u8868\u60C5\u3001\u52A8\u4F5C\u3001\u8BED\u8A00\u63A8\u6D4B\uFF0C\u4E0D\u80FD\u76F4\u63A5\u5199\u201C\u4ED6\u5FC3\u60F3\u201D\u201C\u5979\u6697\u81EA\u9AD8\u5174\u201D",
    "\u5145\u5206\u5229\u7528\u7B2C\u4E00\u4EBA\u79F0\u4F18\u52BF\uFF1A\u5185\u5FC3\u72EC\u767D\u3001\u611F\u5B98\u4F53\u9A8C\u3001\u4E2A\u4EBA\u56DE\u5FC6\u3001\u60C5\u611F\u6CE2\u52A8",
    "\u7981\u6B62\u5728\u53D9\u8FF0\u4E2D\u51FA\u73B0\u201C\u6211\u201D\u4E0D\u53EF\u80FD\u77E5\u9053\u7684\u4FE1\u606F",
    "\u5982\u679C\u662F\u56DE\u5FC6\u5F0F\u53D9\u8FF0\uFF08\u73B0\u5728\u7684\u6211\u56DE\u5FC6\u8FC7\u53BB\u7684\u4E8B\uFF09\uFF0C\u53EF\u4EE5\u6709\u73B0\u5728\u7684\u89C6\u89D2\u8BC4\u8BBA\uFF0C\u4F46\u8981\u6E05\u6670\u533A\u5206"
  ],
  examples: [
    {
      text: "\u6211\u63A8\u5F00\u90A3\u6247\u95E8\u7684\u65F6\u5019\uFF0C\u6CA1\u6709\u60F3\u5230\u95E8\u540E\u7B49\u7740\u6211\u7684\u4F1A\u662F\u4EC0\u4E48\u3002\n\n\u5C4B\u5B50\u91CC\u5F88\u6697\uFF0C\u7A97\u5E18\u62C9\u5F97\u4E25\u4E25\u5B9E\u5B9E\u3002\u6211\u6478\u7D22\u7740\u627E\u5230\u5F00\u5173\uFF0C\u706F\u4EAE\u7684\u77AC\u95F4\uFF0C\u6211\u5012\u5438\u4E86\u4E00\u53E3\u51B7\u6C14\u3002\n\n\u5899\u4E0A\u8D34\u6EE1\u4E86\u7167\u7247\u2014\u2014\u5168\u662F\u6211\u3002\n\n\u6211\u7AD9\u5728\u95E8\u53E3\uFF0C\u540E\u80CC\u6CDB\u8D77\u4E00\u5C42\u51B7\u6C57\u3002\u8FD9\u4E9B\u7167\u7247\u6709\u6211\u5728\u516C\u53F8\u52A0\u73ED\u7684\uFF0C\u6709\u6211\u5728\u8D85\u5E02\u4E70\u83DC\u7684\uFF0C\u751A\u81F3\u6709\u6211\u5728\u5367\u5BA4\u91CC\u7761\u89C9\u7684\u3002\u6709\u4EBA\u4E00\u76F4\u5728\u8DDF\u8E2A\u6211\uFF0C\u800C\u4E14\u5DF2\u7ECF\u5F88\u4E45\u4E86\u3002\n\n\u6211\u7684\u624B\u5F00\u59CB\u53D1\u6296\uFF0C\u4F46\u6211\u5F3A\u8FEB\u81EA\u5DF1\u51B7\u9759\u4E0B\u6765\u3002\u6211\u638F\u51FA\u624B\u673A\u51C6\u5907\u62A5\u8B66\uFF0C\u5C31\u5728\u8FD9\u65F6\uFF0C\u8EAB\u540E\u4F20\u6765\u4E86\u811A\u6B65\u58F0\u3002\n\n\u5F88\u8F7B\uFF0C\u5F88\u6162\uFF0C\u4F46\u6BCF\u4E00\u6B65\u90FD\u50CF\u8E29\u5728\u6211\u7684\u5FC3\u810F\u4E0A\u3002\n\n\u6211\u731B\u5730\u8F6C\u8FC7\u8EAB\u2014\u2014",
      note: "\u7B2C\u4E00\u4EBA\u79F0\u8FC7\u53BB\u5F0F\uFF1A\u4F7F\u7528\u201C\u6211\u201D\u89C6\u89D2\uFF0C\u8FC7\u53BB\u65F6\u6001\uFF08\u63A8\u5F00/\u6CA1\u6709\u60F3\u5230/\u627E\u5230/\u5012\u5438\uFF09\uFF0C\u76F4\u63A5\u5C55\u73B0\u4E3B\u89D2\u7684\u6050\u60E7\uFF08\u51B7\u6C57/\u53D1\u6296/\u5FC3\u810F\u4E0A\uFF09\uFF0C\u65E0\u6CD5\u77E5\u9053\u8DDF\u8E2A\u8005\u7684\u60F3\u6CD5"
    }
  ],
  threshold_overrides: {
    minSensoryTypes: 3,
    sightRatio: 0.45
  },
  radar_weights: {
    bodyReaction: 1.4,
    sensorySignal: 1.2,
    action: 0.9,
    emotion: 1.4,
    infoAdvance: 0.9
  }
};

