var opt_rhythm_short_kb_default = {
  kb_version: "2.0",
  node_id: "node_sentence_rhythm",
  option_id: "opt_rhythm_short",
  option_name: "\u77ED\u53E5\u4E3A\u4E3B",
  option_description: "\u4EE5\u77ED\u53E5(<=15\u5B57)\u4E3A\u4E3B\u5BFC\u8282\u594F\uFF0C\u5E72\u8106\u5229\u843D\uFF0C\u50CF\u9F13\u70B9\u822C\u6572\u51FB\u3002\u9002\u5408\u7D27\u5F20\u573A\u666F\u3001\u52A8\u4F5C\u573A\u9762\u548C\u5FEB\u8282\u594F\u53D9\u4E8B\uFF0C\u4E5F\u662F\u77FF\u5DE5\u98CE\u683C\u6838\u5FC3\u8282\u594F\u3002",
  threshold_overrides: {
    maxSentenceLength: 20,
    targetSentenceLength: 12,
    shortSentenceRatio: 0.7,
    maxParagraphLength: 120,
    targetParagraphLength: 50
  },
  radar_weights: {
    action: 1.3,
    emotion: 1.1,
    infoAdvance: 0.9,
    sensorySignal: 1.1
  },
  system_prompt: "\u77ED\u53E5\u8282\u594F\u7684\u6838\u5FC3\u662F'\u4E00\u51FB\u5373\u4E2D'\u3002\u6BCF\u53E5\u8BDD\u53EA\u4F20\u9012\u4E00\u4E2A\u4FE1\u606F\u70B9\uFF0C\u50CF\u51FA\u62F3\u3001\u50CF\u9F13\u70B9\u3001\u50CF\u5FC3\u8DF3\u3002\u8BFB\u8005\u6CA1\u6709\u5598\u606F\u7A7A\u95F4\uFF0C\u7D27\u5F20\u611F\u81EA\u7136\u751F\u6210\u3002\u5177\u4F53\u6280\u6CD5\uFF1A\n\n1. \u5355\u4FE1\u606F\u539F\u5219\uFF1A\u6BCF\u53E5\u8BDD\u53EA\u5199\u4E00\u4E2A\u52A8\u4F5C\u3001\u4E00\u4E2A\u611F\u5B98\u3001\u4E00\u4E2A\u5FF5\u5934\u3002\u4E0D\u8981\u628A\u4E24\u4E2A\u52A8\u4F5C\u585E\u8FDB\u540C\u4E00\u53E5\u3002'\u4ED6\u8F6C\u8EAB\uFF0C\u62D4\u51FA\u5200'\u8981\u62C6\u6210'\u4ED6\u8F6C\u8EAB\u3002''\u62D4\u51FA\u5200\u3002'\u3002\u53E5\u53F7\u5C31\u662F\u505C\u987F\uFF0C\u505C\u987F\u5C31\u662F\u91CD\u91CF\u3002\n\n2. \u65AD\u53E5\u8981\u72E0\uFF1A\u80FD\u7528\u53E5\u53F7\u5C31\u4E0D\u7528\u9017\u53F7\uFF0C\u80FD\u62C6\u6210\u4E24\u53E5\u5C31\u4E0D\u5408\u6210\u4E00\u53E5\u3002'\u4ED6\u770B\u89C1\u8001\u674E\u5012\u5728\u5730\u4E0A\uFF0C\u80F8\u53E3\u5728\u6D41\u8840'\u8981\u62C6\u6210'\u8001\u674E\u5012\u5728\u5730\u4E0A\u3002''\u80F8\u53E3\u5728\u6D41\u8840\u3002'\u3002\u6BCF\u4E00\u53E5\u5355\u72EC\u6210\u6BB5\uFF0C\u51B2\u51FB\u529B\u7FFB\u500D\u3002\n\n3. \u540D\u8BCD\u52A8\u8BCD\u4F18\u5148\uFF1A\u77ED\u53E5\u4E2D\u5C11\u7528\u5F62\u5BB9\u8BCD\u548C\u526F\u8BCD\u3002\u7528\u540D\u8BCD\u548C\u540D\u8BCD\u3001\u52A8\u8BCD\u548C\u540D\u8BCD\u76F4\u63A5\u78B0\u649E\u3002'\u5200\u5F88\u5FEB\u3002''\u8840\u5F88\u70ED\u3002''\u5899\u5F88\u786C\u3002'\u4E0D\u9700\u8981\u4FEE\u9970\uFF0C\u4E8B\u5B9E\u672C\u8EAB\u5C31\u6709\u529B\u91CF\u3002\n\n4. \u7559\u767D\u5236\u9020\u91CD\u97F3\uFF1A\u5173\u952E\u77AC\u95F4\u524D\u540E\u52A0\u7A7A\u884C\u6216\u6781\u77ED\u53E5\uFF081-3\u5B57\uFF09\u3002'\u4ED6\u62AC\u5934\u3002''\u4E00\u4E2A\u5B57\u3002''\u6B7B\u3002'\u5355\u72EC\u6210\u6BB5\uFF0C\u50CF\u9524\u5B50\u7838\u4E0B\u6765\u3002\n\n5. \u8282\u594F\u53D8\u5316\uFF1A\u5168\u662F\u77ED\u53E5\u4E5F\u4F1A\u75B2\u52B3\u3002\u6BCF10-15\u53E5\u77ED\u53E5\u540E\uFF0C\u53EF\u4EE5\u63D2\u5165\u4E00\u53E5\u7A0D\u957F\u7684\u53E5\u5B50\uFF0820-25\u5B57\uFF09\u4F5C\u4E3A\u8282\u594F\u8C03\u5242\uFF0C\u4F46\u7ACB\u523B\u56DE\u5230\u77ED\u53E5\u3002\u957F\u53E5\u662F\u4E3A\u4E86\u8BA9\u63A5\u4E0B\u6765\u7684\u77ED\u53E5\u66F4\u6709\u529B\u3002\n\n6. \u611F\u5B98\u788E\u7247\u5316\uFF1A\u628A\u611F\u5B98\u4F53\u9A8C\u62C6\u6210\u788E\u7247\u2014\u2014\u4E0D\u662F'\u4ED6\u542C\u5230\u5DE8\u5927\u7684\u7206\u70B8\u58F0\u611F\u5230\u4E00\u9635\u5267\u75DB'\uFF0C\u800C\u662F'\u58F0\u97F3\u6765\u4E86\u3002''\u8033\u6735\u55E1\u7684\u4E00\u4E0B\u3002''\u75BC\u3002''\u4EC0\u4E48\u90FD\u770B\u4E0D\u89C1\u3002'\u3002\u788E\u7247\u5316\u66F4\u63A5\u8FD1\u4EBA\u5728\u6781\u7AEF\u72B6\u6001\u4E0B\u7684\u771F\u5B9E\u611F\u77E5\u3002\n\n7. \u7981\u6B62\u89E3\u91CA\uFF1A\u77ED\u53E5\u4E0D\u89E3\u91CA\u3002\u4E0D\u8BF4'\u56E0\u4E3A\u74E6\u65AF\u6D53\u5EA6\u592A\u9AD8\u6240\u4EE5\u4ED6\u4EEC\u5FC5\u987B\u64A4\u9000'\uFF0C\u53EA\u5199'\u74E6\u65AF\u54CD\u4E86\u3002''\u8D70\u3002'\u3002\u8BFB\u8005\u81EA\u5DF1\u4F1A\u8FDE\u8D77\u6765\u3002",
  constraints: [
    "\u5355\u53E5\u539F\u5219\u4E0A\u4E0D\u8D85\u8FC720\u5B57\uFF0C90%\u53E5\u5B50\u572815\u5B57\u4EE5\u5185",
    "\u77ED\u53E5\uFF0815\u5B57\u4EE5\u5185\uFF09\u5360\u6BD470%\u4EE5\u4E0A",
    "\u7981\u6B62\u8FDE\u7EED3\u53E5\u4EE5\u4E0A\u8D85\u8FC715\u5B57\u7684\u53E5\u5B50",
    "\u6BCF200\u5B57\u81F3\u5C11\u67091\u59041-3\u5B57\u7684\u6781\u77ED\u53E5\u5355\u72EC\u6210\u6BB5\u4F5C\u4E3A\u91CD\u97F3",
    "\u907F\u514D\u4F7F\u7528\u5206\u53F7\u8FDE\u63A5\u591A\u4E2A\u5206\u53E5\uFF0C\u5C11\u7528\u7834\u6298\u53F7\u548C\u7701\u7565\u53F7",
    "\u52A8\u4F5C\u573A\u666F\u4E2D\u6BCF\u53E5\u53EA\u5305\u542B\u4E00\u4E2A\u52A8\u4F5C\uFF0C\u7981\u6B62\u8FDE\u52A8\u53E5\uFF08'\u4ED6\u8F6C\u8EAB\u62D4\u51FA\u5200\u51B2\u51FA\u53BB'\u5FC5\u987B\u62C6\u5F00\uFF09",
    "\u5F62\u5BB9\u8BCD\u548C\u526F\u8BCD\u4F7F\u7528\u5BC6\u5EA6\u4E0D\u8D85\u8FC7\u6BCF100\u5B573\u4E2A",
    "\u6BB5\u843D\u957F\u5EA6\u63A7\u5236\u57283-5\u53E5\u4EE5\u5185\uFF0C\u5173\u952E\u52A8\u4F5C\u53EF\u4EE5\u4E00\u53E5\u4E00\u6BB5"
  ],
  examples: [
    {
      text: "\u74E6\u65AF\u62A5\u8B66\u54CD\u4E86\u3002\n\n\u4E0D\u662F\u9884\u8B66\u3002\u662F\u90A3\u79CD\u6301\u7EED\u7684\u3001\u5C16\u9510\u7684\u3001\u8981\u547D\u7684\u54CD\u58F0\u3002\n\n\u4ED6\u62AC\u5934\u770B\u4EEA\u8868\u3002\n\n\u6D53\u5EA61.8%\u3002\n\n\u8D85\u4E86\u3002\n\n\u8001\u674E\u8FD8\u5728\u524D\u9762\u5228\u7164\u3002\u6CA1\u542C\u89C1\u3002\n\n\u4ED6\u6293\u8D77\u77FF\u706F\u5F80\u90A3\u8FB9\u7167\u3002\u5149\u67F1\u6643\u4E86\u4E24\u4E0B\uFF0C\u7167\u89C1\u8001\u674E\u7684\u80CC\u5F71\uFF0C\u5F13\u7740\uFF0C\u50CF\u53EA\u867E\u3002\n\n\u300C\u8001\u674E\uFF01\u300D\n\n\u6CA1\u53CD\u5E94\u3002\n\n\u98CE\u505C\u4E86\u3002\n\n\u4ED6\u77E5\u9053\u8FD9\u610F\u5473\u7740\u4EC0\u4E48\u3002\u901A\u98CE\u7BA1\u4E00\u505C\uFF0C\u74E6\u65AF\u4E09\u5206\u949F\u5C31\u80FD\u5230\u7206\u70B8\u6D53\u5EA6\u3002\n\n\u4ED6\u7AD9\u8D77\u6765\u3002\u819D\u76D6\u649E\u5230\u6A2A\u6881\uFF0C\u75BC\u3002\u987E\u4E0D\u4E0A\u3002\n\n\u300C\u8D70\uFF01\u300D\n\n\u4ED6\u5F80\u524D\u8DD1\u3002\u9774\u5E95\u8E29\u5728\u788E\u7164\u4E0A\u6ED1\u4E86\u4E00\u4E0B\uFF0C\u624B\u6276\u4F4F\u58C1\u9762\uFF0C\u58C1\u9762\u662F\u70EB\u7684\u3002\n\n\u4E0D\u5BF9\u3002\n\n\u4ED6\u505C\u4E0B\u3002\n\n\u4E0D\u662F\u70EB\u3002\n\n\u662F\u5728\u9707\u3002\n\n\u5F88\u8F7B\u3002\u4ECE\u5F88\u6DF1\u7684\u5730\u65B9\u4F20\u4E0A\u6765\u3002\u50CF\u4EC0\u4E48\u4E1C\u897F\u5728\u91CC\u9762\u7FFB\u8EAB\u3002\n\n\u4ED6\u56DE\u5934\u770B\u3002\n\n\u901A\u9053\u53E3\u7684\u65B9\u5411\uFF0C\u6709\u5149\u3002\n\n\u4E0D\u662F\u77FF\u706F\u7684\u5149\u3002\n\n\u662F\u7EA2\u7684\u3002",
      note: "\u77ED\u53E5\u8282\u594F\u793A\u8303\uFF1A\u6574\u6BB5\u5E73\u5747\u53E5\u957F\u4E0D\u8D85\u8FC710\u5B57\uFF0C\u5173\u952E\u8282\u70B9\u75281-3\u5B57\u6781\u77ED\u53E5\uFF08'\u8D85\u4E86\u3002''\u4E0D\u5BF9\u3002''\u8D70\u3002''\u662F\u7EA2\u7684\u3002'\uFF09\u5355\u72EC\u6210\u6BB5\u5236\u9020\u91CD\u97F3\u3002\u6BCF\u53E5\u4E00\u4E2A\u4FE1\u606F\u70B9\uFF1A\u62A5\u8B66\u54CD\u4E86\u2192\u770B\u4EEA\u8868\u2192\u6D53\u5EA61.8%\u2192\u8001\u674E\u6CA1\u542C\u89C1\u2192\u98CE\u505C\u4E86\u2192\u58C1\u9762\u70EB\u2192\u5728\u9707\u2192\u6709\u7EA2\u5149\u3002\u8BFB\u8005\u8DDF\u7740\u53E5\u5B50\u8282\u594F\u4E00\u8D77\u7D27\u5F20\uFF0C\u6CA1\u6709\u4E00\u53E5\u89E3\u91CA\u4E3A\u4EC0\u4E48\u5371\u9669\uFF0C\u8BFB\u8005\u81EA\u5DF1\u61C2\u3002"
    }
  ],
  requires: [],
  conflicts: [
    "opt_rhythm_long"
  ]
};

