var opt_rhythm_mixed_kb_default = {
  kb_version: "2.0",
  node_id: "node_sentence_rhythm",
  option_id: "opt_rhythm_mixed",
  option_name: "\u957F\u77ED\u4EA4\u9519",
  option_description: "\u957F\u77ED\u53E5\u4EA4\u9519\u4F7F\u7528\uFF0C\u8282\u594F\u6709\u8D77\u4F0F\u53D8\u5316\uFF08\u63A8\u8350\u9ED8\u8BA4\uFF09\u3002\u7D27\u5F20\u65F6\u77ED\u4FC3\uFF0C\u8212\u7F13\u65F6\u7EF5\u957F\uFF0C\u5F62\u6210\u81EA\u7136\u7684\u547C\u5438\u8282\u594F\uFF0C\u6587\u5B66\u6027\u548C\u53EF\u8BFB\u6027\u517C\u987E\u3002",
  threshold_overrides: {
    maxSentenceLength: 60,
    targetSentenceLength: 22,
    shortSentenceRatio: 0.4,
    maxParagraphLength: 200,
    targetParagraphLength: 100
  },
  radar_weights: {
    action: 1,
    emotion: 1.2,
    infoAdvance: 1,
    sensorySignal: 1.2,
    bodyReaction: 1.1
  },
  system_prompt: "\u957F\u77ED\u4EA4\u9519\u662F\u6700\u6709\u97F3\u4E50\u611F\u7684\u8282\u594F\uFF0C\u6838\u5FC3\u662F'\u5BF9\u6BD4\u4EA7\u751F\u529B\u91CF'\u3002\u77ED\u53E5\u662F\u9F13\u70B9\uFF0C\u957F\u53E5\u662F\u65CB\u5F8B\uFF1B\u77ED\u53E5\u662F\u62F3\u5934\uFF0C\u957F\u53E5\u662F\u547C\u5438\uFF1B\u77ED\u53E5\u662F\u60CA\u96F7\uFF0C\u957F\u53E5\u662F\u4E91\u5C42\u3002\u4E8C\u8005\u4EA4\u66FF\u51FA\u73B0\uFF0C\u8BFB\u8005\u7684\u60C5\u7EEA\u8DDF\u7740\u8282\u594F\u8D77\u4F0F\u3002\u5177\u4F53\u6280\u6CD5\uFF1A\n\n1. \u573A\u666F\u5339\u914D\u8282\u594F\uFF1A\u52A8\u4F5C/\u7D27\u5F20/\u9707\u60CA\u573A\u666F\u7528\u77ED\u53E5\uFF0C\u63CF\u5199/\u6292\u60C5/\u56DE\u5FC6\u573A\u666F\u7528\u957F\u53E5\uFF0C\u5BF9\u8BDD\u7528\u4E2D\u53E5\u3002\u540C\u4E00\u573A\u666F\u5185\u4E5F\u8981\u6709\u53D8\u5316\u2014\u2014\u6253\u6597\u4E2D\u7A81\u7136\u63D2\u5165\u4E00\u53E5\u957F\u53E5\u63CF\u5199\u73AF\u5883\uFF0C\u53CD\u800C\u66F4\u886C\u5F97\u7D27\u5F20\uFF1B\u6292\u60C5\u4E2D\u7A81\u7136\u7838\u4E0B\u4E00\u4E2A\u77ED\u53E5\uFF0C\u53CD\u800C\u66F4\u6233\u4EBA\u3002\n\n2. \u957F\u53E5\u94FA\u9648\uFF0C\u77ED\u53E5\u7838\u70B9\uFF1A\u75281-3\u53E5\u957F\u53E5\uFF0840-60\u5B57\uFF09\u628A\u6C1B\u56F4\u94FA\u8DB3\u3001\u628A\u7EC6\u8282\u5199\u591F\uFF0C\u7136\u540E\u75281\u53E5\u6781\u77ED\u53E5\uFF081-5\u5B57\uFF09\u7838\u4E0B\u6838\u5FC3\u4FE1\u606F\u3002\u6BD4\u5982\u957F\u53E5\u5199\u98CE\u600E\u4E48\u5439\u3001\u6811\u600E\u4E48\u6447\u3001\u5929\u600E\u4E48\u9ED1\uFF0C\u7136\u540E\u77ED\u53E5\u2014\u2014'\u96E8\u6765\u4E86\u3002'\u3002\u5BF9\u6BD4\u611F\u77AC\u95F4\u51FA\u6765\u3002\n\n3. \u6BB5\u843D\u5185\u90E8\u547C\u5438\uFF1A\u4E00\u4E2A\u6BB5\u843D\u91CC\u8981\u6709\u957F\u6709\u77ED\uFF0C\u4E0D\u80FD\u5168\u662F\u957F\u53E5\uFF08\u8BFB\u7740\u7D2F\uFF09\uFF0C\u4E5F\u4E0D\u80FD\u5168\u662F\u77ED\u53E5\uFF08\u8BFB\u7740\u614C\uFF09\u3002\u7406\u60F3\u7ED3\u6784\uFF1A\u5F00\u5934\u957F\u53E5\u5165\u573A\u666F\u2192\u4E2D\u95F4\u4E2D\u53E5\u63A8\u8FDB\u2192\u7ED3\u5C3E\u77ED\u53E5\u6536\u675F/\u7559\u60AC\u5FF5\u3002\n\n4. \u5355\u5B57/\u4E24\u5B57\u53E5\u7684\u7528\u6CD5\uFF1A\u6781\u77ED\u53E5\uFF081-3\u5B57\uFF09\u4E0D\u80FD\u968F\u4FBF\u7528\uFF0C\u8981\u7528\u5728\u5200\u5203\u4E0A\u2014\u2014\u60C5\u7EEA\u8F6C\u6298\u70B9\u3001\u5173\u952E\u4FE1\u606F\u63ED\u793A\u3001\u52A8\u4F5C\u5B9A\u683C\u3002\u4E00\u7AE0\u91CC\u75285-8\u6B21\u5C31\u591F\u4E86\uFF0C\u7528\u591A\u4E86\u5C31\u6CA1\u6548\u679C\u4E86\u3002\u7528\u4E4B\u524D\u5148\u7528\u957F\u53E5\u628A\u5F20\u529B\u62C9\u6EE1\u3002\n\n5. \u957F\u53E5\u8981'\u901A'\uFF1A\u957F\u53E5\u4E0D\u662F\u51D1\u5B57\u6570\uFF0C\u8981\u6709\u5185\u5728\u97F5\u5F8B\u3002\u901A\u8FC7\u9017\u53F7\u3001\u987F\u53F7\u5236\u9020\u505C\u987F\uFF0C\u50CF\u547C\u5438\u4E00\u6837\u3002\u957F\u53E5\u91CC\u8981\u6709\u753B\u9762\u6D41\u52A8\u2014\u2014\u4ECE\u8FDC\u5230\u8FD1\uFF0C\u4ECE\u5916\u5230\u5185\uFF0C\u4ECE\u89C6\u89C9\u5230\u542C\u89C9\u5230\u89E6\u89C9\uFF0C\u8BFB\u8005\u8DDF\u7740\u53E5\u5B50\u8D70\uFF0C\u4E0D\u89C9\u5F97\u7D2F\u3002\n\n6. \u8282\u594F\u52A0\u901F\u51CF\u901F\uFF1A\u8981\u7D27\u5F20\u7684\u65F6\u5019\uFF0C\u53E5\u5B50\u8D8A\u6765\u8D8A\u77ED\uFF0C\u6BB5\u843D\u8D8A\u6765\u8D8A\u788E\uFF1B\u8981\u8212\u7F13\u7684\u65F6\u5019\uFF0C\u53E5\u5B50\u6162\u6162\u62C9\u957F\uFF0C\u6BB5\u843D\u6162\u6162\u53D8\u5BBD\u3002\u50CF\u97F3\u4E50\u7684\u6E10\u5F3A\u6E10\u5F31\uFF0C\u81EA\u7136\u8FC7\u6E21\uFF0C\u4E0D\u8981\u7A81\u7136\u5207\u6362\u3002\n\n7. \u5BF9\u8BDD\u8282\u594F\uFF1A\u5BF9\u8BDD\u672C\u8EAB\u662F\u77ED\u7684\uFF0C\u5BF9\u8BDD\u524D\u540E\u7684\u63CF\u5199\u53EF\u4EE5\u957F\u4E00\u70B9\uFF0C\u5F62\u6210'\u957F-\u77ED-\u957F'\u7684\u6CE2\u7EB9\u7ED3\u6784\u3002\u6BD4\u5982\uFF1A\u957F\u53E5\u5199\u4EBA\u7269\u600E\u4E48\u8D70\u8FDB\u6765\u3001\u4EC0\u4E48\u8868\u60C5\u2192\u77ED\u5BF9\u8BDD\u2192\u957F\u53E5\u5199\u4EBA\u7269\u8BF4\u5B8C\u540E\u7684\u52A8\u4F5C/\u73AF\u5883\u53D8\u5316\u3002",
  constraints: [
    "\u6BB5\u843D\u5185\u90E8\u5FC5\u987B\u6709\u957F\u77ED\u53E5\u53D8\u5316\uFF0C\u7981\u6B62\u8FDE\u7EED5\u53E5\u4EE5\u4E0A\u76F8\u540C\u957F\u5EA6\u533A\u95F4\u7684\u53E5\u5B50",
    "\u52A8\u4F5C\u573A\u666F\u77ED\u53E5\u6BD4\u4F8B\u63D0\u9AD8\u523060%\u4EE5\u4E0A\uFF0C\u6292\u60C5/\u56DE\u5FC6\u573A\u666F\u957F\u53E5\u6BD4\u4F8B\u63D0\u9AD8\u523050%\u4EE5\u4E0A",
    "\u6BCF1000\u5B57\u81F3\u5C11\u67093-5\u5904\u6781\u77ED\u53E5\uFF081-5\u5B57\uFF09\u4F5C\u4E3A\u8282\u594F\u91CD\u97F3\uFF0C\u4E14\u5FC5\u987B\u5728\u957F\u53E5\u94FA\u57AB\u4E4B\u540E",
    "\u957F\u53E5\uFF0840\u5B57\u4EE5\u4E0A\uFF09\u5185\u90E8\u5FC5\u987B\u6709\u81F3\u5C112\u4E2A\u9017\u53F7\u505C\u987F\uFF0C\u7981\u6B62\u4E00\u9017\u5230\u5E95",
    "\u5355\u53E5\u4E0D\u8D85\u8FC760\u5B57\uFF0C\u8D85\u8FC7\u5FC5\u987B\u62C6\u6210\u4E24\u53E5",
    "\u8282\u594F\u8F6C\u6362\u8981\u81EA\u7136\u2014\u2014\u7D27\u5F20\u6BB5\u5230\u8212\u7F13\u6BB5\u4E4B\u95F4\u81F3\u5C11\u67092\u53E5\u4E2D\u53E5\u8FC7\u6E21\uFF0C\u4E0D\u8981\u8DF3\u5D16\u5F0F\u5207\u6362",
    "\u6BB5\u843D\u957F\u5EA6\u6839\u636E\u8282\u594F\u8C03\u6574\uFF1A\u7D27\u5F20\u6BB53-5\u53E5\uFF0C\u8212\u7F13\u6BB55-8\u53E5\uFF0C\u5173\u952E\u77AC\u95F4\u53EF\u4EE51\u53E5\u4E00\u6BB5",
    "\u5BF9\u8BDD\u524D\u540E\u5FC5\u987B\u6709\u52A8\u4F5C/\u795E\u6001\u63CF\u5199\uFF0C\u5F62\u6210'\u63CF\u5199-\u5BF9\u8BDD-\u63CF\u5199'\u7684\u8282\u594F\u5355\u5143"
  ],
  examples: [
    {
      text: "\u8001\u9648\u8E72\u5728\u5DF7\u9053\u58C1\u8FB9\uFF0C\u628A\u77FF\u706F\u62E7\u5230\u6700\u6697\uFF0C\u53EA\u7559\u4E00\u70B9\u9EC4\u8C46\u5927\u7684\u5149\u6620\u5728\u811A\u4E0B\u7684\u788E\u7164\u4E0A\u3002\u901A\u98CE\u7BA1\u65E9\u5C31\u505C\u4E86\uFF0C\u7A7A\u6C14\u91CC\u5F25\u6F2B\u7740\u4E00\u80A1\u6DE1\u6DE1\u7684\u3001\u751C\u4E1D\u4E1D\u7684\u5473\u9053\uFF0C\u50CF\u70C2\u82F9\u679C\uFF0C\u4ED6\u77E5\u9053\u90A3\u662F\u74E6\u65AF\u3002\n\n\u6E29\u5EA6\u8BA1\u63D2\u5728\u58C1\u7F1D\u91CC\uFF0C\u7EA2\u8272\u6DB2\u67F1\u722C\u5F97\u5F88\u6162\uFF0C\u6BCF\u52A8\u4E00\u683C\u90FD\u50CF\u5728\u62FD\u4ED6\u7684\u795E\u7ECF\u3002\n\n35.9\u3002\n\n36.1\u3002\n\n36.4\u3002\n\n\u4ED6\u6570\u7740\u81EA\u5DF1\u7684\u547C\u5438\u3002\u5438\u6C14\u56DB\u79D2\uFF0C\u618B\u6C14\u4E24\u79D2\uFF0C\u547C\u6C14\u516D\u79D2\uFF0C\u8FD9\u662F\u8001\u77FF\u5DE5\u6559\u4ED6\u7684\u529E\u6CD5\uFF0C\u80FD\u5728\u6C27\u6C14\u4E0D\u8DB3\u7684\u65F6\u5019\u591A\u6491\u4E00\u4F1A\u513F\u3002\u5DF7\u58C1\u6DF1\u5904\u4F20\u6765\u5F88\u8F7B\u7684\u9707\u98A4\uFF0C\u4E0D\u662F\u77FF\u9707\uFF0C\u77FF\u9707\u4E0D\u662F\u8FD9\u4E2A\u9891\u7387\uFF0C\u8FD9\u4E2A\u66F4\u6C89\uFF0C\u66F4\u6162\uFF0C\u50CF\u4EC0\u4E48\u5DE8\u5927\u7684\u4E1C\u897F\u5728\u5F88\u6DF1\u5F88\u6DF1\u7684\u5730\u65B9\u7FFB\u4E86\u4E2A\u8EAB\u3002\n\n\u8001\u674E\u5728\u4ED6\u65C1\u8FB9\u5750\u7740\uFF0C\u80CC\u9760\u7740\u58C1\uFF0C\u5934\u5782\u7740\uFF0C\u5DF2\u7ECF\u5F88\u4E45\u6CA1\u52A8\u4E86\u3002\u53F3\u80F3\u818A\u80BF\u5F97\u50CF\u5927\u817F\u90A3\u4E48\u7C97\uFF0C\u76AE\u80A4\u4E0B\u9762\u900F\u7740\u4E00\u79CD\u53D1\u4EAE\u7684\u9752\u7D2B\u8272\uFF0C\u90A3\u662F\u574F\u75BD\u7684\u989C\u8272\u3002\u4ED6\u8FD8\u6709\u6C14\uFF0C\u80F8\u53E3\u6BCF\u9694\u5F88\u4E45\u624D\u8D77\u4F0F\u4E00\u4E0B\uFF0C\u5F31\u5F97\u50CF\u98CE\u4E2D\u7684\u70DB\u706B\u3002\n\n\u8001\u9648\u6478\u4E86\u6478\u53E3\u888B\u3002\u534A\u5757\u538B\u7F29\u997C\u5E72\uFF0C\u4E00\u4E2A\u6253\u706B\u673A\uFF0C\u77FF\u706F\u7535\u91CF31%\u3002\n\n\u6C34\u8FD8\u5269\u4E24\u53E3\u3002\n\n\u4ED6\u628A\u94DC\u7897\u7AEF\u8D77\u6765\uFF0C\u51D1\u5230\u8001\u674E\u5634\u8FB9\uFF0C\u503E\u659C\u4E86\u4E00\u70B9\u3002\u6C34\u987A\u7740\u8001\u674E\u7684\u5634\u89D2\u6D41\u4E0B\u6765\uFF0C\u6CA1\u54BD\u4E0B\u53BB\u3002\n\n\u8001\u9648\u628A\u7897\u6536\u56DE\u6765\uFF0C\u81EA\u5DF1\u559D\u4E86\u5269\u4E0B\u7684\u4E00\u53E3\u3002\u6C34\u662F\u6E29\u7684\uFF0C\u6709\u80A1\u94C1\u9508\u5473\u3002\n\n\u9ED1\u6697\u91CC\uFF0C\u90A3\u4E2A\u9707\u98A4\u53C8\u6765\u4E86\u3002\n\n\u8FD9\u6B21\u66F4\u8FD1\u4E86\u3002",
      note: "\u957F\u77ED\u4EA4\u9519\u793A\u8303\uFF1A\u5F00\u5934\u7528\u957F\u53E5\u94FA\u9648\u73AF\u5883\uFF08\u74E6\u65AF\u5473\u9053/\u6E29\u5EA6\u8BA1/\u547C\u5438\u65B9\u6CD5/\u58C1\u9707\uFF09\uFF0C\u7136\u540E\u75283\u4E2A\u6781\u77ED\u53E5\uFF08'35.9\u3002''36.1\u3002''36.4\u3002'\uFF09\u5236\u9020\u7D27\u5F20\u611F\uFF0C\u63A5\u7740\u53C8\u56DE\u5230\u957F\u53E5\u63CF\u5199\u8001\u674E\u7684\u72B6\u6001\uFF0C\u518D\u7528\u77ED\u53E5\uFF08'\u534A\u5757\u538B\u7F29\u997C\u5E72...''\u6C34\u8FD8\u5269\u4E24\u53E3\u3002'\uFF09\u4EA4\u4EE3\u7269\u8D44\uFF0C\u6700\u540E\u7ED3\u5C3E'\u8FD9\u6B21\u66F4\u8FD1\u4E86\u3002'\u4E00\u4E2A\u77ED\u53E5\u6536\u675F\uFF0C\u4F59\u5473\u5341\u8DB3\u3002\u957F\u77ED\u4EA4\u66FF\u50CF\u6D77\u6D6A\u4E00\u6837\uFF0C\u8BFB\u8005\u7684\u60C5\u7EEA\u8DDF\u7740\u8D77\u4F0F\u3002"
    }
  ],
  requires: [],
  conflicts: []
};

