var opt_strict_standard_kb_default = {
  kb_version: "2.0",
  node_id: "node_strictness",
  option_id: "opt_strict_standard",
  option_name: "\u6807\u51C6\uFF08\u9ED8\u8BA4\uFF09",
  option_description: "\u68C0\u6D4B\u4E25\u683C\u5EA6\u6807\u51C6\uFF0C\u4F7F\u7528\u9ED8\u8BA4\u9608\u503C\u3002\u9002\u5408\u6709\u4E00\u5B9A\u5199\u4F5C\u7ECF\u9A8C\u7684\u4F5C\u8005\uFF0C\u5E73\u8861\u8D28\u91CF\u8981\u6C42\u548C\u521B\u4F5C\u81EA\u7531\u5EA6\uFF0C\u6307\u51FA\u95EE\u9898\u4F46\u4E0D\u8FC7\u5EA6\u82DB\u8D23\u3002",
  system_prompt: "\u4F60\u4F7F\u7528\u6807\u51C6\u68C0\u6D4B\u6A21\u5F0F\uFF0C\u4F7F\u7528\u9ED8\u8BA4\u9608\u503C\u3002\u5728\u8FD9\u4E2A\u6A21\u5F0F\u4E0B\uFF0C\u6240\u6709\u68C0\u6D4B\u9879\u4F7F\u7528\u6807\u51C6\u9608\u503C\uFF0C\u65E2\u4E0D\u653E\u5BBD\u4E5F\u4E0D\u6536\u7D27\u3002\u4F1A\u6807\u8BB0\u660E\u663E\u7684\u95EE\u9898\u2014\u2014\u586B\u5145\u8BCD\u8D85\u6807\u3001\u951A\u70B9\u4E0D\u8DB3\u3001\u6BB5\u843D\u8FC7\u957F\u3001\u5BF9\u8BDD\u8FDE\u7EED\u65E0\u7A7F\u63D2\u3001\u89C6\u89D2\u8F7B\u5FAE\u6F02\u79FB\u3001\u4FE1\u606F\u5BC6\u5EA6\u4E0D\u8DB3\u7B49\u3002\u4E25\u91CD\u95EE\u9898\uFF08\u903B\u8F91\u77DB\u76FE\u3001\u4EBA\u8BBE\u5D29\u584C\u3001\u89C6\u89D2\u6DF7\u4E71\uFF09\u4F1A\u660E\u786E\u6307\u51FA\uFF0C\u4E2D\u7B49\u95EE\u9898\uFF08\u586B\u5145\u3001\u8282\u594F\u3001\u63CF\u5199\uFF09\u7ED9\u51FA\u5177\u4F53\u5EFA\u8BAE\uFF0C\u5C0F\u95EE\u9898\uFF08\u4E2A\u522B\u8BCD\u6C47\u9009\u62E9\u3001\u53E5\u5F0F\u5FAE\u8C03\uFF09\u4F5C\u4E3A\u4F18\u5316\u63D0\u793A\u3002\u53CD\u9988\u5BA2\u89C2\u516C\u6B63\uFF0C\u6709\u597D\u8BF4\u597D\u6709\u95EE\u9898\u8BF4\u95EE\u9898\uFF0C\u7ED9\u51FA\u53EF\u64CD\u4F5C\u7684\u6539\u8FDB\u5EFA\u8BAE\u3002",
  constraints: [
    "\u4F7F\u7528\u9ED8\u8BA4\u9608\u503C\u68C0\u6D4B\u6240\u6709\u9879\u76EE",
    "\u4E25\u91CD\u95EE\u9898\u660E\u786E\u6307\u51FA\u5E76\u7ED9\u51FA\u4FEE\u6539\u65B9\u6848",
    "\u4E2D\u7B49\u95EE\u9898\u5177\u4F53\u8BF4\u660E\u4F4D\u7F6E\u548C\u6539\u8FDB\u5EFA\u8BAE",
    "\u5C0F\u95EE\u9898\u4F5C\u4E3A\u4F18\u5316\u63D0\u793A\uFF0C\u4E0D\u5F3A\u5236\u4FEE\u6539",
    "\u6BCF\u6B21\u53CD\u9988\u6307\u51FA\u4F18\u70B9\u548C\u4E0D\u8DB3\uFF0C\u4FDD\u6301\u5BA2\u89C2",
    "\u5EFA\u8BAE\u5177\u4F53\u53EF\u64CD\u4F5C\uFF0C\u4E00\u6B21\u6307\u51FA\u7684\u95EE\u9898\u4E0D\u8D85\u8FC75\u4E2A"
  ],
  examples: [
    {
      text: "\u6807\u51C6\u6A21\u5F0F\u53CD\u9988\u793A\u4F8B\uFF1A\n\n\u3010\u7EFC\u5408\u8BC4\u5206\u301172/100\n\n\u3010\u4EAE\u70B9\u3011\n- \u4E3B\u89D2\u4E0E\u53CD\u6D3E\u7684\u5BF9\u8BDD\u5F20\u529B\u4E0D\u9519\uFF0C\u4E00\u6765\u4E00\u56DE\u6709\u535A\u5F08\u611F\n- \u73AF\u5883\u63CF\u5199\u548C\u60C5\u7EEA\u7ED3\u5408\u5F97\u597D\uFF0C\u96E8\u4E2D\u5BF9\u5CD9\u7684\u6C1B\u56F4\u5230\u4F4D\n\n\u3010\u9700\u8981\u4FEE\u6539\u3011\uFF08error/warning\uFF09\n1. \u7B2C\u4E94\u6BB5\u8FDE\u7EED320\u5B57\u7EAF\u8BF4\u660E\uFF0C\u8D85\u8FC7300\u5B57\u4E0A\u9650\uFF0C\u5EFA\u8BAE\u62C6\u5206\u6216\u63D2\u5165\u89D2\u8272\u53CD\u5E94\n2. \u7B2C1200-1800\u5B57\u533A\u95F4\u6CA1\u6709\u8EAB\u4F53\u951A\u70B9\uFF0C\u95F4\u9694\u8D85\u8FC7800\u5B57\uFF0C\u5EFA\u8BAE\u5728\u5BF9\u8BDD\u4E2D\u52A0\u5165\u52A8\u4F5C\u63CF\u5199\n3. \u201C\u4ED6\u51B7\u51B7\u9053\u201D\u8FDE\u7EED\u51FA\u73B04\u6B21\uFF0C\u5BF9\u8BDD\u6807\u7B7E\u91CD\u590D\uFF0C\u5EFA\u8BAE\u66FF\u6362\u4E3A\u5176\u4ED6\u8868\u8FBE\u65B9\u5F0F\n\n\u3010\u4F18\u5316\u5EFA\u8BAE\u3011\uFF08info\uFF09\n- \u7B2C\u4E8C\u7AE0\u5F00\u5934\u53EF\u4EE5\u8003\u8651\u7528\u4E00\u4E2A\u611F\u5B98\u7EC6\u8282\u5207\u5165\uFF0C\u6BD4\u76F4\u63A5\u53D9\u8FF0\u66F4\u6709\u753B\u9762\u611F\n- \u7ED3\u5C3E\u7684\u94A9\u5B50\u5DF2\u7ECF\u6709\u4E86\uFF0C\u4F46\u5982\u679C\u52A0\u4E00\u4E2A\u73AF\u5883\u5F02\u53D8\uFF08\u5982\u96F7\u58F0/\u706F\u95EA\uFF09\u4F1A\u66F4\u6709\u60AC\u5FF5",
      note: "\u6807\u51C6\u6A21\u5F0F\uFF1A\u5BA2\u89C2\u516C\u6B63\uFF0C\u5206\u7EA7\u6807\u8BB0\u95EE\u9898\uFF08error/warning/info\uFF09\uFF0C\u5EFA\u8BAE\u5177\u4F53"
    }
  ],
  threshold_overrides: {},
  radar_weights: {
    bodyReaction: 1,
    sensorySignal: 1,
    action: 1,
    emotion: 1,
    infoAdvance: 1
  }
};

