      text: "1500\u5B57\u77ED\u7AE0\u7ED3\u6784\u793A\u4F8B\uFF1A\n- \u5F00\u5934\uFF08100\u5B57\uFF09\uFF1A\u76F4\u63A5\u8FDB\u5165\u51B2\u7A81\u573A\u666F\n- \u53D1\u5C55\uFF081100\u5B57\uFF09\uFF1A\u5BF9\u8BDD\u63A8\u8FDB+\u52A8\u4F5C\u63CF\u5199+\u5C0F\u8F6C\u6298\n- \u94A9\u5B50\u7ED3\u5C3E\uFF08300\u5B57\uFF09\uFF1A\u60AC\u5FF5/\u53CD\u8F6C/\u65B0\u4FE1\u606F\u51FA\u73B0\uFF0C\u621B\u7136\u800C\u6B62",
