var opt_tone_folksy_kb_default = {
  kb_version: "2.0",
  node_id: "node_tone",
  option_id: "opt_tone_folksy",
  option_name: "\u4E61\u571F\u5E02\u4E95",
  option_description: "\u70DF\u706B\u6C14\u5341\u8DB3\uFF0C\u6709\u751F\u6D3B\u8D28\u611F\uFF0C\u67F4\u7C73\u6CB9\u76D0\u3001\u8857\u574A\u90BB\u91CC\u3001\u5E02\u4E95\u767E\u6001\u3002\u9002\u5408\u5E74\u4EE3\u6587\u3001\u4E61\u571F\u6587\u3001\u5E02\u4E95\u751F\u6D3B\u9898\u6750\u3002",
  threshold_overrides: {
    maxSentenceLength: 45,
    targetSentenceLength: 20,
    shortSentenceRatio: 0.45,
    maxParagraphLength: 150,
    maxDialogueContinuous: 4
  },
  radar_weights: {
    emotion: 1.1,
    sensorySignal: 1.3,
    action: 0.9
  },
  system_prompt: "\u4E61\u571F\u5E02\u4E95\u57FA\u8C03\u7684\u6838\u5FC3\u662F'\u70DF\u706B\u6C14'\u3002\u5199\u7684\u662F\u67F4\u7C73\u6CB9\u76D0\u3001\u5BB6\u957F\u91CC\u77ED\u3001\u8857\u574A\u90BB\u91CC\u3001\u4E09\u6559\u4E5D\u6D41\uFF0C\u6587\u5B57\u8981\u6709\u751F\u6D3B\u8D28\u611F\uFF0C\u80FD\u95FB\u5230\u6CB9\u70DF\u5473\u3001\u542C\u5230\u53EB\u5356\u58F0\u3001\u6478\u5230\u7C97\u5E03\u7684\u7EB9\u7406\u3002\u5177\u4F53\u8BED\u8A00\u89C4\u5219\uFF1A\n\n1. \u751F\u6D3B\u7EC6\u8282\uFF1A\u5199\u5177\u4F53\u7684\u98DF\u7269\uFF08\u8471\u6CB9\u997C\u3001\u8C46\u8150\u8111\u3001\u7EA2\u70E7\u8089\u3001\u7A9D\u7A9D\u5934\uFF09\u3001\u5177\u4F53\u7684\u4EF7\u683C\uFF08\u4E24\u6BDB\u4E94\u3001\u4E09\u5757\u4E8C\uFF09\u3001\u5177\u4F53\u7684\u7269\u4EF6\uFF08\u642A\u74F7\u7F38\u3001\u6696\u6C34\u74F6\u3001\u4E8C\u516B\u81EA\u884C\u8F66\u3001\u7F1D\u7EAB\u673A\uFF09\u3001\u5177\u4F53\u7684\u573A\u6240\uFF08\u83DC\u5E02\u573A\u3001\u5927\u6742\u9662\u3001\u80E1\u540C\u53E3\u3001\u4F9B\u9500\u793E\uFF09\u3002\u7EC6\u8282\u8D8A\u5177\u4F53\u8D8A\u771F\u5B9E\u3002\n\n2. \u65B9\u8A00\u9002\u5EA6\uFF1A\u53EF\u4EE5\u7528\u65B9\u8A00\u8BCD\u6C47\u548C\u53E3\u8BED\u8868\u8FBE\uFF0C\u4F46\u4E0D\u80FD\u591A\u5230\u770B\u4E0D\u61C2\u3002\u5317\u65B9\u53E3\u8BED\uFF08\u548B\u3001\u5565\u3001\u4E2D\u3001\u752D\u3001\u6401\u3001\u5F97\u52B2\uFF09\u3001\u5357\u65B9\u53E3\u8BED\uFF08\u4F22\u5B50\u3001\u6653\u5F97\u3001\u83AB\u3001\u567B\uFF09\u6839\u636E\u6545\u4E8B\u5730\u70B9\u9009\u7528\uFF0C\u4FDD\u6301\u8BED\u8A00\u7684\u5730\u57DF\u611F\u3002\n\n3. \u611F\u5B98\u4E30\u5BCC\uFF1A\u55C5\u89C9\uFF08\u6CB9\u70DF\u5473\u3001\u7164\u6C14\u5473\u3001\u69D0\u82B1\u9999\u3001\u81ED\u8C46\u8150\u5473\uFF09\u3001\u5473\u89C9\uFF08\u54B8\u4E86\u3001\u6DE1\u4E86\u3001\u8FA3\u3001\u9178\u3001\u751C\uFF09\u3001\u89E6\u89C9\uFF08\u7C97\u5E03\u78E8\u624B\u3001\u677F\u51F3\u784C\u5C41\u80A1\u3001\u592A\u9633\u6652\u5F97\u6696\u70D8\u70D8\uFF09\u3001\u542C\u89C9\uFF08\u53EB\u5356\u58F0\u3001\u81EA\u884C\u8F66\u94C3\u3001\u6536\u97F3\u673A\u3001\u7092\u83DC\u58F0\uFF09\u2014\u2014\u4E94\u611F\u5168\u5F00\uFF0C\u8FD9\u662F\u70DF\u706B\u6C14\u7684\u6765\u6E90\u3002\n\n4. \u4EBA\u7269\u9C9C\u6D3B\uFF1A\u5C0F\u4EBA\u7269\u7684\u559C\u6012\u54C0\u4E50\uFF0C\u63A5\u5730\u6C14\u7684\u751F\u5B58\u667A\u6167\u3002\u8BF4\u8BDD\u505A\u4E8B\u7B26\u5408\u8EAB\u4EFD\u2014\u2014\u5C0F\u8D29\u4F1A\u5406\u559D\u3001\u5927\u5988\u4F1A\u780D\u4EF7\u3001\u5DE5\u4EBA\u4F1A\u9A82\u5A18\u3001\u5B69\u5B50\u4F1A\u6492\u6CFC\u3002\u4E0D\u5199\u5B8C\u7F8E\u4EBA\u7269\uFF0C\u6709\u7F3A\u70B9\u6709\u6BDB\u75C5\u6709\u5C0F\u7B97\u76D8\u624D\u771F\u5B9E\u3002\n\n5. \u8282\u594F\u8212\u7F13\uFF1A\u751F\u6D3B\u6D41\u53D9\u4E8B\uFF0C\u4E0D\u8FFD\u6C42\u5FEB\u8282\u594F\u3002\u5F20\u5BB6\u957F\u674E\u5BB6\u77ED\u3001\u4E70\u83DC\u505A\u996D\u4E0A\u73ED\u4E0B\u73ED\uFF0C\u65E5\u5E38\u91CC\u85CF\u7740\u4EBA\u60C5\u51B7\u6696\u3002",
  constraints: [
    "\u6BCF500\u5B57\u81F3\u5C11\u67091\u5904\u5177\u4F53\u7684\u751F\u6D3B\u7EC6\u8282\uFF08\u98DF\u7269/\u4EF7\u683C/\u7269\u4EF6/\u573A\u6240\uFF09\uFF0C\u4E0D\u80FD\u98D8\u5728\u7A7A\u4E2D",
    "\u65B9\u8A00\u8BCD\u6C47\u63A7\u5236\u572810%-15%\uFF0C\u4E0D\u80FD\u5F71\u54CD\u9605\u8BFB\u7406\u89E3\uFF0C\u5FC5\u8981\u65F6\u901A\u8FC7\u4E0A\u4E0B\u6587\u7406\u89E3",
    "\u4E94\u611F\u63CF\u5199\u4E2D\u55C5\u89C9\u548C\u5473\u89C9\u81F3\u5C11\u5404\u51FA\u73B01\u6B21/\u5343\u5B57\uFF0C\u70DF\u706B\u6C14\u6765\u81EA\u6C14\u5473\u548C\u5473\u9053",
    "\u5BF9\u8BDD\u8981\u7B26\u5408\u4EBA\u7269\u8EAB\u4EFD\u548C\u5730\u57DF\uFF0C\u5C0F\u8D29\u8BF4\u8BDD\u50CF\u5C0F\u8D29\uFF0C\u5927\u5988\u8BF4\u8BDD\u50CF\u5927\u5988",
    "\u7981\u6B62\u7A7A\u6D1E\u6292\u60C5\u548C\u534E\u4E3D\u8F9E\u85FB\uFF0C\u7528\u5177\u4F53\u7684\u751F\u6D3B\u573A\u666F\u4EE3\u66FF\u62BD\u8C61\u7684\u60C5\u611F\u63CF\u5199",
    "\u4EBA\u7269\u8981\u6709\u5C0F\u7F3A\u70B9\u548C\u5C0F\u7B97\u76D8\uFF0C\u4E0D\u80FD\u9AD8\u5927\u5168\uFF0C\u63A5\u5730\u6C14\u7684\u4EBA\u7269\u624D\u9C9C\u6D3B",
    "\u6BB5\u843D\u76EE\u6807\u957F\u5EA680-120\u5B57\uFF0C\u53D9\u4E8B\u8282\u594F\u4ECE\u5BB9\u4E0D\u6025\u8E81",
    "\u7981\u6B62\u7F51\u7EDC\u7528\u8BED\u548C\u73B0\u4EE3\u6897\uFF0C\u4FDD\u6301\u65F6\u4EE3\u611F\u548C\u751F\u6D3B\u771F\u5B9E\u611F"
  ],
  examples: [
    {
      text: "\u5929\u8FD8\u6CA1\u4EAE\u900F\uFF0C\u738B\u5A76\u5C31\u8D77\u5E8A\u4E86\u3002\n\n\u7164\u7403\u7089\u5B50\u5C01\u4E86\u4E00\u591C\uFF0C\u6345\u5F00\u7684\u65F6\u5019\u5192\u4E86\u4E00\u9635\u9ED1\u70DF\uFF0C\u545B\u5F97\u5979\u76F4\u54B3\u55FD\u3002\u5979\u6247\u4E86\u4E24\u4E0B\u84B2\u6247\uFF0C\u706B\u82D7\u5B50\u817E\u5730\u8D77\u6765\u4E86\uFF0C\u84DD\u76C8\u76C8\u7684\uFF0C\u6620\u5F97\u5979\u8138\u4E0A\u7684\u76B1\u7EB9\u90FD\u5728\u8DF3\u3002\n\n\u548C\u9762\u7684\u76C6\u662F\u642A\u74F7\u7684\uFF0C\u6389\u4E86\u4E09\u5757\u6F06\uFF0C\u9732\u7740\u9ED1\u94C1\u5E95\u3002\u5979\u8200\u4E86\u4E24\u74E2\u767D\u9762\uFF0C\u4E00\u74E2\u7389\u7C73\u9762\uFF0C\u5151\u4E86\u6E29\u6C34\uFF0C\u624B\u5728\u9762\u91CC\u6405\u548C\uFF0C\u6307\u7F1D\u91CC\u5168\u662F\u9762\u560E\u5DF4\u3002\n\n\u5916\u95F4\u5C4B\u4F20\u6765\u5979\u7537\u4EBA\u7684\u54B3\u55FD\u58F0\uFF0C\u8001\u70DF\u67AA\uFF0C\u54B3\u8D77\u6765\u50CF\u8981\u628A\u80BA\u90FD\u5410\u51FA\u6765\u3002\n\n\u300C\u6B7B\u4E0D\u4E86\u5C31\u8D77\u6765\uFF0C\u300D\u738B\u5A76\u671D\u91CC\u95F4\u558A\uFF0C\u300C\u4ECA\u5929\u8C46\u8150\u644A\u5F20\u7638\u5B50\u6765\uFF0C\u665A\u4E86\u5C31\u6CA1\u70ED\u4E4E\u7684\u4E86\u3002\u300D\n\n\u5979\u6380\u5F00\u54B8\u83DC\u575B\u5B50\uFF0C\u4E00\u80A1\u54B8\u9178\u5473\u8E7F\u51FA\u6765\u3002\u635E\u4E86\u4E24\u6839\u841D\u535C\u6761\uFF0C\u6EF4\u4E86\u4E24\u6EF4\u9999\u6CB9\uFF0C\u6401\u5728\u7C97\u74F7\u789F\u5B50\u91CC\u3002\u68D2\u5B50\u9762\u7CA5\u5728\u9505\u91CC\u5495\u561F\u7740\uFF0C\u6CE1\u6CE1\u9876\u5F00\u4E86\u9505\u76D6\uFF0C\u987A\u7740\u9505\u6CBF\u5F80\u4E0B\u6DCC\uFF0C\u5728\u7164\u7403\u7089\u5B50\u4E0A\u6ECB\u5566\u4E00\u58F0\uFF0C\u7CCA\u5473\u5C31\u4E0A\u6765\u4E86\u3002\n\n\u738B\u5A76\u8D76\u7D27\u628A\u9505\u76D6\u6380\u5F00\u4E00\u6761\u7F1D\u3002\n\n\u80E1\u540C\u53E3\u5DF2\u7ECF\u6709\u52A8\u9759\u4E86\u3002\u5356\u725B\u5976\u7684\u94C3\u94DB\u53EE\u94C3\u53EE\u94C3\u54CD\uFF0C\u626B\u8857\u7684\u8001\u9648\u5934\u62FF\u7740\u5927\u626B\u5E1A\u54D7\u5566\u54D7\u5566\uFF0C\u5BF9\u95E8\u674E\u5BB6\u7684\u6536\u97F3\u673A\u5728\u653E\u300A\u671D\u9633\u6C9F\u300B\uFF0C\u54C7\u5566\u54C7\u5566\u7684\u3002\n\n\u65B0\u7684\u4E00\u5929\u5F00\u59CB\u4E86\u3002",
      note: "\u4E61\u571F\u5E02\u4E95\u793A\u8303\uFF1A\u5177\u4F53\u751F\u6D3B\u7EC6\u8282\uFF08\u7164\u7403\u7089\u5B50/\u642A\u74F7\u76C6\u6389\u6F06/\u4E24\u74E2\u767D\u9762\u4E00\u74E2\u7389\u7C73\u9762/\u841D\u535C\u6761\u6EF4\u9999\u6CB9/\u68D2\u5B50\u9762\u7CA5\u5495\u561F/\u300A\u671D\u9633\u6C9F\u300B\uFF09\uFF0C\u65B9\u8A00\u9002\u5EA6\uFF08\u548B/\u5565/\u6401/\u752D\u6CA1\u6709\u786C\u585E\uFF09\uFF0C\u4E94\u611F\u5168\u5F00\uFF08\u545B\u5F97\u54B3\u55FD/\u84DD\u76C8\u76C8\u706B\u82D7/\u54B8\u9178\u5473/\u6ECB\u5566\u7CCA\u5473/\u94C3\u94DB\u53EE\u94C3/\u54D7\u5566\u626B\u5E1A\u58F0\uFF09\uFF0C\u8282\u594F\u8212\u7F13\uFF0C\u5C31\u662F\u666E\u901A\u4EBA\u5BB6\u7684\u4E00\u4E2A\u65E9\u6668\uFF0C\u4F46\u70DF\u706B\u6C14\u5341\u8DB3\u3002"
    }
  ],
  requires: [],
  conflicts: [
    "opt_tone_cold"
  ]
};

