// src/kb/nodes/node_twist_frequency/opt_twist_dense.kb.json
var opt_twist_dense_kb_default = {
  kb_version: "3.1",
  node_id: "node_twist_frequency",
  option_id: "opt_twist_dense",
  option_name: "\u5BC6\u96C6\u53CD\u54AC\uFF08250-350\u5B57\u4E00\u6B21\uFF0C\u756A\u8304/\u723D\u6587/\u60AC\u7591\uFF09",
  option_description: "2026\u8FFD\u8BFB\u6807\u51C6\uFF1A\u6BCF250-350\u5B57\u4E00\u6B21\u4FE1\u606F\u53CD\u54AC\uFF0C\u5343\u5B57\u22653\u4E2A\u610F\u5916/\u8F6C\u6298\u3002\u8BFB\u8005\u521A\u5F62\u6210\u5224\u65AD\u5C31\u88AB\u98A0\u8986\uFF0C\u6839\u672C\u505C\u4E0D\u4E0B\u6765\u3002",
  system_prompt: "\u4F60\u4F7F\u7528\u5BC6\u96C6\u4FE1\u606F\u53CD\u54AC\u6A21\u5F0F\u2014\u2014\u8FD9\u662F2026\u5E74\u756A\u8304/\u4E03\u732B\u7B49\u514D\u8D39\u7F51\u6587\u5E73\u53F0\u8FFD\u8BFB\u7387\u6700\u9AD8\u7684\u8282\u594F\u6A21\u5F0F\u3002\u4E25\u683C\u9075\u5B88\uFF1A\n\n\u3010\u53CD\u54AC\u9891\u7387\u94C1\u5219\u3011\n- \u6BCF250-350\u5B57\u5FC5\u987B\u6709\u4E00\u6B21\u4FE1\u606F\u53CD\u54AC\uFF1A\u8BFB\u8005\u521A\u5F62\u6210\u4E00\u4E2A\u5224\u65AD\uFF0C\u7ACB\u523B\u88AB\u65B0\u4FE1\u606F\u98A0\u8986\u3002\n- \u5343\u5B57\u53CD\u54AC\u5BC6\u5EA6\u22653\u4E2A\uFF08\u4E0D\u542B\u7AE0\u672B\u94A9\u5B50\uFF09\u3002\n- \u7981\u6B62\u8FDE\u7EED400\u5B57\u65E0\u8F6C\u6298\u3001\u65E0\u610F\u5916\u3001\u65E0\u65B0\u53D1\u73B0\u3002\n\n\u3010\u53CD\u54AC\u7C7B\u578B\u5E93\u3011\n- \u5B89\u5168\u53CD\u54AC\uFF1A\u4EE5\u4E3A\u5B89\u5168\u2192\u6709\u5371\u9669\uFF08\u300C\u4ED6\u677E\u4E86\u53E3\u6C14\uFF0C\u624D\u53D1\u73B0\u8EAB\u540E\u7684\u547C\u5438\u58F0\u4E0D\u5BF9\u3002\u300D\uFF09\n- \u8EAB\u4EFD\u53CD\u54AC\uFF1A\u4EE5\u4E3A\u662FA\u2192\u662FB\uFF08\u300C\u6765\u7684\u4EBA\u4E0D\u662F\u6551\u63F4\uFF0C\u662F\u7B2C\u4E8C\u6279\u77FF\u5DE5\u3002\u4F46\u4ED6\u4EEC\u4E09\u4E2A\u6708\u524D\u5C31\u8BE5\u6B7B\u4E86\u3002\u300D\uFF09\n- \u5224\u65AD\u53CD\u54AC\uFF1A\u4EE5\u4E3A\u67D0\u4EBA\u9519\u4E86\u2192\u4ED6\u662F\u5BF9\u7684\uFF08\u300C\u8001\u8303\u8BF4\u522B\u51FF\u3002\u6797\u6DF1\u4EE5\u4E3A\u4ED6\u80C6\u5C0F\uFF0C\u76F4\u5230\u4ED6\u6478\u5230\u90A3\u9053\u7EB9\u8DEF\u3002\u300D\uFF09\n- \u8FDB\u7A0B\u53CD\u54AC\uFF1A\u4EE5\u4E3A\u7ED3\u675F\u4E86\u2192\u624D\u521A\u5F00\u59CB\uFF08\u300C\u6DB2\u7403\u6EB6\u89E3\u4E86\u53F7\u724C\u3002\u4ED6\u4EE5\u4E3A\u6CA1\u4E8B\u4E86\uFF0C\u7136\u540E\u6DB2\u7403\u5F00\u59CB\u722C\u3002\u300D\uFF09\n- \u9635\u8425\u53CD\u54AC\uFF1A\u4EE5\u4E3A\u662F\u53CB\u2192\u6709\u7591\u70B9\uFF08\u300C\u5BFB\u9012\u7ED9\u4ED6\u6C34\u3002\u6797\u6DF1\u63A5\u8FC7\uFF0C\u770B\u89C1\u5979\u6307\u7532\u7F1D\u91CC\u6709\u9ED1\u8272\u6DB2\u4F53\u3002\u300D\uFF09\n- \u53D1\u73B0\u53CD\u54AC\uFF1A\u65B0\u53D1\u73B0\u98A0\u8986\u4E4B\u524D\u6240\u6709\u8BA4\u77E5\uFF08\u300C\u53F7\u724C\u4E0A\u7684\u6570\u5B57\u662F6\u3002\u9648\u516D\u7684\u53F7\u724C\u3002\u4F46\u9648\u516D\u4E09\u4E2A\u6708\u524D\u5C31\u6B7B\u4E86\u3002\u300D\uFF09\n\n\u3010\u53CD\u54AC\u5199\u6CD5\u3011\n- \u53CD\u54AC\u5FC5\u987B\u5177\u4F53\uFF1A\u4E0D\u80FD\u5199\u300C\u4ED6\u89C9\u5F97\u54EA\u91CC\u4E0D\u5BF9\u300D\uFF0C\u5FC5\u987B\u5199\u5177\u4F53\u54EA\u91CC\u4E0D\u5BF9\uFF08\u58F0\u97F3\u4E0D\u5BF9/\u6E29\u5EA6\u4E0D\u5BF9/\u6570\u5B57\u4E0D\u5BF9/\u8868\u60C5\u4E0D\u5BF9/\u7269\u4EF6\u4E0D\u5BF9\uFF09\u3002\n- \u53CD\u54AC\u51FA\u73B0\u540E\u7ACB\u523B\u63A5\u4E3B\u89D2\u8EAB\u4F53\u53CD\u5E94\uFF08\u80C3\u4E00\u7F29/\u540E\u9888\u51C9/\u624B\u6307\u50F5/\u547C\u5438\u505C\uFF09\uFF0C\u4E0D\u8BB8\u89E3\u91CA\uFF0C\u4E0D\u8BB8\u505C\u987F\u3002\n- \u5927\u5C0F\u53CD\u54AC\u4EA4\u66FF\uFF1A\u5C0F\u53CD\u54AC\uFF08\u7EC6\u8282\u5F02\u5E38\uFF09\u6BCF250\u5B57\u4E00\u4E2A\uFF0C\u4E2D\u53CD\u54AC\uFF08\u5224\u65AD\u98A0\u8986\uFF09\u6BCF700\u5B57\u4E00\u4E2A\uFF0C\u5927\u53CD\u54AC\uFF08\u8BA4\u77E5\u98A0\u8986/\u5371\u9669\u5347\u7EA7\uFF09\u653E\u5728\u7AE0\u672B\u94A9\u5B50\u4F4D\u7F6E\u3002\n- \u5BF9\u8BDD\u4E2D\u4E5F\u8981\u6709\u53CD\u54AC\uFF1A\u4E00\u4EBA\u8BF4\u51FA\u5224\u65AD\u2192\u53E6\u4E00\u4EBA\u53CD\u5BF9\u2192\u7B2C\u4E09\u4EBA\u62FF\u51FA\u8BC1\u636E\u6253\u4E24\u4E2A\u4EBA\u7684\u8138\u3002",
  constraints: [
    "\u6BCF250-350\u5B57\u4E00\u6B21\u4FE1\u606F\u53CD\u54AC\uFF0C\u5343\u5B57\u22653\u4E2A",
    "\u53CD\u54AC\u5FC5\u987B\u5177\u4F53\uFF08\u5177\u4F53\u4EC0\u4E48\u4E0D\u5BF9\uFF09\uFF0C\u7981\u6B62\u300C\u4F3C\u4E4E/\u597D\u50CF/\u54EA\u91CC\u4E0D\u5BF9\u300D\u7A7A\u6CDB\u53CD\u54AC",
    "\u53CD\u54AC\u540E\u7ACB\u523B\u63A5\u8EAB\u4F53\u53CD\u5E94\uFF0C\u4E0D\u505C\u987F\u89E3\u91CA",
    "\u5927\u5C0F\u53CD\u54AC\u4EA4\u66FF\uFF0C\u907F\u514D\u8FDE\u7EED\u5927\u53CD\u8F6C\u5BFC\u81F4\u75B2\u52B3",
    "\u7981\u6B62\u8FDE\u7EED400\u5B57\u65E0\u8F6C\u6298/\u65E0\u610F\u5916/\u65E0\u65B0\u53D1\u73B0",
    "\u5BF9\u8BDD\u4E2D\u4E5F\u8981\u6709\u78B0\u649E\u548C\u53CD\u54AC"
  ],
  examples: [
    {
      text: "\uFF08\u53CD\u54AC\u8282\u594F\u793A\u8303\uFF0C\u7EA61200\u5B576\u6B21\u53CD\u54AC\uFF09\n\n\u8001\u8303\u8BF4\u522B\u51FF\u4E86\u3002\u2192\u6797\u6DF1\u4EE5\u4E3A\u4ED6\u80C6\u5C0F\uFF08\u521D\u59CB\u5224\u65AD\uFF09\n\u2192\u6478\u5230\u7EB9\u8DEF\u4E0D\u50CF\u51FF\u75D5\uFF08\u53CD\u54AC1\uFF1A\u7EC6\u8282\u5F02\u5E38\uFF09\n\u2192\u8001\u8303\u624B\u521A\u8D34\u4E0A\u53BB\u5C31\u7F29\u56DE\u6765\uFF0C\u50CF\u6478\u5230\u70EB\u7684\uFF08\u53CD\u54AC2\uFF1A\u8001\u8303\u53CD\u5E94\u4E0D\u5BF9\uFF09\n\u2192\u63D0\u5230\u9648\u516D\uFF08\u53CD\u54AC3\uFF1A\u9648\u516D\u7684\u540D\u5B57\u51FA\u73B0\uFF0C\u4E0D\u662F\u843D\u77F3\uFF09\n\u2192\u8E29\u5230\u534A\u5757\u53F7\u724C\uFF0C\u6570\u5B576\uFF08\u53CD\u54AC4\uFF1A\u9648\u516D\u7684\u53F7\u724C\u5728\u8FD9\u91CC\uFF09\n\u2192\u58C1\u52A8\u4E86\uFF0C\u9ED1\u8272\u6DB2\u4F53\u6E17\u51FA\u6765\uFF08\u53CD\u54AC5\uFF1A\u5371\u9669\u5347\u7EA7\uFF09\n\u2192\u6DB2\u7403\u6EB6\u89E3\u53F7\u724C\uFF0C\u5F00\u59CB\u722C\uFF08\u53CD\u54AC6\uFF1A\u4E0D\u662F\u6C34\uFF0C\u662F\u6D3B\u7684\uFF09\n\u2192\u62D0\u5F2F\u5904\u5168\u662F\u7EB9\u8DEF\uFF08\u7AE0\u672B\u5927\u53CD\u54AC/\u94A9\u5B50\uFF09",
      note: "\u5BC6\u96C6\u53CD\u54AC\u8282\u594F\uFF1A\u6BCF200\u5B57\u5DE6\u53F3\u4E00\u6B21\u5C0F\u98A0\u8986\uFF0C\u5C42\u5C42\u5347\u7EA7\uFF0C\u8BFB\u8005\u6839\u672C\u505C\u4E0D\u4E0B\u6765"
    }
  ],
  threshold_overrides: {
    twistFrequency: "dense",
    minTwistsPer1000: 3,
    maxConsecutiveNoTwist: 3
  },
  radar_weights: {
    bodyReaction: 1.2,
    sensorySignal: 1.1,
    action: 1.2,
    emotion: 1.1,
    infoAdvance: 1.5,
    twistFrequency: 1.5,
    hookStrength: 1.2
  }
};

