      text: "\u60A6\u6765\u5BA2\u6808\u7684\u5927\u5802\u91CC\uFF0C\u4EBA\u58F0\u9F0E\u6CB8\u3002\n\n\u9760\u7A97\u7684\u4E00\u5F20\u684C\u5B50\u65C1\u5750\u7740\u4E00\u4E2A\u9752\u886B\u5E74\u8F7B\u4EBA\uFF0C\u9762\u524D\u6446\u7740\u4E00\u58F6\u9152\u3001\u4E24\u789F\u5C0F\u83DC\uFF0C\u5374\u81EA\u59CB\u81F3\u7EC8\u6CA1\u52A8\u51E0\u7B77\u5B50\u3002\u4ED6\u7684\u76EE\u5149\u65F6\u4E0D\u65F6\u98D8\u5411\u95E8\u53E3\uFF0C\u53F3\u624B\u59CB\u7EC8\u642D\u5728\u8170\u95F4\u90A3\u67C4\u4E0D\u8D77\u773C\u7684\u94C1\u5251\u4E0A\u3002\n\n\u201C\u5C0F\u4E8C\uFF0C\u7ED3\u8D26\u3002\u201D\n\n\u4ED6\u653E\u4E0B\u4E00\u952D\u788E\u94F6\u5B50\uFF0C\u521A\u8981\u8D77\u8EAB\uFF0C\u95E8\u5916\u7A81\u7136\u9A6C\u8E44\u58F0\u5927\u4F5C\uFF0C\u4E00\u961F\u94C1\u7532\u9A91\u5175\u75BE\u9A70\u800C\u81F3\uFF0C\u5728\u5BA2\u6808\u95E8\u524D\u9F50\u5237\u5237\u52D2\u4F4F\u7F30\u7EF3\u3002\u4E3A\u9996\u7684\u519B\u5B98\u7FFB\u8EAB\u4E0B\u9A6C\uFF0C\u624B\u6301\u4E00\u5377\u660E\u9EC4\u8272\u7684\u5377\u8F74\uFF0C\u5927\u6B65\u8D70\u8FDB\u5BA2\u6808\u3002\n\n\u201C\u5211\u90E8\u7F09\u62FF\u8981\u72AF\uFF01\u95F2\u6742\u4EBA\u7B49\u56DE\u907F\uFF01\u201D\n\n\u5927\u5802\u91CC\u77AC\u95F4\u5B89\u9759\u4E0B\u6765\u3002\u9752\u886B\u5E74\u8F7B\u4EBA\u7684\u77B3\u5B54\u5FAE\u5FAE\u4E00\u7F29\uFF0C\u624B\u6307\u5728\u5251\u9798\u4E0A\u8F7B\u8F7B\u6572\u4E86\u4E09\u4E0B\u2014\u2014\u8FD9\u662F\u6C5F\u6E56\u4EBA\u793A\u8B66\u7684\u6697\u53F7\u3002\n\n\u4ED6\u6CE8\u610F\u5230\uFF0C\u89D2\u843D\u91CC\u4E00\u4E2A\u6234\u6597\u7B20\u7684\u559D\u8336\u4EBA\uFF0C\u624B\u5DF2\u7ECF\u6084\u6084\u63A2\u5165\u4E86\u6000\u4E2D\u3002",
      note: "\u5386\u53F2\u67B6\u7A7A\u8BCD\u5E93\u793A\u4F8B\uFF1A\u5BA2\u6808/\u5C0F\u4E8C/\u788E\u94F6\u5B50/\u9A6C\u8E44/\u94C1\u7532\u9A91\u5175/\u5211\u90E8/\u5251\u9798/\u6C5F\u6E56\u4EBA/\u6597\u7B20\u7B49\u53E4\u4EE3\u6B66\u4FA0\u8BCD\u6C47\u81EA\u7136\u878D\u5165"
