      text: "\u51CC\u6668\u4E09\u70B9\u5341\u4E03\u5206\u3002\n\n\u6211\u88AB\u5C3F\u618B\u9192\uFF0C\u6478\u7D22\u7740\u4E0B\u4E86\u5E8A\u3002\u8D70\u5ECA\u91CC\u6F06\u9ED1\u4E00\u7247\uFF0C\u6211\u6CA1\u5F00\u706F\u2014\u2014\u6015\u5435\u9192\u8001\u5A46\u5B69\u5B50\u3002\n\n\u536B\u751F\u95F4\u5728\u8D70\u5ECA\u5C3D\u5934\u3002\u6211\u5149\u7740\u811A\u8E29\u5728\u5730\u677F\u4E0A\uFF0C\u5730\u677F\u51B0\u51C9\u523A\u9AA8\uFF0C\u8FD9\u5F88\u5947\u602A\uFF0C\u867D\u7136\u5DF2\u7ECF\u5165\u79CB\uFF0C\u4F46\u5730\u6696\u4E00\u76F4\u5F00\u7740\u3002\n\n\u8D70\u5230\u4E00\u534A\uFF0C\u6211\u505C\u4F4F\u4E86\u3002\n\n\u8EAB\u540E\u4F20\u6765\u811A\u6B65\u58F0\u3002\n\n\u5F88\u8F7B\uFF0C\u5F88\u6162\uFF0C\u662F\u8D64\u811A\u8E29\u5728\u5730\u677F\u4E0A\u7684\u58F0\u97F3\u3002\u55D2\u3001\u55D2\u3001\u55D2\u2026\u2026\n\n\u6211\u7684\u5BD2\u6BDB\u4E00\u4E0B\u5B50\u7AD6\u4E86\u8D77\u6765\u3002\u8001\u5A46\u5B69\u5B50\u90FD\u5728\u5367\u5BA4\u91CC\u7761\u89C9\uFF0C\u8FD9\u4E2A\u65F6\u95F4\u8C01\u4F1A\u5728\u8D70\u5ECA\u4E0A\uFF1F\n\n\u6211\u4E0D\u6562\u56DE\u5934\u3002\n\n\u811A\u6B65\u58F0\u8D8A\u6765\u8D8A\u8FD1\uFF0C\u6211\u80FD\u611F\u89C9\u5230\u4E00\u80A1\u9634\u51B7\u7684\u6C14\u606F\u4ECE\u80CC\u540E\u903C\u8FD1\uFF0C\u50CF\u662F\u6709\u4EBA\u628A\u4E00\u5757\u51B0\u8D34\u5728\u4E86\u6211\u7684\u540E\u9888\u4E0A\u3002\u7136\u540E\uFF0C\u4E00\u4E2A\u58F0\u97F3\u5728\u6211\u8033\u8FB9\u8F7B\u8F7B\u54CD\u8D77\u2014\u2014\n\n\u662F\u4E00\u4E2A\u5973\u4EBA\u7684\u58F0\u97F3\uFF0C\u53C8\u7EC6\u53C8\u5C16\uFF0C\u50CF\u662F\u4ECE\u5F88\u8FDC\u5F88\u8FDC\u7684\u5730\u65B9\u4F20\u6765\uFF1A\n\n\u300C\u4F60\u2026\u2026\u770B\u89C1\u6211\u5B69\u5B50\u4E86\u5417\uFF1F\u300D",
      note: "\u6050\u6016\u8BCD\u5E93\u793A\u4F8B\uFF1A\u51CC\u6668/\u9ED1\u6697/\u8D64\u811A/\u51B0\u51C9/\u811A\u6B65\u58F0/\u5BD2\u6BDB/\u9634\u51B7/\u5973\u4EBA\u58F0\u97F3\u7B49\u6050\u6016\u5143\u7D20\uFF0C\u672A\u77E5\u6050\u60E7\u6BD4\u76F4\u63A5\u89C1\u9B3C\u66F4\u5413\u4EBA"
