      text: "\u8840\u8165\u5473\u8FD8\u6CA1\u6563\u3002\n\n\u9648\u9ED8\u8E72\u5728\u5C38\u4F53\u65C1\u8FB9\uFF0C\u6234\u4E0A\u4E73\u80F6\u624B\u5957\u3002\u6B7B\u8005\u662F\u4E00\u540D\u4E2D\u5E74\u7537\u6027\uFF0C\u4EF0\u9762\u8EBA\u5728\u5BA2\u5385\u7684\u5730\u6BEF\u4E0A\uFF0C\u80F8\u53E3\u6709\u4E00\u5904\u5200\u4F24\uFF0C\u8840\u8FF9\u4EE5\u4ED6\u4E3A\u4E2D\u5FC3\u5448\u653E\u5C04\u72B6\u55B7\u6E85\uFF0C\u5728\u767D\u8272\u5899\u58C1\u4E0A\u753B\u51FA\u4E00\u5E45\u523A\u76EE\u7684\u56FE\u6848\u3002\n\n\u201C\u6B7B\u4EA1\u65F6\u95F4\u5927\u7EA6\u5728\u6628\u665A\u5341\u70B9\u5230\u51CC\u6668\u4E24\u70B9\u4E4B\u95F4\u3002\u201D\u6CD5\u533B\u8E72\u5728\u53E6\u4E00\u8FB9\uFF0C\u6307\u7740\u5C38\u4F53\u8116\u9888\u5904\u7684\u7D2B\u7EA2\u8272\u6591\u5757\uFF0C\u201C\u5C38\u6591\u5DF2\u7ECF\u56FA\u5B9A\uFF0C\u5C38\u50F5\u5F00\u59CB\u7F13\u89E3\u3002\u81F4\u547D\u4F24\u662F\u4E00\u5200\u6BD9\u547D\uFF0C\u51F6\u5668\u662F\u5355\u5203\u9510\u5668\uFF0C\u5BBD\u5EA6\u5927\u7EA6\u4E09\u5398\u7C73\uFF0C\u4ECE\u808B\u9AA8\u95F4\u9699\u523A\u5165\u5FC3\u810F\u3002\u201D\n\n\u9648\u9ED8\u7684\u76EE\u5149\u4ECE\u5C38\u4F53\u79FB\u5F00\uFF0C\u626B\u8FC7\u6574\u4E2A\u623F\u95F4\u3002\u95E8\u7A97\u5B8C\u597D\uFF0C\u6CA1\u6709\u64AC\u52A8\u75D5\u8FF9\u3002\u8336\u51E0\u4E0A\u6709\u4E24\u4E2A\u8336\u676F\uFF0C\u4E00\u676F\u8FD8\u5269\u534A\u676F\u51C9\u8336\uFF0C\u53E6\u4E00\u676F\u51E0\u4E4E\u6CA1\u52A8\u3002\n\n\u201C\u5BC6\u5BA4\uFF1F\u201D\u52A9\u624B\u5C0F\u738B\u4F4E\u58F0\u95EE\u3002\n\n\u9648\u9ED8\u6CA1\u8BF4\u8BDD\uFF0C\u4ED6\u6CE8\u610F\u5230\u4E00\u4EF6\u5947\u602A\u7684\u4E8B\u2014\u2014\u6B7B\u8005\u53F3\u624B\u7684\u98DF\u6307\u548C\u62C7\u6307\u4E0A\u6CBE\u7740\u4E00\u4E9B\u7070\u767D\u8272\u7684\u7C89\u672B\uFF0C\u4F46\u4ED6\u5BB6\u91CC\u6CA1\u6709\u4EFB\u4F55\u9762\u7C89\u6216\u7C7B\u4F3C\u7684\u4E1C\u897F\u3002\n\n\u90A3\u662F\u6307\u7EB9\u7C89\u3002\n\n\u6709\u4EBA\u5728\u8B66\u5BDF\u6765\u4E4B\u524D\uFF0C\u5DF2\u7ECF\u64E6\u62ED\u8FC7\u73B0\u573A\u4E86\u3002",
