      text: '\u8230\u6865\u7684\u7EA2\u8272\u8B66\u62A5\u706F\u75AF\u72C2\u65CB\u8F6C\uFF0C\u6620\u5728\u6BCF\u4E2A\u4EBA\u8138\u4E0A\u3002\n\n\u300C\u654C\u8230\u8DC3\u8FC1\u5B8C\u6210\uFF0C\u4E09\u8258\u5DE1\u6D0B\u8230\uFF0C\u8DDD\u79BB\u5341\u4E8C\u4E07\u516C\u91CC\uFF01\u300D\n\n\u9648\u8230\u957F\u731B\u5730\u63E1\u7D27\u6307\u6325\u6905\u7684\u6276\u624B\uFF0C\u795E\u7ECF\u63A5\u53E3\u5728\u540E\u9888\u5904\u5FAE\u5FAE\u53D1\u70EB\u2014\u2014"\u81F4\u8FDC\u53F7"\u7684AI\u6B63\u5728\u5C06\u6218\u672F\u6570\u636E\u76F4\u63A5\u6CE8\u5165\u4ED6\u7684\u89C6\u89C9\u76AE\u5C42\u3002\u4E0B\u4E00\u79D2\uFF0CHUD\u5728\u4ED6\u89C6\u7F51\u819C\u4E0A\u5C55\u5F00\uFF0C\u4E09\u8258\u654C\u8230\u7684\u8F6E\u5ED3\u3001\u62A4\u76FE\u503C\u3001\u6B66\u5668\u53C2\u6570\u5168\u90E8\u4EE5\u534A\u900F\u660E\u7684\u56FE\u6807\u60AC\u6D6E\u5728\u89C6\u91CE\u4E2D\u3002\n\n\u300C\u5168\u8230\u4E00\u7EA7\u6218\u5907\uFF0C\u542F\u52A8\u80FD\u91CF\u62A4\u76FE\uFF0C\u5DE6\u6EE1\u8235\uFF01\u300D\n\n\u5F15\u64CE\u5BA4\u7684\u4F4E\u9891\u55E1\u9E23\u9AA4\u7136\u5347\u9AD8\uFF0C\u4EBA\u5DE5\u91CD\u529B\u56E0\u4E3A\u8FC7\u8F7D\u800C\u6CE2\u52A8\u4E86\u4E00\u77AC\uFF0C\u51E0\u4E2A\u6CA1\u7CFB\u5B89\u5168\u5E26\u7684\u8239\u5458\u8E09\u8DC4\u4E86\u4E00\u4E0B\u3002\n\n\u300C\u4E3B\u70AE\u5145\u80FD\u5B8C\u6BD5\uFF0C\u9501\u5B9A\u5B8C\u6210\uFF01\u300D\u6B66\u5668\u5B98\u7684\u58F0\u97F3\u4ECE\u901A\u8BAF\u5668\u91CC\u4F20\u6765\uFF0C\u5E26\u7740\u7535\u6D41\u6742\u97F3\u3002\n\n\u9648\u8230\u957F\u76EF\u7740\u89C6\u91CE\u4E2D\u8D8A\u6765\u8D8A\u8FD1\u7684\u7EA2\u8272\u5149\u70B9\uFF0C\u6DF1\u5438\u4E00\u53E3\u6C14\u3002\n\n\u300C\u5F00\u706B\u3002\u300D\n\n\u8230\u4F53\u5FAE\u5FAE\u4E00\u9707\uFF0C\u4E00\u9053\u84DD\u767D\u8272\u7684\u79BB\u5B50\u5149\u675F\u4ECE\u4E3B\u70AE\u53E3\u55B7\u6D8C\u800C\u51FA\uFF0C\u6495\u88C2\u4E86\u6F06\u9ED1\u7684\u592A\u7A7A\u3002',
      note: "\u79D1\u5E7B\u8BCD\u5E93\u793A\u4F8B\uFF1A\u8230\u6865/\u8DC3\u8FC1/\u5DE1\u6D0B\u8230/\u795E\u7ECF\u63A5\u53E3/HUD/AI/\u80FD\u91CF\u62A4\u76FE/\u5F15\u64CE/\u79BB\u5B50\u70AE/\u4E3B\u70AE\u5145\u80FD\u7B49\u79D1\u5E7B\u8BCD\u6C47\u81EA\u7136\u878D\u5165"
