    {
      text: "\u665A\u4E0A\u4E5D\u70B9\uFF0CCBD\u5199\u5B57\u697C\u7684\u706F\u5149\u8FD8\u4EAE\u7740\u4E00\u534A\u3002\n\n\u6797\u60A6\u76EF\u7740\u7535\u8111\u5C4F\u5E55\u4E0A\u7684PPT\uFF0C\u773C\u775B\u5E72\u6DA9\u5F97\u5389\u5BB3\u3002\u5979\u63C9\u4E86\u63C9\u592A\u9633\u7A74\uFF0C\u7AEF\u8D77\u5DF2\u7ECF\u51C9\u900F\u7684\u5496\u5561\u559D\u4E86\u4E00\u53E3\u2014\u2014\u82E6\u5473\u8BA9\u5979\u7A0D\u5FAE\u6E05\u9192\u4E86\u4E00\u4E9B\u3002\n\n\u624B\u673A\u5C4F\u5E55\u4EAE\u4E86\u4E00\u4E0B\uFF0C\u662F\u5988\u5988\u53D1\u6765\u7684\u5FAE\u4FE1\uFF1A\u300C\u5468\u672B\u56DE\u5BB6\u5417\uFF1F\u7ED9\u4F60\u7096\u4E86\u6C64\u3002\u300D\n\n\u5979\u6253\u5B57\u56DE\u4E86\u53E5\u300C\u770B\u60C5\u51B5\uFF0C\u8981\u52A0\u73ED\u300D\uFF0C\u53D1\u9001\uFF0C\u7136\u540E\u628A\u624B\u673A\u6263\u5728\u684C\u9762\u4E0A\u3002\n\n\u65C1\u8FB9\u5DE5\u4F4D\u7684\u5F20\u4F1F\u4F38\u4E86\u4E2A\u61D2\u8170\uFF1A\u300C\u8FD8\u4E0D\u8D70\uFF1F\u6211\u5148\u64A4\u4E86\uFF0C\u672B\u73ED\u8F66\u5FEB\u6CA1\u4E86\u3002\u300D\n\n\u300C\u4F60\u4EEC\u5148\u8D70\u5427\uFF0C\u6211\u6539\u5B8C\u8FD9\u7248\u65B9\u6848\u5C31\u8D70\u3002\u300D\u6797\u60A6\u52C9\u5F3A\u7B11\u4E86\u7B11\u3002\n\n\u952E\u76D8\u58F0\u91CD\u65B0\u5728\u7A7A\u65F7\u7684\u529E\u516C\u533A\u54CD\u8D77\u3002\u7A97\u5916\uFF0C\u57CE\u5E02\u7684\u9713\u8679\u706F\u6620\u5728\u73BB\u7483\u5E55\u5899\u4E0A\uFF0C\u7EA2\u7684\u84DD\u7684\u7EFF\u7684\uFF0C\u50CF\u4E00\u5E45\u51B7\u6F20\u7684\u753B\u3002\n\n\u5979\u70B9\u5F00\u5916\u5356APP\uFF0C\u70B9\u4E86\u4E00\u4EFD\u9EBB\u8FA3\u70EB\u2014\u2014\u8FD9\u5DF2\u7ECF\u662F\u5979\u8FD9\u5468\u8FDE\u7EED\u7B2C\u56DB\u5929\u5403\u5916\u5356\u4E86\u3002",
      note: "\u90FD\u5E02\u73B0\u4EE3\u8BCD\u5E93\u793A\u4F8B\uFF1APPT/\u5496\u5561/\u5FAE\u4FE1/\u52A0\u73ED/\u5916\u5356/CBD/\u9713\u8679\u706F/\u952E\u76D8/\u672B\u73ED\u8F66/APP\u7B49\u73B0\u4EE3\u8BCD\u6C47\u81EA\u7136\u878D\u5165"
    }
