  examples: [
    {
      text: "\u6B7B\u8005\u7684\u624B\u6307\u52A8\u4E86\u4E00\u4E0B\u3002\n\n\u9648\u8B66\u5B98\u8E72\u4E0B\u53BB\uFF0C\u6234\u624B\u5957\u7684\u624B\u78B0\u4E86\u78B0\u90A3\u6839\u624B\u6307\u3002\u50F5\u786C\u7684\u3002\u5DF2\u7ECF\u6B7B\u4E86\u81F3\u5C11\u516D\u4E2A\u5C0F\u65F6\uFF0C\u5C38\u50F5\u90FD\u51FA\u6765\u4E86\u3002\n\n\u662F\u4ED6\u770B\u9519\u4E86\u3002\n\n\u4ED6\u7AD9\u8D77\u8EAB\uFF0C\u76EE\u5149\u626B\u8FC7\u51FA\u79DF\u5C4B\u3002\u95E8\u7A97\u53CD\u9501\uFF0C\u94A5\u5319\u5728\u6B7B\u8005\u88E4\u515C\u91CC\uFF0C\u684C\u4E0A\u6709\u4E00\u676F\u559D\u4E86\u4E00\u534A\u7684\u6C34\uFF0C\u6C34\u91CC\u6709\u5B89\u7720\u836F\u3002\u5178\u578B\u7684\u81EA\u6740\u3002\n\n\u4E0D\u5BF9\u3002\n\n\u4ED6\u91CD\u65B0\u8E72\u4E0B\u53BB\uFF0C\u7FFB\u5F00\u6B7B\u8005\u7684\u773C\u76AE\u3002\n\n\u77B3\u5B54\u662F\u7F29\u5C0F\u7684\u3002\n\n\u5B89\u7720\u836F\u4E2D\u6BD2\u6B7B\u4EA1\uFF0C\u77B3\u5B54\u5E94\u8BE5\u662F\u6563\u5927\u7684\u3002\n\n\u8FD9\u4E0D\u662F\u81EA\u6740\u3002",
      note: "\u60AC\u7591V3.1\u5F00\u5934\uFF1A\u7B2C\u4E00\u53E5\u5F02\u5E38\uFF08\u624B\u6307\u52A8\u4E86\uFF09\u2192\u8EAB\u4F53\u5728\u573A\uFF08\u8E72\u3001\u78B0\uFF09\u2192\u53CD\u54AC\uFF08\u770B\u9519\u4E86/\u5C38\u50F5\uFF09\u2192\u518D\u53CD\u54AC\uFF08\u4E0D\u5BF9/\u77B3\u5B54\u7F29\u5C0F\uFF09\u2192\u94A9\u5B50\uFF08\u4E0D\u662F\u81EA\u6740\uFF09\u3002"
    }
  ],
